INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21490, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过照顾让东西长出来。", "primary_collocate": null, "pronunciation": "péi yù chū", "ipa": "pʰei˧˥ y˥˩ ʈʂʰu˥", "syllable_count": 3, "sentences": [{"text": "奶奶每天浇水，培育出一盆好看的花。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用心照顾，培育出了几棵小树。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在阳台上培育出了绿色的青菜。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸花了两年培育出这棵苹果树。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过细心照顾，他培育出了嫩绿的豆芽。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她天天浇水，培育出一小片绿色的草。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场主在田里培育出金黄的玉米。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在院子里培育出很多红色的月季。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们培育出了一盆健康的豆苗。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要天天照顾，你也能培育出漂亮的草莓。", "target_word": "培育出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "培育出了", "label": "体标"}], "register": "中性", "sense_fingerprint": "靠照顾让植物长出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99e3e928-3fb0-4690-a235-40ae1f64ddce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "培育出", "is_correct": true, "explanation": "培育出：靠照顾让花长出来，符合“奶奶每天浇水，培育出一盆好看的花”的句意。"}, {"text": "切出", "is_correct": false, "explanation": "语义：切只能把物体分开，不能让花生长出来。"}, {"text": "写出", "is_correct": false, "explanation": "搭配：写出多搭配文字或作品，不能搭配“一盆花”。"}, {"text": "吹出", "is_correct": false, "explanation": "语义：吹是用气流推动，不能让一盆花长出来。"}], "explanations": {"培育出": "培育出：靠照顾让花长出来，符合“奶奶每天浇水，培育出一盆好看的花”的句意。", "切出": "语义：切只能把物体分开，不能让花生长出来。", "写出": "搭配：写出多搭配文字或作品，不能搭配“一盆花”。", "吹出": "语义：吹是用气流推动，不能让一盆花长出来。"}, "sentence_index": 0, "correct_answer": "培育出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂花了两年培育出这辆汽车。", "explanation": "这里应该用〈制造〉。培育用于生物和新品种，机器产品要用制造。"}, {"text": "科学家花了两年培育出一种新药。", "explanation": "这里应该用〈研制〉。培育用于生物品种或人才，药品要用研制。"}, {"text": "工人们花了两年培育出一台电脑。", "explanation": "这里应该用〈组装〉。培育用于生物和品种，电脑这类机器要用组装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '424c24d8-0068-4da5-9c55-1eed25e62be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培育出", "is_correct": true, "explanation": "培育出：经过种植和照顾让作物长出来，符合“农场主在田里培育出金黄的玉米”的句意。"}, {"text": "发出", "is_correct": false, "explanation": "搭配：发出多搭配声音、光等，不能搭配“金黄的玉米”。"}, {"text": "放射出", "is_correct": false, "explanation": "语义：放射出的是光或能量，玉米不能被放射出来。"}, {"text": "讲出", "is_correct": false, "explanation": "语义：讲出的是话语，不能指作物生长出来。"}], "explanations": {"培育出": "培育出：经过种植和照顾让作物长出来，符合“农场主在田里培育出金黄的玉米”的句意。", "发出": "搭配：发出多搭配声音、光等，不能搭配“金黄的玉米”。", "放射出": "语义：放射出的是光或能量，玉米不能被放射出来。", "讲出": "语义：讲出的是话语，不能指作物生长出来。"}, "sentence_index": 6, "correct_answer": "培育出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "设计师培育出一座漂亮的房子。", "explanation": "这里应该用〈设计〉。培育用于生物和品种，房屋要用设计或建造。"}, {"text": "裁缝培育出一件漂亮的衣服。", "explanation": "这里应该用〈缝制〉。培育不用于衣物，衣服要用缝制。"}, {"text": "酿酒师培育出一瓶香醇的酒。", "explanation": "这里应该用〈酿造〉。培育不用于饮品，酒要用酿造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '424c24d8-0068-4da5-9c55-1eed25e62be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天组装，培育出了一台红色的机器。", "corrected_sentence": "他每天组装，制造出了一台红色的机器。", "error_description": "错误：「培育」用于生物和品种，机器应用「制造」。错误形式：培育出了一台红色的机器；正确形式：制造出了一台红色的机器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '424c24d8-0068-4da5-9c55-1eed25e62be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工匠培育出了一座精致的楼房。", "corrected_sentence": "工匠建造了一座精致的楼房。", "error_description": "错误：「培育」用于生物和品种，楼房应用「建造」。错误形式：培育出了一座精致的楼房；正确形式：建造了一座精致的楼房。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '424c24d8-0068-4da5-9c55-1eed25e62be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
