INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "太阳晒到东西上。", "primary_collocate": null, "pronunciation": "rì shài", "ipa": "ʐ̩˥˩ ʂaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "红色的窗帘经过多年日晒，颜色变浅了。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机放在车里，日晒会让电池变热。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞可以挡住日晒。", "target_word": "日晒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日晒之后，鱼干变得又硬又香。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳台上的花怕日晒，要放到树下。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期日晒和风吹，让这块木板裂开了。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的海边，日晒特别强。", "target_word": "日晒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日晒过后的被子，睡起来很舒服。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的油漆最怕日晒，所以要停在阴凉处。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把稻谷放在院子里，靠日晒让它变干。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日晒雨淋", "label": "复合"}, {"form": "日曬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "太阳晒到东西上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77d44374-9130-4214-8484-34407e94bcda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日晒", "is_correct": true, "explanation": "正确：日晒指太阳晒到东西上，窗帘长期被晒，颜色就会变浅，符合句意。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻不会使窗帘褪色，“颜色变浅”不是冷冻造成的结果，句意不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：窗帘不是被烹饪的东西，“烹饪”与“颜色变浅”毫无关系。"}, {"text": "翻新", "is_correct": false, "explanation": "搭配：窗帘通常说“换”，不说“翻新”；而且翻新会让东西变新，与“颜色变浅”相反。"}], "explanations": {"日晒": "正确：日晒指太阳晒到东西上，窗帘长期被晒，颜色就会变浅，符合句意。", "冷冻": "语义：冷冻不会使窗帘褪色，“颜色变浅”不是冷冻造成的结果，句意不通。", "烹饪": "语义：窗帘不是被烹饪的东西，“烹饪”与“颜色变浅”毫无关系。", "翻新": "搭配：窗帘通常说“换”，不说“翻新”；而且翻新会让东西变新，与“颜色变浅”相反。"}, "sentence_index": 0, "correct_answer": "日晒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把湿毛巾放进烘干机里，靠日晒烘干。", "explanation": "这里应该用〈烘干〉。烘干靠机器加热，日晒靠太阳照射，烘干机里没有阳光，不能说“靠日晒烘干”。"}, {"text": "把肉放进冰箱，靠日晒保存。", "explanation": "这里应该用〈冷藏〉。冷藏靠低温保存，日晒靠太阳照射，冰箱里没有阳光，不能说“靠日晒保存”。"}, {"text": "这棵大树下很凉快，适合日晒。", "explanation": "这里应该用〈乘凉〉。乘凉是在大树的树荫下休息；日晒必须在阳光下进行，树下有阴影，所以“适合日晒”与“树下凉快”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24ea2e1e-6ad9-427a-893e-6fc57ee1efc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日晒", "is_correct": true, "explanation": "正确：日晒指太阳照射，夏天的海边阳光强，所以“特别强”指的是日晒。"}, {"text": "夜色", "is_correct": false, "explanation": "搭配：“夜色”指夜晚的景象，程度一般说“浓”，不说“特别强”，且与白天的日照语境不合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人的高矮，与海边的天气和日照无关，句意不通。"}, {"text": "冰雹", "is_correct": false, "explanation": "语义：冰雹多出现在寒冷的天气里，与夏天海边的强烈日照不符。"}], "explanations": {"日晒": "正确：日晒指太阳照射，夏天的海边阳光强，所以“特别强”指的是日晒。", "夜色": "搭配：“夜色”指夜晚的景象，程度一般说“浓”，不说“特别强”，且与白天的日照语境不合。", "身高": "语义：身高指人的高矮，与海边的天气和日照无关，句意不通。", "冰雹": "语义：冰雹多出现在寒冷的天气里，与夏天海边的强烈日照不符。"}, "sentence_index": 6, "correct_answer": "日晒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说这种药膏能很快治好日晒。", "explanation": "这里应该用〈晒伤〉。“治好”针对的是伤害，日晒只是照射的过程，不能被治好。"}, {"text": "阴天的时候，我们在院子里日晒。", "explanation": "这里应该用〈乘凉〉。阴天在院子里乘凉很自然；日晒必须有阳光直接照射，阴天没有直射的阳光，所以不能说“阴天日晒”。"}, {"text": "把湿衣服挂在屋里，靠日晒让它变干。", "explanation": "这里应该用〈晾干〉。晾干是把湿物挂在通风处自然变干，不需要阳光；日晒要靠太阳直接照射，屋里没有阳光，不能说“靠日晒让它变干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24ea2e1e-6ad9-427a-893e-6fc57ee1efc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木板把日晒了三年，颜色变深了。", "corrected_sentence": "这块木板被日晒了三年，颜色变深了。", "error_description": "把字句错误：“把”后须接受事宾语，这里“把”后直接接动词，缺少宾语。表示木板受晒，应用“被”字句，说“这块木板被日晒了三年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24ea2e1e-6ad9-427a-893e-6fc57ee1efc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的被子日晒了过，闻起来很香。", "corrected_sentence": "我的被子日晒过，闻起来很香。", "error_description": "体标错误：“日晒”后表示经历只用“过”，不能再加“了”，应说“日晒过”，不能说“日晒了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24ea2e1e-6ad9-427a-893e-6fc57ee1efc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把硬壳去掉，让里面的东西出来。", "primary_collocate": null, "pronunciation": "tuō ké", "ipa": "tʰwo˥ kʰɤ˧˥", "syllable_count": 2, "sentences": [{"text": "工人用机器给稻谷脱壳，得到大米。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花生要先脱壳，再放进锅里炒。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每天给几吨松子脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕麦脱壳以后，才可以磨成粉。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台小机器脱壳很快，一分钟能处理很多种子。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把晒干的稻谷送去脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葵花籽脱壳后，里面的籽仁又小又白。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "稻谷脱壳时要小心，别把米弄碎。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一台机器，专门给豆子脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新收的稻谷脱壳以后，颜色有点黄。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱了壳", "label": "体标"}, {"form": "脱壳机", "label": "复合"}], "register": "中性", "sense_fingerprint": "去掉谷物、种子等的硬壳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7262136-bedf-47a3-b4c0-59481b3c3d7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱壳", "is_correct": true, "explanation": "正确。脱壳：去掉稻谷的硬壳，与“得到大米”的结果相符。"}, {"text": "开采", "is_correct": false, "explanation": "搭配：“开采”用于矿产、资源，不能用于稻谷。"}, {"text": "编织", "is_correct": false, "explanation": "配价：“编织”需要丝线、竹条等材料作对象，稻谷不能作其对象。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：“熔化”指固体受热变为液体，与稻谷脱壳的加工结果不符。"}], "explanations": {"脱壳": "正确。脱壳：去掉稻谷的硬壳，与“得到大米”的结果相符。", "开采": "搭配：“开采”用于矿产、资源，不能用于稻谷。", "编织": "配价：“编织”需要丝线、竹条等材料作对象，稻谷不能作其对象。", "熔化": "语义：“熔化”指固体受热变为液体，与稻谷脱壳的加工结果不符。"}, "sentence_index": 0, "correct_answer": "脱壳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些苹果要先脱壳，再切成块。", "explanation": "这里应该用〈去皮〉。“脱壳”指去掉硬壳，苹果有皮而无硬壳，应说“去皮”。"}, {"text": "这些蔬菜要先脱壳，再下锅炒。", "explanation": "这里应该用〈脱水〉。“脱壳”指去掉硬壳，蔬菜没有硬壳，应说“脱水”去掉水分。"}, {"text": "秋天到了，树叶一片片脱壳了。", "explanation": "这里应该用〈脱落〉。树叶没有硬壳，“脱落”指掉下来，不能说脱壳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脱壳", "is_correct": true, "explanation": "正确。脱壳：去掉葵花籽的硬壳，露出籽仁，与“籽仁又小又白”相符。"}, {"text": "锻造", "is_correct": false, "explanation": "语义：“锻造”指金属加工，与葵花籽的处理不符。"}, {"text": "焊接", "is_correct": false, "explanation": "搭配：“焊接”用于金属等材料，不能用于葵花籽。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：“雕刻”指加工出花纹或形象，与“籽仁又小又白”的描述不符。"}], "explanations": {"脱壳": "正确。脱壳：去掉葵花籽的硬壳，露出籽仁，与“籽仁又小又白”相符。", "锻造": "语义：“锻造”指金属加工，与葵花籽的处理不符。", "焊接": "搭配：“焊接”用于金属等材料，不能用于葵花籽。", "雕刻": "语义：“雕刻”指加工出花纹或形象，与“籽仁又小又白”的描述不符。"}, "sentence_index": 6, "correct_answer": "脱壳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布要先脱壳，再染新颜色。", "explanation": "这里应该用〈脱色〉。“脱壳”指去掉硬壳，布料没有硬壳，应说“脱色”去掉原有颜色。"}, {"text": "这只鸡要先脱壳，再开膛。", "explanation": "这里应该用〈脱毛〉。鸡身上是毛，没有硬壳，不能用“脱壳”去掉鸡毛。"}, {"text": "这个玻璃杯要先脱壳，再擦干净。", "explanation": "这里应该用〈擦干净〉。玻璃杯没有保护壳，“脱壳”只指去掉硬质保护壳，应说“擦干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民用机器稻谷脱壳，再去卖。", "corrected_sentence": "农民用机器给稻谷脱壳，再去卖。", "error_description": "错误：“脱壳”的对象“稻谷”前缺少介词“给”，应说“给稻谷脱壳”，不能直接说“机器稻谷脱壳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "核桃了脱壳后，要尽快晒干。", "corrected_sentence": "核桃脱壳后，要尽快晒干。", "error_description": "错误：动态助词“了”不能放在动词“脱壳”之前，写成“了脱壳”。这里不需要“了”，应说“核桃脱壳后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
