INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一件事之后紧跟着另一件事发生。", "primary_collocate": null, "pronunciation": "suí hòu", "ipa": "suei˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "飞机落了地，随后我们坐车去酒店。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先洗了手，随后开始做饭。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯突然灭了，随后传来一声大叫。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥先到家，我随后也到了。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先敲了门，随后走了进去。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友发了信息，他随后就回电话了。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束了，随后是颁奖。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板先讲几句话，随后请大家吃饭。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风吹过，随后下起了大雨。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起笔，随后在纸上写了名字。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隨後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事之后紧跟着另一件事发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7262136-bedf-47a3-b4c0-59481b3c3d7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随后", "is_correct": true, "explanation": "正确。“随后”表示飞机落地之后紧接着坐车去酒店，与句中的先后顺序相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“飞机落了地”之后的连续动作不符。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“飞机落了地”这种瞬时结果搭配。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从未发生，与句中已安排的具体动作矛盾。"}], "explanations": {"随后": "正确。“随后”表示飞机落地之后紧接着坐车去酒店，与句中的先后顺序相符。", "偶尔": "语义：“偶尔”表示不常发生，与“飞机落了地”之后的连续动作不符。", "一直": "搭配：“一直”表示持续，不能与“飞机落了地”这种瞬时结果搭配。", "从不": "语义：“从不”表示从未发生，与句中已安排的具体动作矛盾。"}, "sentence_index": 0, "correct_answer": "随后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两人随后在同一秒钟跳了起来。", "explanation": "这里应该用〈同时〉。“随后”表示先后紧接，两人在同一秒跳起来应说“同时”。"}, {"text": "随后，我们先吃了饭。", "explanation": "这里应该用〈首先〉。“随后”需要前面已有事情发生，“先”表示最初，两者矛盾。"}, {"text": "他一边走路，随后一边打电话。", "explanation": "这里应该用〈同时〉。“随后”表示先后相继，一边走路一边打电话是同时进行的，应说“同时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随后", "is_correct": true, "explanation": "正确。“随后”表示比赛结束之后紧接着颁奖，与句中的先后顺序相符。"}, {"text": "事先", "is_correct": false, "explanation": "语义：“事先”表示在某事之前，与“比赛结束了”之后才颁奖的顺序相反。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”表示从未如此，不与即将发生的颁奖搭配。"}, {"text": "原先", "is_correct": false, "explanation": "语义：“原先”指原来的情况，与比赛结束后的颁奖顺序不符。"}], "explanations": {"随后": "正确。“随后”表示比赛结束之后紧接着颁奖，与句中的先后顺序相符。", "事先": "语义：“事先”表示在某事之前，与“比赛结束了”之后才颁奖的顺序相反。", "从来": "搭配：“从来”表示从未如此，不与即将发生的颁奖搭配。", "原先": "语义：“原先”指原来的情况，与比赛结束后的颁奖顺序不符。"}, "sentence_index": 6, "correct_answer": "随后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两位大臣随后同时入殿。", "explanation": "这里应该用〈一同〉。“随后”指一件接一件，两人同时入殿不能用“随后”。"}, {"text": "行军队伍的末尾随后却空无一人。", "explanation": "这里应删去〈随后〉。“随后”只表示时间先后，不能表示位置；删去后为“行军队伍的末尾却空无一人”。"}, {"text": "猫在前面跑，狗随后却先跑到了终点。", "explanation": "这里应删去〈随后〉，改为“猫在前面跑，狗却先跑到了终点”。“随后”指跟在后面，与“先跑到终点”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先写完作业，随后的出去散步。", "corrected_sentence": "我先写完作业，随后出去散步。", "error_description": "助词错误：“随后”是副词，作状语后不能加“的”，应说“随后出去散步”，不能说“随后的出去散步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她关上门，随后的拿起了包。", "corrected_sentence": "她关上门，随后拿起了包。", "error_description": "助词错误：“随后”是副词，作状语后不能加“的”，应说“随后拿起了包”，不能说“随后的拿起了包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
