INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "经过一段过程之后，出现的最后结果。", "primary_collocate": null, "pronunciation": "zuì zhōng", "ipa": "tsuei˥˩ tʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他努力了很久，最终成功了。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛最终以三比二结束。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们最终找到了回家的路。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想了很久，最终还是同意了。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨最终停了，我们出去玩。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过讨论，大家最终选了这个办法。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明最终没有去那家公司。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最终，他们赢得了比赛。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗最终回到了主人身边。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机最终在晚上十点到了。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "经过过程之后的最后结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73bdc592-5317-4323-ab99-fe56d44fcace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最终", "is_correct": true, "explanation": "“最终”表示经过努力后的最后结果，符合“努力了很久”之后成功的语境。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立刻，与“努力了很久”的时间过程矛盾。"}, {"text": "先", "is_correct": false, "explanation": "语义：“先”表示先后顺序，句中没有另一个动作，句意不通。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示催促，后面接的是要马上做的动作，不能用于已经发生的结果。"}], "explanations": {"最终": "“最终”表示经过努力后的最后结果，符合“努力了很久”之后成功的语境。", "马上": "语义：“马上”表示立刻，与“努力了很久”的时间过程矛盾。", "先": "语义：“先”表示先后顺序，句中没有另一个动作，句意不通。", "赶紧": "搭配：“赶紧”表示催促，后面接的是要马上做的动作，不能用于已经发生的结果。"}, "sentence_index": 0, "correct_answer": "最终"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最终，他吃了饭，再去工作。", "explanation": "这里应该用〈首先〉。“最终”表示结果出现在最后，后面不能接“再去工作”这样的后续动作。"}, {"text": "他最终一开始就放弃了，我们都很意外。", "explanation": "这里应该用〈一开始〉。“最终”表示结果出现在最后，与“一开始”的起点矛盾，应说“一开始就放弃了”。"}, {"text": "他最终刚才就走了，我没见到他。", "explanation": "这里应该用〈刚才〉。“最终”表示结果出现在最后，与“刚才”的过去时点矛盾，应说“刚才就走了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最终", "is_correct": true, "explanation": "“最终”表示结果在最后，符合“小明没有去那家公司”的结论。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示催促，不能与“没有去”组合，句子不通。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作正在进行，不能与“没有去”组合。"}, {"text": "特此", "is_correct": false, "explanation": "语域：“特此”是公文用语，用在日常叙述中不合适。"}], "explanations": {"最终": "“最终”表示结果在最后，符合“小明没有去那家公司”的结论。", "赶紧": "搭配：“赶紧”表示催促，不能与“没有去”组合，句子不通。", "正在": "搭配：“正在”表示动作正在进行，不能与“没有去”组合。", "特此": "语域：“特此”是公文用语，用在日常叙述中不合适。"}, "sentence_index": 6, "correct_answer": "最终"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一听到铃声，他最终飞快地冲出了教室。", "explanation": "这里应该用〈立即〉。“最终”表示结果出现在最后，与“一听到铃声”就行动的即时反应矛盾，应说“立即”。"}, {"text": "他最终在三秒钟内就算出了结果。", "explanation": "这里应该用〈很快〉。“最终”表示结果出现在最后，与“三秒钟内”这样的短时间矛盾，应说“很快”。"}, {"text": "他最终马上回了我的消息。", "explanation": "这里应该用〈随即〉代替“最终马上”。“最终”表示结果出现在最后，与“马上”的即时回应矛盾；“随即”表示紧接着发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过多次尝试，我们终于最终找到了答案。", "corrected_sentence": "经过多次尝试，我们最终找到了答案。", "error_description": "错误：“终于”和“最终”意思重复，都表示结果出现在最后，不能叠在同一个动词前面。应说“我们最终找到了答案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个小孩终于最终没有回来。", "corrected_sentence": "那个小孩最终没有回来。", "error_description": "错误：“终于”和“最终”意思重复，不能同时用在“没有回来”前面。应说“那个小孩最终没有回来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
