INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生豆就是没有煮过的豆子。", "primary_collocate": null, "pronunciation": "shēng dòu", "ipa": "ʂɤŋ˥ tou˥˩", "syllable_count": 2, "sentences": [{"text": "生豆就是没有煮过的豆子。", "target_word": "生豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生豆不能直接吃，要先煮熟。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把生豆放进水里泡了一夜。", "target_word": "生豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些生豆太硬了，要煮很久。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煮好的豆子很软，可是生豆很硬。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做豆浆以前，要先把生豆泡一泡。", "target_word": "生豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了生豆，肚子很不舒服。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶买了一袋生豆，准备煮豆汤。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生豆煮熟以后，颜色和味道都变了。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友不要吃生豆，一定要煮熟再吃。", "target_word": "生豆", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗生豆", "label": "量词"}, {"form": "一袋生豆", "label": "量词"}], "register": "中性", "sense_fingerprint": "没有煮熟的普通豆子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d2a2b0-046a-431e-85e1-9cfdfaec8fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生豆", "is_correct": true, "explanation": "正确。“没有煮过的豆子”即指生豆，与句中定义一致。"}, {"text": "熟豆", "is_correct": false, "explanation": "语义：熟豆已经煮过，与“没有煮过的豆子”正好相反。"}, {"text": "豆浆", "is_correct": false, "explanation": "语义：豆浆是把豆子煮过、磨碎后制成的饮料，不符合“没有煮过”。"}, {"text": "豆沙", "is_correct": false, "explanation": "搭配：豆沙是煮烂压碎后加糖制成的馅料，不能用“就是没有煮过的豆子”来定义。"}], "explanations": {"生豆": "正确。“没有煮过的豆子”即指生豆，与句中定义一致。", "熟豆": "语义：熟豆已经煮过，与“没有煮过的豆子”正好相反。", "豆浆": "语义：豆浆是把豆子煮过、磨碎后制成的饮料，不符合“没有煮过”。", "豆沙": "搭配：豆沙是煮烂压碎后加糖制成的馅料，不能用“就是没有煮过的豆子”来定义。"}, "sentence_index": 0, "correct_answer": "生豆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些生豆很软，可以直接吃。", "explanation": "这里应该用〈熟豆〉。生豆没有煮过，既不软，也不能直接吃。"}, {"text": "这棵生豆太硬了，要煮很久。", "explanation": "这里应该用〈颗〉。豆子按粒计量，“棵”只用于树木等植物。"}, {"text": "这些生豆太甜了，别吃太多。", "explanation": "这里应该用〈豆沙〉。生豆没有甜味，不能说“太甜了”，豆沙才是加糖煮制后的甜食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生豆", "is_correct": true, "explanation": "正确。生豆没有煮过，吃下去会让肚子不舒服，符合语境。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“吃”不能与“水”搭配，应说“喝”。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“吃”一般不说“吃汤”，应说“喝汤”。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：饮料通常说“喝”，不说“吃”。"}], "explanations": {"生豆": "正确。生豆没有煮过，吃下去会让肚子不舒服，符合语境。", "水": "搭配：“吃”不能与“水”搭配，应说“喝”。", "汤": "搭配：“吃”一般不说“吃汤”，应说“喝汤”。", "饮料": "搭配：饮料通常说“喝”，不说“吃”。"}, "sentence_index": 6, "correct_answer": "生豆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "生豆很嫩，买回家可以直接吃。", "explanation": "这里应该用〈豆腐〉。生豆没有煮过，既不嫩，也不能直接吃。"}, {"text": "生豆很甜，是我最爱吃的点心。", "explanation": "这里应该用〈绿豆糕〉。生豆没有甜味，也不是点心，不能这样描述。"}, {"text": "生豆很凉，夏天可以直接吃。", "explanation": "这里应该用〈冰棍〉。生豆不凉，也不能直接吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们买了三只生豆，准备做豆浆。", "corrected_sentence": "我们买了三袋生豆，准备做豆浆。", "error_description": "量词错误：“只”多用于动物、成对物品中的单个等，不用于计量生豆；成袋的生豆应用“袋”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把一条生豆泡在水里了。", "corrected_sentence": "妈妈把一袋生豆泡在水里了。", "error_description": "量词错误：“生豆”应搭配量词“袋”，不能用“条”（“条”多用于细长的东西）。成袋的生豆应说“一袋生豆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
