INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21524, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "表示从一个地方到另一个地方，比如走过一条路。", "primary_collocate": null, "pronunciation": "jīng", "ipa": "tɕiŋ˥", "syllable_count": 1, "sentences": [{"text": "火车经南京开往上海。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机经香港飞到了东京。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们经这条小路回学校。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从北京出发，经天津到济南。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车经这座桥开到了对面。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船经海口开往三亚。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从家去学校，经一个公园就到了。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车经山路回到村里。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路经学校门口通向市场。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐火车经武汉去长沙。", "target_word": "经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "經", "label": "繁体"}], "register": "书面", "sense_fingerprint": "介词，途中经过某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 海口 (Zipf 3.89), 开往 (Zipf 3.55), 三亚 (Zipf 3.79)']::text[], 'e7262136-bedf-47a3-b4c0-59481b3c3d7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经", "is_correct": true, "explanation": "正确。经 jīng 为本词，介词，表示途中经过某地。"}, {"text": "今", "is_correct": false, "explanation": "韵母不同（-in 与 -ing），jīn 意思是今天，与 jīng 不同。"}, {"text": "景", "is_correct": false, "explanation": "声调不同（第三声与第一声），jǐng 意思是风景，与 jīng 不同。"}, {"text": "静", "is_correct": false, "explanation": "声调不同（第四声与第一声），jìng 意思是安静，与 jīng 不同。"}, {"text": "井", "is_correct": false, "explanation": "声调不同（第三声与第一声），jǐng 意思是水井，与 jīng 不同。"}], "explanations": {"经": "正确。经 jīng 为本词，介词，表示途中经过某地。", "今": "韵母不同（-in 与 -ing），jīn 意思是今天，与 jīng 不同。", "景": "声调不同（第三声与第一声），jǐng 意思是风景，与 jīng 不同。", "静": "声调不同（第四声与第一声），jìng 意思是安静，与 jīng 不同。", "井": "声调不同（第三声与第一声），jǐng 意思是水井，与 jīng 不同。"}, "sentence_index": null, "correct_answer": "经"}, "level_3": {"options": [{"text": "经", "is_correct": true, "explanation": "正确。经：介词，表示火车途中经过南京这一地点，与句意相符。"}, {"text": "跟", "is_correct": false, "explanation": "搭配：“跟”后接人或共同行动的对象，不能接地点，“跟南京开往上海”不成立。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示为了某人或某事，与表示途经路线的意思不相符。"}, {"text": "用", "is_correct": false, "explanation": "配价：“用”后接工具或方式，“南京”是地点，不能作“用”的宾语。"}], "explanations": {"经": "正确。经：介词，表示火车途中经过南京这一地点，与句意相符。", "跟": "搭配：“跟”后接人或共同行动的对象，不能接地点，“跟南京开往上海”不成立。", "为": "语义：“为”表示为了某人或某事，与表示途经路线的意思不相符。", "用": "配价：“用”后接工具或方式，“南京”是地点，不能作“用”的宾语。"}, "sentence_index": 0, "correct_answer": "经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们经公园吃饭。", "explanation": "这里应该用〈在〉。“经”表示途中经过某地，多用于移动过程；“吃饭”是停留的活动，不能用“经公园”表示场所。"}, {"text": "我们经顺序排队。", "explanation": "这里应该用〈按〉。“经”表示途经某地或经过某个过程，不能表示依据，应说“按顺序排队”。"}, {"text": "我们经学校出发。", "explanation": "这里应该用〈从〉。“经”表示途中经过的地点，不能用来标示出发点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21524, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "经", "is_correct": true, "explanation": "正确。经 jīng 为本词，介词，表示途中经过某地。"}, {"text": "金", "is_correct": false, "explanation": "韵母不同（-in 与 -ing），jīn 意思是金子，与 jīng 不同。"}, {"text": "警", "is_correct": false, "explanation": "声调不同（第三声与第一声），jǐng 意思是警察，与 jīng 不同。"}, {"text": "镜", "is_correct": false, "explanation": "声调不同（第四声与第一声），jìng 意思是镜子，与 jīng 不同。"}, {"text": "竞", "is_correct": false, "explanation": "声调不同（第四声与第一声），jìng 意思是竞争，与 jīng 不同。"}], "explanations": {"经": "正确。经 jīng 为本词，介词，表示途中经过某地。", "金": "韵母不同（-in 与 -ing），jīn 意思是金子，与 jīng 不同。", "警": "声调不同（第三声与第一声），jǐng 意思是警察，与 jīng 不同。", "镜": "声调不同（第四声与第一声），jìng 意思是镜子，与 jīng 不同。", "竞": "声调不同（第四声与第一声），jìng 意思是竞争，与 jīng 不同。"}, "sentence_index": null, "correct_answer": "经"}, "level_3": {"options": [{"text": "经", "is_correct": true, "explanation": "正确。经：介词，表示从家到学校的途中经过一个公园，与句意相符。"}, {"text": "凭", "is_correct": false, "explanation": "语义：“凭”表示依据或凭借，与表示途经地点的句意不相符。"}, {"text": "和", "is_correct": false, "explanation": "搭配：“和”连接人或事物，“和一个公园”后不能接表示路线的动作。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”字句需要动词处置具体对象，“要把一个公园”的结构不成立。"}], "explanations": {"经": "正确。经：介词，表示从家到学校的途中经过一个公园，与句意相符。", "凭": "语义：“凭”表示依据或凭借，与表示途经地点的句意不相符。", "和": "搭配：“和”连接人或事物，“和一个公园”后不能接表示路线的动作。", "把": "配价：“把”字句需要动词处置具体对象，“要把一个公园”的结构不成立。"}, "sentence_index": 6, "correct_answer": "经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经我借了一本书。", "explanation": "这里应该用〈向〉。“经”表示途经某处，不能引出借书的对象，应说“向我借”。"}, {"text": "我们经火车去长沙。", "explanation": "这里应该用〈乘〉。“乘”可引出交通工具，说“乘火车去长沙”；“经”表示途经的地点或路线，不直接引出交通工具。"}, {"text": "这条船经三部分组成。", "explanation": "这里应该用〈由〉。“由”可引出构成成分，说“由三部分组成”；“经”表示经过，不能用于引出构成成分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "列车从经武汉开往广州。", "corrected_sentence": "列车经武汉开往广州。", "error_description": "错误：“经”与“从”重复使用，句中没有出发地，不能在“经”前加“从”。应去掉“从”，改为“列车经武汉开往广州”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐大巴经到武汉去北京。", "corrected_sentence": "我们坐大巴经武汉去北京。", "error_description": "错误：“经”后面不能接“到”，“经”直接跟表示途经的地点即可。应去掉“到”，改为“我们坐大巴经武汉去北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be1005a-85a2-4331-8225-b8a7a0c2e314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
