INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在买东西和卖东西的人中间帮忙的人。", "primary_collocate": null, "pronunciation": "zhōng jiān shāng", "ipa": "ʈ͡ʂʊŋ˥ tɕjɛn˥ ʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "中间商帮农民把苹果卖给城里的商店。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是中间商，帮买家找卖家。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有中间商，农民只能自己去卖菜。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间商从工厂拿货，再卖给小商店。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有中间商，这件衣服比工厂价贵。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中间商常常两边联系，让买卖更容易。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔做中间商，每天都要打很多电话。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买茶叶时，中间商帮我找到了好的茶农。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位中间商认识很多卖家和买家。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把茶叶卖给中间商，中间商再卖给茶店。", "target_word": "中间商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "中间商:在买卖双方中间帮忙的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f266c8f4-35c9-4740-9e77-94aae56e485a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中间商", "is_correct": true, "explanation": "中间商在买卖双方之间帮忙，句中“帮农民把苹果卖给商店”正是其职能。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判负责执行比赛规则，不参与买卖，“裁判帮农民卖苹果”不成立。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能帮农民卖苹果，句意不通。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生的职业是诊治病人，与帮忙卖苹果无关，句意不通。"}], "explanations": {"中间商": "中间商在买卖双方之间帮忙，句中“帮农民把苹果卖给商店”正是其职能。", "裁判": "语义：裁判负责执行比赛规则，不参与买卖，“裁判帮农民卖苹果”不成立。", "钢琴": "语义：钢琴是乐器，不能帮农民卖苹果，句意不通。", "医生": "语义：医生的职业是诊治病人，与帮忙卖苹果无关，句意不通。"}, "sentence_index": 0, "correct_answer": "中间商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂是中间商，自己生产衣服。", "explanation": "这里应该用〈生产商〉。工厂自己生产衣服属于生产，中间商只在买卖之间帮忙。"}, {"text": "这盏灯是中间商，帮人买卖茶叶。", "explanation": "这里指物品不妥：〈中间商〉指个人或企业，灯不能作中间商。"}, {"text": "这匹老马每天把茶叶从山上驮下来，是中间商。", "explanation": "这里指动物不妥：〈中间商〉指个人或企业，马不能作中间商。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中间商", "is_correct": true, "explanation": "中间商需要频繁联系买卖双方，打很多电话正合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种花草的场所，不能作职业，“做花园”与句意不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能做职业，“做石头”不成立。"}, {"text": "大爷", "is_correct": false, "explanation": "语域：“大爷”是口语词，与本句语体不协调；且它不是一种职业。"}], "explanations": {"中间商": "中间商需要频繁联系买卖双方，打很多电话正合句意。", "花园": "语义：花园是种花草的场所，不能作职业，“做花园”与句意不符。", "石头": "语义：石头是无生命的物体，不能做职业，“做石头”不成立。", "大爷": "语域：“大爷”是口语词，与本句语体不协调；且它不是一种职业。"}, "sentence_index": 6, "correct_answer": "中间商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中间商自己种茶，再卖给茶店。", "explanation": "这里应该用〈茶农〉。自己种茶属于生产，中间商只在买卖之间帮忙。"}, {"text": "这棵树是中间商，把茶叶卖给茶店。", "explanation": "这里指植物不妥：〈中间商〉指个人或企业，树不能作中间商。"}, {"text": "那条河每年都帮买家找到卖家，是中间商。", "explanation": "这里指自然物不妥：〈中间商〉指个人或企业，河流不能作中间商。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆中间商每天帮农民卖蔬菜。", "corrected_sentence": "这位中间商每天帮农民卖蔬菜。", "error_description": "量词错误：指人可用“位”或“个”，“辆”多用于车辆，不能修饰人。应改为“这位中间商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姨妈是一张中间商，每天都要帮人找货源。", "corrected_sentence": "我姨妈是一位中间商，每天都要帮人找货源。", "error_description": "量词错误：指人可用“位”或“个”，“张”多用于纸或桌子等，不能修饰人。应改为“一位中间商”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
