INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "产品或事物的好坏程度。", "primary_collocate": null, "pronunciation": "zhì liàng", "ipa": "ʈʂɻ̩˥˩ liɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店的衣服质量很好。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要提高产品的质量。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气质量今天比昨天好。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买东西最看重质量。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机质量不好，用了一个月就坏了。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠质量会影响第二天的心情。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果质量不错，又新鲜又甜。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "便宜的东西质量不一定差。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "质量好的鞋可以穿很多年。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做菜时，好的材料能保证饭菜的质量。", "target_word": "质量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "质量问题", "label": "复合"}], "register": "中性", "sense_fingerprint": "产品或事物的好坏程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027318f4-2b33-4396-a5c8-0febbc57a5e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "质量", "is_correct": true, "explanation": "「质量」指东西的好坏程度，与「很好」搭配，符合句意。"}, {"text": "速度", "is_correct": false, "explanation": "语义：「速度」说快慢，衣服没有速度，不能用「很好」评价。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指人或动物的重量，衣服没有体重。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：衣服没有年龄，「年龄」只用于人或动植物。"}], "explanations": {"质量": "「质量」指东西的好坏程度，与「很好」搭配，符合句意。", "速度": "语义：「速度」说快慢，衣服没有速度，不能用「很好」评价。", "体重": "语义：「体重」指人或动物的重量，衣服没有体重。", "年龄": "语义：衣服没有年龄，「年龄」只用于人或动植物。"}, "sentence_index": 0, "correct_answer": "质量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的衣服质量很多。", "explanation": "这里应该用〈数量〉。「质量」说好坏，不说多少，「很多」要用「数量」。"}, {"text": "这双鞋的质量很便宜。", "explanation": "这里应该用〈价格〉。「便宜」用于价钱，「质量」不能说便宜。"}, {"text": "他这次考试的质量很好。", "explanation": "这里应该用〈成绩〉。「质量」多用于产品或工作，考试结果要用「成绩」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "质量", "is_correct": true, "explanation": "「质量」指水果的好坏，「不错」可以评价它，符合句意。"}, {"text": "性格", "is_correct": false, "explanation": "语义：「性格」只用于人，水果没有性格。"}, {"text": "工资", "is_correct": false, "explanation": "语义：「工资」是劳动报酬，不是水果的属性。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：「房间」是空间，不能说水果「房间不错」。"}], "explanations": {"质量": "「质量」指水果的好坏，「不错」可以评价它，符合句意。", "性格": "语义：「性格」只用于人，水果没有性格。", "工资": "语义：「工资」是劳动报酬，不是水果的属性。", "房间": "搭配：「房间」是空间，不能说水果「房间不错」。"}, "sentence_index": 6, "correct_answer": "质量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的质量很长。", "explanation": "这里应该用〈寿命〉。「寿命」指使用的年限，可以说长短，「质量」说好坏或轻重，不能用「长」来形容。"}, {"text": "他跑步的质量很快。", "explanation": "这里应该用〈速度〉。「快」用于速度，「质量」不能说快慢。"}, {"text": "他家到学校的质量很远。", "explanation": "这里应该用〈距离〉。「距离」指两地之间的远近，可以说远，「质量」说好坏或轻重，不能说远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑的质量的很稳定。", "corrected_sentence": "这台电脑的质量很稳定。", "error_description": "错误在于“质量”后多出“的”。“这台电脑的质量”已是完整的主语，“质量”后不应再接“的”，应删去，说“这台电脑的质量很稳定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂的产品质量高很。", "corrected_sentence": "这家工厂的产品质量很高。", "error_description": "错误在于“很”与“高”的语序。形容词作谓语时，程度副词“很”应放在形容词前面，应说“质量很高”，不能说“质量高很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0513fdf-1194-433e-86ab-311a913ce376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
