INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21543, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21543, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很多相同的东西一起做。", "primary_collocate": null, "pronunciation": "pī liàng", "ipa": "pʰi˥ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店批量卖水果。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂批量做玩具。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想批量打印这些文件。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校批量买了新桌子。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们批量生产自行车。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工具能批量保存图片。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司批量发了一百封信。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈批量包了很多饺子，准备过年。", "target_word": "批量", "complexity_tier": "T3", "furigana": "mā ma pī liàng bāo le hěn duō jiǎo zi, zhǔn bèi guò nián.", "sentence_source": "generated"}, {"text": "老板说，批量买更便宜。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请批量处理这些照片。", "target_word": "批量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批量生产", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多相同的东西一起做，数量大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8d2a2b0-046a-431e-85e1-9cfdfaec8fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批量", "is_correct": true, "explanation": "“批量”表示成批同时卖同类的东西，与“卖水果”搭配。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”不能与“水果”搭配，不能说“读水果”。"}, {"text": "猜", "is_correct": false, "explanation": "语义：“猜”是推测，与“卖水果”的动作不相容。"}, {"text": "特此", "is_correct": false, "explanation": "语域：“特此”是书面公文用语，用于告知性文字，不适合用于描述日常卖水果。"}], "explanations": {"批量": "“批量”表示成批同时卖同类的东西，与“卖水果”搭配。", "读": "搭配：“读”不能与“水果”搭配，不能说“读水果”。", "猜": "语义：“猜”是推测，与“卖水果”的动作不相容。", "特此": "语域：“特此”是书面公文用语，用于告知性文字，不适合用于描述日常卖水果。"}, "sentence_index": 0, "correct_answer": "批量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校批量买了一张新桌子。", "explanation": "这里应该用〈单独〉。“批量”要求很多相同的东西一起做，只买一张不能用批量。"}, {"text": "他批量读完了一本小说。", "explanation": "这里应该用〈一口气〉。“批量”指很多相同的东西一起做，“读完一本小说”是一次完成的单个任务，不能用批量。"}, {"text": "他批量完成了一项任务。", "explanation": "这里应该用〈独立〉。“批量”指很多相同的东西一起做，“一项任务”只有一件，不能用批量，要说独立完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批量", "is_correct": true, "explanation": "“批量”表示一次成批发出同类的信件，与“发了一百封信”相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指不经常，与一次发出一百封信的数量互相冲突。"}, {"text": "当面", "is_correct": false, "explanation": "搭配：“当面”指面对面，与“发信”不搭配。"}, {"text": "亲口", "is_correct": false, "explanation": "搭配：“亲口”指用嘴亲自说出，不能用于发信。"}], "explanations": {"批量": "“批量”表示一次成批发出同类的信件，与“发了一百封信”相符。", "偶尔": "语义：“偶尔”指不经常，与一次发出一百封信的数量互相冲突。", "当面": "搭配：“当面”指面对面，与“发信”不搭配。", "亲口": "搭配：“亲口”指用嘴亲自说出，不能用于发信。"}, "sentence_index": 6, "correct_answer": "批量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请批量休息片刻。", "explanation": "这里应该用〈一起〉。“批量”要求同时处理很多相同的东西，“休息”不是这样的动作，不能用批量。"}, {"text": "老师们批量思考这些问题。", "explanation": "这里应该用〈认真〉。“批量”修饰的是处理同类事物的动作，“思考问题”不是这样的动作，不能用批量。"}, {"text": "孩子们批量长大了。", "explanation": "这里应该用〈陆续〉。“批量”表示同时成批处理，“长大”是逐渐、先后发生的，不能说批量长大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们很批量抄写了单词。", "corrected_sentence": "学生们批量抄写了单词。", "error_description": "错误：副词“批量”前不能加程度副词“很”，应说“批量抄写了单词”，不能说“很批量抄写”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请很批量清洗这些杯子。", "corrected_sentence": "请批量清洗这些杯子。", "error_description": "错误：副词“批量”前不能加程度副词“很”，应说“批量清洗这些杯子”，不能说“很批量清洗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de22b3e-02af-423f-920c-c5ea4703c37d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
