INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认证就是证明一个东西是真的、对的。", "primary_collocate": null, "pronunciation": "rèn zhèng", "ipa": "ɻən˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "网站要认证你的身份。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先认证，再进入这个网站。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牛奶已经认证过了，可以放心喝。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行需要认证你的电话号码。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家机构正在认证这批古董。", "target_word": "认证", "complexity_tier": "T3", "furigana": "rèn zhèng", "sentence_source": "generated"}, {"text": "专家认证了这件青铜器。", "target_word": "认证", "complexity_tier": "T3", "furigana": "rèn zhèng", "sentence_source": "generated"}, {"text": "这家公司要认证每位员工的资格。", "target_word": "认证", "complexity_tier": "T3", "furigana": "rèn zhèng", "sentence_source": "generated"}, {"text": "手机号认证以后，你才能买东西。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作要用两天认证所有的文件。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用你的名字认证一下这个账号。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认证了", "label": "体标"}, {"form": "认证过", "label": "体标"}, {"form": "認證", "label": "繁体"}, {"form": "认证中心", "label": "复合"}], "register": "书面", "sense_fingerprint": "检查并证明某人或某物是真的、合格的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a7a5ac5-16ea-4b03-b6bf-b31c050a3381') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "认证", "is_correct": true, "explanation": "正确答案：认证，指经过检验确认某人或某物真实、合格。"}, {"text": "认真", "is_correct": false, "explanation": "zhēn（第一声）与 zhèng（第四声）韵母与声调都不同，意思是认真、不马虎。"}, {"text": "人证", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是人作的证词。"}, {"text": "认知", "is_correct": false, "explanation": "zhī（第一声）与 zhèng（第四声）韵母与声调都不同，意思是认识、知道。"}, {"text": "任职", "is_correct": false, "explanation": "zhí（第二声）与 zhèng（第四声）韵母与声调不同，意思是担任职务。"}, {"text": "认成", "is_correct": false, "explanation": "chéng（第二声）与 zhèng（第四声）声母与声调都不同，意思是把甲错当成乙。"}], "explanations": {"认证": "正确答案：认证，指经过检验确认某人或某物真实、合格。", "认真": "zhēn（第一声）与 zhèng（第四声）韵母与声调都不同，意思是认真、不马虎。", "人证": "rén（第二声）与 rèn（第四声）声调不同，意思是人作的证词。", "认知": "zhī（第一声）与 zhèng（第四声）韵母与声调都不同，意思是认识、知道。", "任职": "zhí（第二声）与 zhèng（第四声）韵母与声调不同，意思是担任职务。", "认成": "chéng（第二声）与 zhèng（第四声）声母与声调都不同，意思是把甲错当成乙。"}, "sentence_index": null, "correct_answer": "认证"}, "level_3": {"options": [{"text": "认证", "is_correct": true, "explanation": "正确：“认证”指经过核验确认身份，网站需要确认你是真人。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是舍弃、不要的意思，与网站需要核实身份的目的相反。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”接的是纪录、局面、限制，不说打破“身份”。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”的对象是人，“你的身份”不能作为通知的内容。"}], "explanations": {"认证": "正确：“认证”指经过核验确认身份，网站需要确认你是真人。", "放弃": "语义：“放弃”是舍弃、不要的意思，与网站需要核实身份的目的相反。", "打破": "搭配：“打破”接的是纪录、局面、限制，不说打破“身份”。", "通知": "配价：“通知”的对象是人，“你的身份”不能作为通知的内容。"}, "sentence_index": 0, "correct_answer": "认证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法院认证他有罪。", "explanation": "这里应该用〈认定〉。认证是经检验确认真实或合格，多用于身份、资格、产品；判定罪责要用认定。"}, {"text": "老师认证了他的进步。", "explanation": "这里应该用〈认可〉。认证针对的是资格或产品是否合格，评价别人的进步要用认可。"}, {"text": "这张收据可以认证我付过钱。", "explanation": "这里应该用〈证明〉。认证必须由有权机构正式确认合格，不用来证明个人行为，应说证明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "认证", "is_correct": true, "explanation": "正确答案：认证，指经过检验确认真实或合格。"}, {"text": "认账", "is_correct": false, "explanation": "zhàng（第四声）与 zhèng（第四声）声调相同，韵母不同（ang 与 eng），意思是承认自己欠的账或做过的事。"}, {"text": "认生", "is_correct": false, "explanation": "shēng（第一声）与 zhèng（第四声）声母与声调都不同，意思是小孩见了陌生人害羞。"}, {"text": "真正", "is_correct": false, "explanation": "zhēn（第一声）与 rèn（第四声）声母与声调不同，zhèng 相同，意思是真的、确实。"}, {"text": "任重", "is_correct": false, "explanation": "zhòng（第四声）与 zhèng（第四声）韵母不同（ong 与 eng），意思是责任重大。"}], "explanations": {"认证": "正确答案：认证，指经过检验确认真实或合格。", "认账": "zhàng（第四声）与 zhèng（第四声）声调相同，韵母不同（ang 与 eng），意思是承认自己欠的账或做过的事。", "认生": "shēng（第一声）与 zhèng（第四声）声母与声调都不同，意思是小孩见了陌生人害羞。", "真正": "zhēn（第一声）与 rèn（第四声）声母与声调不同，zhèng 相同，意思是真的、确实。", "任重": "zhòng（第四声）与 zhèng（第四声）韵母不同（ong 与 eng），意思是责任重大。"}, "sentence_index": null, "correct_answer": "认证"}, "level_3": {"options": [{"text": "认证", "is_correct": true, "explanation": "正确：“认证”指核定员工的资格，与句子语境相符。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，与核定资格的意思不符。"}, {"text": "嫌弃", "is_correct": false, "explanation": "搭配：“嫌弃”的对象是人或事物，不说嫌弃“资格”。"}, {"text": "辞退", "is_correct": false, "explanation": "配价：“辞退”的宾语是人，不能说辞退“资格”。"}], "explanations": {"认证": "正确：“认证”指核定员工的资格，与句子语境相符。", "浪费": "语义：“浪费”指白白耗费，与核定资格的意思不符。", "嫌弃": "搭配：“嫌弃”的对象是人或事物，不说嫌弃“资格”。", "辞退": "配价：“辞退”的宾语是人，不能说辞退“资格”。"}, "sentence_index": 6, "correct_answer": "认证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一下子认证了他。", "explanation": "这里应该用〈认出〉。认证是确认资格或真实性，不表示凭样貌辨认出人。"}, {"text": "他终于认证了错误。", "explanation": "这里应该用〈承认〉。认证是有权机构对合格性的正式确认，承认错误要用承认。"}, {"text": "我认证他是对的。", "explanation": "这里应该用〈认为〉。认证是官方确认合格，个人的看法不能用认证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游戏账号要先了认证手机号，才能充值。", "corrected_sentence": "游戏账号要先认证手机号，才能充值。", "error_description": "“了”只能放在动词后表示完成，“了认证”的语序是错误的；此句应写作“要先认证手机号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批证书需要重新了认证。", "corrected_sentence": "这批证书需要重新认证。", "error_description": "错误：“重新了认证”。正确：“重新认证”。“了”表示完成，只能放在动词后，不能插在“认证”之前，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西不会随便变来变去，一直保持一样。", "primary_collocate": null, "pronunciation": "wěn dìng xìng", "ipa": "wən˨˩˦ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这张桌子的稳定性很好，不会晃。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子刚学走路，身体的稳定性还不够。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机信号的稳定性不好，常常断线。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把梯子一站上去就晃，稳定性不好。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宽底的杯子稳定性高，不容易倒。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买车时，爸爸很看重车的稳定性。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船的稳定性差，风一大就晃。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气的稳定性不好，一会儿晴一会儿雨。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台秤的稳定性很高，每次称出来的数都一样。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架的稳定性不够，放太多书会倒。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "穩定性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西不乱变、不摇晃，一直保持一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a92634-fb21-491d-bc46-54f0ac3ab9c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观，与“不会晃”无关，“颜色很好，不会晃”不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”指气味或滋味，不能用来说桌子。"}, {"text": "稳定性", "is_correct": true, "explanation": "稳定性指东西不晃、一直保持一样，与“不会晃”的语境相符。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”说的是尺寸，与桌子是否晃动无关，“长度很好，不会晃”不通。"}], "explanations": {"颜色": "语义：“颜色”指外观，与“不会晃”无关，“颜色很好，不会晃”不通。", "味道": "搭配：“味道”指气味或滋味，不能用来说桌子。", "稳定性": "稳定性指东西不晃、一直保持一样，与“不会晃”的语境相符。", "长度": "语义：“长度”说的是尺寸，与桌子是否晃动无关，“长度很好，不会晃”不通。"}, "sentence_index": 0, "correct_answer": "稳定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的稳定性很大，两个人才抬得动。", "explanation": "这里应该用〈重量〉。稳定性指东西不随便变化，不指轻重；“两个人才抬得动”说的是重量。"}, {"text": "这块石头的稳定性很高，是红色的。", "explanation": "这里应该用〈颜色〉。稳定性指东西不随便变化，不指颜色；“是红色的”说的是颜色。"}, {"text": "这一张稳定性不好，一站就晃。", "explanation": "这里应该用〈种〉或不加量词。“张”用于平面的东西，稳定性是抽象性质，不能用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：“声音”指声响，与“差”和“风一大就晃”无关，“声音差”不通。"}, {"text": "名声", "is_correct": false, "explanation": "语义：“名声”指社会评价，不指船的晃动，与句意不符。"}, {"text": "稳定性", "is_correct": true, "explanation": "稳定性指东西不晃、不乱变的特性，与“差，风一大就晃”的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说人或物的重量，不能和“差”搭配来描述船是否晃动。"}], "explanations": {"声音": "语义：“声音”指声响，与“差”和“风一大就晃”无关，“声音差”不通。", "名声": "语义：“名声”指社会评价，不指船的晃动，与句意不符。", "稳定性": "稳定性指东西不晃、不乱变的特性，与“差，风一大就晃”的语境相符。", "体重": "搭配：“体重”说人或物的重量，不能和“差”搭配来描述船是否晃动。"}, "sentence_index": 6, "correct_answer": "稳定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一扇稳定性不够，放太多书会倒。", "explanation": "这里应该用〈种〉或不加量词。“扇”用于门窗，稳定性是抽象性质，不能用“扇”计量。"}, {"text": "这辆车的稳定性很快，十分钟就能到机场。", "explanation": "这里应该用〈速度〉。稳定性指东西不随便变，不指快慢；“很快，十分钟就能到机场”说的是速度。"}, {"text": "书架的稳定性很多，放太多书会倒。", "explanation": "这里应该用〈很高〉或〈很好〉。稳定性是抽象性质，不可数，不能用“很多”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台洗衣机的稳定性好很，脱水时也不晃。", "corrected_sentence": "这台洗衣机的稳定性很好，脱水时也不晃。", "error_description": "错误：“好很”。“很”应放在形容词前面，正确说法是“稳定性很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书柜得稳定性很好，装满书也不会倒。", "corrected_sentence": "这个书柜的稳定性很好，装满书也不会倒。", "error_description": "错误：“得”。“稳定性”前的定语应用“的”，不能用“得”。正确说法是“书柜的稳定性很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
