INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西是从哪里来的，比如苹果的产地是果园。", "primary_collocate": null, "pronunciation": "chǎn dì", "ipa": "ʈʂʰan˨˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这个苹果的产地是山东。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这种大米的产地吗？", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "瓶子上写着葡萄酒的产地。", "target_word": "产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种橙子的产地很远，所以有点贵。", "target_word": "产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买菜时总是看产地。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋的产地是哪里？", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "茶叶的产地不同，价格也不同。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想知道这块肉的产地。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛奶包装上有产地和日期。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了香蕉的产地。", "target_word": "产地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "產地", "label": "繁体"}, {"form": "原产地", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "产地：东西从哪里来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f266c8f4-35c9-4740-9e77-94aae56e485a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产地", "is_correct": true, "explanation": "产地：物品出产的地方，山东是苹果的产地，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是金额，不能是地名山东，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”描述外观，不能是地名山东，句意不通。"}, {"text": "保质期", "is_correct": false, "explanation": "搭配：“保质期”说的是时长，不说“保质期是山东”。"}], "explanations": {"产地": "产地：物品出产的地方，山东是苹果的产地，符合句意。", "价格": "语义：“价格”是金额，不能是地名山东，句意不通。", "颜色": "语义：“颜色”描述外观，不能是地名山东，句意不通。", "保质期": "搭配：“保质期”说的是时长，不说“保质期是山东”。"}, "sentence_index": 0, "correct_answer": "产地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行的产地是上海。", "explanation": "这里应该用〈出发地〉。产地指物品出产的地方，旅行的起点不能说产地。"}, {"text": "他的产地是农民。", "explanation": "这里应该用〈出身〉。产地是物品出产的地方，人的出身不能说产地。"}, {"text": "我想去一条有名的产地参观。", "explanation": "这里应该用〈个〉。产地是地方，量词用个或处，〈条〉用于长的东西，不能修饰产地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产地", "is_correct": true, "explanation": "产地：茶叶出产的地方，产地不同则价格不同，符合句意。"}, {"text": "性别", "is_correct": false, "explanation": "语义：茶叶没有性别，“性别不同”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指生物的存活年限，不是茶叶的属性，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人和动物，不说茶叶的体重。"}], "explanations": {"产地": "产地：茶叶出产的地方，产地不同则价格不同，符合句意。", "性别": "语义：茶叶没有性别，“性别不同”说不通。", "寿命": "语义：“寿命”指生物的存活年限，不是茶叶的属性，句意不通。", "体重": "搭配：“体重”用于人和动物，不说茶叶的体重。"}, "sentence_index": 6, "correct_answer": "产地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个会议的产地在北京。", "explanation": "这里应该用〈地点〉。产地指物品出产的地方，会议举行的场所不能说产地。"}, {"text": "这本书的产地是《红楼梦》。", "explanation": "这里应该用〈书名〉。产地指物品出产的地方，书的名称不能说产地。"}, {"text": "我的产地是小明。", "explanation": "这里应该用〈名字〉。产地只用于物品，人的名字不能说产地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想去一只有名的产地，看看那里的果园。", "corrected_sentence": "我想去一个有名的产地，看看那里的果园。", "error_description": "错误在量词：产地是地方，应说「一个产地」或「一处产地」；「只」用于动物等，不能修饰产地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些茶叶得产地不同，口感也不同。", "corrected_sentence": "这些茶叶的产地不同，口感也不同。", "error_description": "错误在修饰标记：修饰名词「产地」要用「的」，「得」用于动词或形容词后的补语，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
