INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把东西从一个地方送到另一个地方。", "primary_collocate": null, "pronunciation": "wù liú", "ipa": "u˥˩ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "现在网上买东西，物流很快。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做物流工作。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，物流常常比较慢。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想查一下物流信息。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家物流公司上班。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物流让生活方便了很多。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的物流还不太方便。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的物流能让客人更满意。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天会影响物流速度。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是管理仓库和物流。", "target_word": "物流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "货物的运输、存放和送达过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ee3da4-4c99-4c2d-aaed-c51fb6a3dd04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物流", "is_correct": true, "explanation": "正确：“物流”指货物的运输和送达，句中说网上买东西后送货很快。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“快”形容速度，不能用来形容“价格”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气本身没有快慢的速度义，与“网上买东西”的语境不合。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不是能快慢送达的事物，句子说的是送货速度。"}], "explanations": {"物流": "正确：“物流”指货物的运输和送达，句中说网上买东西后送货很快。", "价格": "搭配：“快”形容速度，不能用来形容“价格”。", "天气": "语义：天气本身没有快慢的速度义，与“网上买东西”的语境不合。", "银行": "语义：银行不是能快慢送达的事物，句子说的是送货速度。"}, "sentence_index": 0, "correct_answer": "物流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天用卡车物流原料到仓库。", "explanation": "这里应该用〈运输〉。“物流”是名词，指运送货物的过程或行业，不能当动词用来表示“运送”。"}, {"text": "我把物流装进了箱子。", "explanation": "语义：“物流”指运送货物的过程或行业，是抽象的，不是可以装进箱子的东西；装进箱子的应是“包裹”或“货物”。"}, {"text": "他是一位很厉害的物流。", "explanation": "语义：“物流”不指人，指运送的过程或行业；形容人要说“物流工作者”或“物流人员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物流", "is_correct": true, "explanation": "正确：“物流”指运送货物的过程，句中说山区的运送还不方便。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不是可以“方便”与否的事物，“山区的月亮”句意说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，与“山区”“方便”的语境不合。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“方便”不与“工资”搭配，句子说的是运送条件。"}], "explanations": {"物流": "正确：“物流”指运送货物的过程，句中说山区的运送还不方便。", "月亮": "语义：“月亮”不是可以“方便”与否的事物，“山区的月亮”句意说不通。", "身高": "体貌：身高是人的体貌特征，与“山区”“方便”的语境不合。", "工资": "搭配：“方便”不与“工资”搭配，句子说的是运送条件。"}, "sentence_index": 6, "correct_answer": "物流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想去邮局寄物流。", "explanation": "这里应该用〈快递〉。“寄”的对象是包裹或快递，“物流”指运送的过程或行业，不能被寄出。"}, {"text": "周末我们在餐厅吃物流。", "explanation": "这里应该用〈饭菜〉。“吃”的对象是食物，“物流”指运送货物的过程或行业，不能吃。"}, {"text": "我的身高和物流一样高。", "explanation": "这里应该用〈人〉。“一样高”用于比较人或物体的高矮，“物流”指运送货物的过程或行业，是抽象的，没有高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在一条物流公司工作。", "corrected_sentence": "她在一家物流公司工作。", "error_description": "量词错误：“物流公司”的量词应为“家”，不能用“条”。正确形式为“一家物流公司”。“条”多用于细长的物件，不能用于公司。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些物流们公司都很大。", "corrected_sentence": "这些物流公司都很大。", "error_description": "错误形式：“物流们”。正确形式：“物流”。“物流”指运送的过程或行业，不指人，不能加复数词尾“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
