INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保证一定做到。", "primary_collocate": null, "pronunciation": "què bǎo", "ipa": "tɕʰɥe˥˩ pɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "出门前要确保门已经关好。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须确保食品安全。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师检查了每个人的作业，确保没有错误。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请确保手机有电。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提前出发，确保准时到达。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天检查机器，确保安全。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了确保质量，我们做了三次检查。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你确保把门锁好。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生确保病人吃了药。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司确保每个客人都满意。", "target_word": "确保", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "確保", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "采取办法，保证某件事一定做到或不出问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ee3da4-4c99-4c2d-aaed-c51fb6a3dd04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "确保", "is_correct": true, "explanation": "确保：保证一定做到，与“出门前要确保门已经关好”的句意相符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“门已经关好”这样的小句作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“门已经关好”不相容，“要唱门已经关好”句意说不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能支配“门已经关好”这样的内容，句意说不通。"}], "explanations": {"确保": "确保：保证一定做到，与“出门前要确保门已经关好”的句意相符。", "散步": "配价：“散步”是不及物动词，不能带“门已经关好”这样的小句作宾语。", "唱": "语义：“唱”与“门已经关好”不相容，“要唱门已经关好”句意说不通。", "吃": "语义：“吃”不能支配“门已经关好”这样的内容，句意说不通。"}, "sentence_index": 0, "correct_answer": "确保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们还没确保今天的会议时间。", "explanation": "这里应该用〈确定〉。“确保”表示保证某事一定做到，不能用来表示定下会议时间。"}, {"text": "我们要确保火灾再次发生。", "explanation": "这里应该用〈预防〉。“确保”表示保证某事一定做到，不能用于不希望发生的事情。"}, {"text": "气象台确保明天会下雨。", "explanation": "这里应该用〈预报〉。“确保”要求人能够采取措施使事情一定实现，天气无法这样控制，不能用来表示天气预报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确保", "is_correct": true, "explanation": "确保：保证一定做到，与“为了确保质量”的句意相符。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”与“质量”的目的关系相反，“为了破坏质量”句意说不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”不能表示目的，“为了忘记质量”句意说不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再坚持，与“为了……质量”的目的不合，句意说不通。"}], "explanations": {"确保": "确保：保证一定做到，与“为了确保质量”的句意相符。", "破坏": "语义：“破坏”与“质量”的目的关系相反，“为了破坏质量”句意说不通。", "忘记": "语义：“忘记”不能表示目的，“为了忘记质量”句意说不通。", "放弃": "语义：“放弃”表示不再坚持，与“为了……质量”的目的不合，句意说不通。"}, "sentence_index": 6, "correct_answer": "确保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "顾客经常确保服务太慢。", "explanation": "这里应该用〈抱怨〉。“确保”是有意采取措施使事情一定做到，不能用来描述顾客对服务的不满。"}, {"text": "工人们想确保机器故障。", "explanation": "这里应该用〈阻止〉。“确保”表示保证某事一定做到，不能用于不希望发生的故障。"}, {"text": "我们应该确保危险。", "explanation": "这里应该用〈躲避〉。“确保”表示保证事情一定做到，不能用来表示躲避危险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂已经了确保产品安全。", "corrected_sentence": "工厂已经确保产品安全。", "error_description": "错误形式：“已经了确保”。“了”是动态助词，不能放在动词“确保”之前，删去即可，应说“工厂已经确保产品安全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你很确保把窗户关好。", "corrected_sentence": "请你确保把窗户关好。", "error_description": "错误形式：“很确保”。正确形式：“确保”。“很”一般修饰形容词，“确保”是行为动词，不能受“很”修饰，应直接说“确保”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
