INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "消费国就是买很多东西用的国家。", "primary_collocate": null, "pronunciation": "xiāo fèi guó", "ipa": "ɕiɑʊ˥ feɪ˥˩ ku̯ɔ˧˥", "syllable_count": 3, "sentences": [{"text": "日本是很大的茶叶消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费国的人买很多东西。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消费国每年进口大量手机。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巧克力的主要消费国在欧洲。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国既是生产国，也是重要的消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家人多钱多，是最大的汽车消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡从产地运到消费国，价格会变高。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费国的人们爱喝咖啡，所以进口很多咖啡豆。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多水果从南方的国家卖到北方的消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国不种大米，是大米消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "消费国:买很多东西用的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f266c8f4-35c9-4740-9e77-94aae56e485a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消费国", "is_correct": true, "explanation": "消费国指买很多东西的国家，日本是大量买茶叶的国家，符合句意。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：国家不能是工厂，“很大的茶叶工厂”与句意不符。"}, {"text": "老外", "is_correct": false, "explanation": "语域：“老外”是口语词，与本句的书面语体不协调；且它指人，不指国家。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：国家不是茶馆，“很大的茶叶茶馆”说的是店铺，与句中国家主体不符。"}], "explanations": {"消费国": "消费国指买很多东西的国家，日本是大量买茶叶的国家，符合句意。", "工厂": "语义：国家不能是工厂，“很大的茶叶工厂”与句意不符。", "老外": "语域：“老外”是口语词，与本句的书面语体不协调；且它指人，不指国家。", "茶馆": "语义：国家不是茶馆，“很大的茶叶茶馆”说的是店铺，与句中国家主体不符。"}, "sentence_index": 0, "correct_answer": "消费国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日本每年向海外大量出口汽车，国内却几乎不买车，是重要的消费国。", "explanation": "这里应该用〈出口国〉。句中说国内几乎不买车，却称消费国，应说出口国；消费国指大量买入、消耗商品的国家。"}, {"text": "这家贸易公司每年大量买进茶叶，是重要的消费国。", "explanation": "这里应该用〈采购商〉。消费国指国家，公司买进茶叶应说〈采购商〉，不能作为消费国。"}, {"text": "这位老师是个很大的消费国。", "explanation": "这里指人不妥：〈消费国〉指国家，不能指个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费国", "is_correct": true, "explanation": "消费国是买入商品的国家，咖啡运到它那里价格会变高，符合句意。"}, {"text": "产地", "is_correct": false, "explanation": "语义：咖啡本来就从产地出发，不能再“运到产地”，运输终点应是买入的一方。"}, {"text": "银行", "is_correct": false, "explanation": "语义：咖啡不会被运到银行，句中运输的终点应是买入咖啡的国家。"}, {"text": "大爷", "is_correct": false, "explanation": "语域：“大爷”是口语词，与本句语体不协调；且它指人，不指国家。"}], "explanations": {"消费国": "消费国是买入商品的国家，咖啡运到它那里价格会变高，符合句意。", "产地": "语义：咖啡本来就从产地出发，不能再“运到产地”，运输终点应是买入的一方。", "银行": "语义：咖啡不会被运到银行，句中运输的终点应是买入咖啡的国家。", "大爷": "语域：“大爷”是口语词，与本句语体不协调；且它指人，不指国家。"}, "sentence_index": 6, "correct_answer": "消费国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司每年大量买进大米，是大米消费国。", "explanation": "这里指公司不妥：〈消费国〉指国家，公司不能作为消费国。"}, {"text": "这个小国大量种植大米，却从来不吃大米，是大米消费国。", "explanation": "这里应该用〈生产国〉。大量种植大米是生产，且从不吃大米，不符合消费国的定义。"}, {"text": "这个小国每年向邻国供应大量大米，本国却几乎不买大米，是重要的大米消费国。", "explanation": "这里应该用〈出口国〉。句中说本国几乎不买大米、只向邻国供应，应说出口国；消费国指大量买入、消耗商品的国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小国每年大量买进茶叶，是重要的一座消费国。", "corrected_sentence": "这个小国每年大量买进茶叶，是重要的一个消费国。", "error_description": "量词错误：国家应用“个”，不用“座”。“座”多用于山、桥、城市等固定建筑，应改为“一个消费国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只消费国的人喜欢买进口的咖啡。", "corrected_sentence": "那个消费国的人喜欢买进口的咖啡。", "error_description": "量词错误：国家应用“个”，不用“只”。“只”多用于动物等，应改为“那个消费国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
