INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "船把东西送到的一个地方。", "primary_collocate": null, "pronunciation": "mù dì gǎng", "ipa": "mu˥˩ ti˥˩ kɑŋ˨˩", "syllable_count": 3, "sentences": [{"text": "这条船的目的港是青岛。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船长把目的港告诉了大家。", "target_word": "目的港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物要运到目的港才算送到。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这艘船的目的港吗？", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了目的港，工人开始卸货。", "target_word": "目的港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目的港在海边，离这儿很远。", "target_word": "目的港", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上画着船去目的港的路线。", "target_word": "目的港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船已经离开了上一个港口，正在驶向目的港。", "target_word": "目的港", "complexity_tier": "T3", "furigana": "chuán yǐ jīng lí kāi le shàng yí gè gǎng kǒu ， zhèng zài shǐ xiàng mù dì gǎng 。", "sentence_source": "generated"}, {"text": "货单上写着目的港的名字。", "target_word": "目的港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船走了十天，终于到了目的港。", "target_word": "目的港", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "目的港：船把东西送到的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f266c8f4-35c9-4740-9e77-94aae56e485a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目的港", "is_correct": true, "explanation": "正确：目的港是船把东西送到的地方，「这条船的目的港是青岛」成立。"}, {"text": "货物", "is_correct": false, "explanation": "语义：货物是被运送的东西，不是地点，不能说「这条船的货物是青岛」。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：国籍指国家归属，不能作为船的终点地点。"}, {"text": "船票", "is_correct": false, "explanation": "搭配：船票是票据，不能与「是 + 地名」搭配来表示目的地。"}], "explanations": {"目的港": "正确：目的港是船把东西送到的地方，「这条船的目的港是青岛」成立。", "货物": "语义：货物是被运送的东西，不是地点，不能说「这条船的货物是青岛」。", "国籍": "语义：国籍指国家归属，不能作为船的终点地点。", "船票": "搭配：船票是票据，不能与「是 + 地名」搭配来表示目的地。"}, "sentence_index": 0, "correct_answer": "目的港"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆货车的目的港是市中心的仓库吗？", "explanation": "这里应该用〈目的地〉。目的港只指船运的港口，货车的终点不能说成港口。"}, {"text": "这份快递的目的港是爷爷家吗？", "explanation": "这里应该用〈目的地〉。快递送达的终点是地址，不是港口，目的港只用于船运。"}, {"text": "货物要在目的港转船吗？", "explanation": "这里应该用〈中转港〉。转船发生在途中，目的港是最终到达的港口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目的港", "is_correct": true, "explanation": "正确：地图上画的船去的地方是目的港，符合语境。"}, {"text": "办公桌", "is_correct": false, "explanation": "语义：办公桌不是船能去的地方，「船去办公桌的路线」不成立。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是家具，不是可以前往的地点。"}, {"text": "牙刷", "is_correct": false, "explanation": "体貌：船与牙刷的体积相差悬殊，地图上不会画船去牙刷的路线。"}], "explanations": {"目的港": "正确：地图上画的船去的地方是目的港，符合语境。", "办公桌": "语义：办公桌不是船能去的地方，「船去办公桌的路线」不成立。", "课桌": "语义：课桌是家具，不是可以前往的地点。", "牙刷": "体貌：船与牙刷的体积相差悬殊，地图上不会画船去牙刷的路线。"}, "sentence_index": 6, "correct_answer": "目的港"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车走了十天，终于到了目的港。", "explanation": "这里应该用〈车站〉。火车到站，目的港只用于船运。"}, {"text": "飞机飞了十天，终于到了目的港。", "explanation": "这里应该用〈机场〉。飞机抵达机场，目的港只用于船运。"}, {"text": "船走了十天，终于把目的港开进了海里。", "explanation": "这里宾语颠倒：应说船驶入目的港，目的港是船要到达的地方，不能被开进海里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船已经驶进着目的港。", "corrected_sentence": "船已经驶进了目的港。", "error_description": "「驶进」是一次完成的动作，应用「了」表示完成，不能用「着」（着表示持续状态）。错误形式「驶进着目的港」应改为「驶进了目的港」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本目的港每天都很忙。", "corrected_sentence": "那个目的港每天都很忙。", "error_description": "量词用错：目的港应用量词「个」，不能用「本」（本用于书籍）。错误形式「那本目的港」应改为「那个目的港」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0c490a-f638-4245-a590-7d8209a188bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
