INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21576, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情需要很多人一起用手工作。", "primary_collocate": null, "pronunciation": "láo dòng mì jí xíng", "ipa": "lau˧˥ tʊŋ˥˩ mi˥˩ tɕi˧˥ ɕiŋ˧˥", "syllable_count": 5, "sentences": [{"text": "做鞋是劳动密集型的工作，要很多人一起做。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小厂是劳动密集型，工人都用手做东西。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摘苹果是劳动密集型的事，一个人做不完。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工做衣服属于劳动密集型。", "target_word": "劳动密集型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "劳动密集型的工作很累，要用很多力气。", "target_word": "劳动密集型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里办了一个劳动密集型的小工厂。", "target_word": "劳动密集型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "包饺子是劳动密集型，大家一起动手。", "target_word": "劳动密集型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家的茶园是劳动密集型，采茶要很多人。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种劳动密集型的活儿，机器不容易代替。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在劳动密集型的工厂工作，每天用手装玩具。", "target_word": "劳动密集型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勞動密集型", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事要很多人一起动手干活的类型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a92634-fb21-491d-bc46-54f0ac3ab9c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "劳动密集型", "is_correct": true, "explanation": "正确。句中说做鞋“要很多人一起做”，符合劳动密集型的特点。"}, {"text": "技术密集型", "is_correct": false, "explanation": "语义：技术密集型依靠技术和设备，与“要很多人一起做”的人力投入相矛盾。"}, {"text": "资本密集型", "is_correct": false, "explanation": "搭配：“资本密集型”说的是大量资金投入，不能与“要很多人一起做”的手工作业搭配。"}, {"text": "电子信息产业", "is_correct": false, "explanation": "语义：做鞋属于传统手工业，不是电子信息产业的工作。"}], "explanations": {"劳动密集型": "正确。句中说做鞋“要很多人一起做”，符合劳动密集型的特点。", "技术密集型": "语义：技术密集型依靠技术和设备，与“要很多人一起做”的人力投入相矛盾。", "资本密集型": "搭配：“资本密集型”说的是大量资金投入，不能与“要很多人一起做”的手工作业搭配。", "电子信息产业": "语义：做鞋属于传统手工业，不是电子信息产业的工作。"}, "sentence_index": 0, "correct_answer": "劳动密集型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家芯片厂是劳动密集型，车间里全是自动化设备。", "explanation": "这里应该用〈技术密集型〉。劳动密集型靠大量人力，句中说车间全是自动化设备，应该用〈技术密集型〉。"}, {"text": "造飞机是劳动密集型的行业，需要大量资金。", "explanation": "这里应该用〈资本密集型〉。劳动密集型强调人力投入，句中强调大量资金，应该用〈资本密集型〉。"}, {"text": "软件开发是劳动密集型的工作，主要靠脑力。", "explanation": "这里应该用〈知识密集型〉。劳动密集型靠人的体力与人数，句中说主要靠脑力，应该用〈知识密集型〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "劳动密集型", "is_correct": true, "explanation": "正确。包饺子要大家一起动手，符合劳动密集型的特点。"}, {"text": "知识密集型", "is_correct": false, "explanation": "语义：知识密集型靠脑力和技术，与“大家一起动手”的体力活动相反。"}, {"text": "房地产业", "is_correct": false, "explanation": "搭配：“包饺子”是家务活动，不与“房地产业”搭配。"}, {"text": "金融业", "is_correct": false, "explanation": "语义：包饺子是家务劳动，不属于金融业，与句意不符。"}], "explanations": {"劳动密集型": "正确。包饺子要大家一起动手，符合劳动密集型的特点。", "知识密集型": "语义：知识密集型靠脑力和技术，与“大家一起动手”的体力活动相反。", "房地产业": "搭配：“包饺子”是家务活动，不与“房地产业”搭配。", "金融业": "语义：包饺子是家务劳动，不属于金融业，与句意不符。"}, "sentence_index": 6, "correct_answer": "劳动密集型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爸爸是个劳动密集型的人，性格很温和。", "explanation": "这里应该用〈勤快〉。劳动密集型指依靠大量人力的产业或生产方式，句中用来形容一个人，把产业义误用到人身上；形容人勤劳应该用〈勤快〉。"}, {"text": "这座山是劳动密集型的，爬起来很累。", "explanation": "这里应该用〈费力〉。劳动密集型指依靠大量人力的生产方式，山不是生产活动，用它形容爬山的费力程度是误用；描述爬山费劲应该用〈费力〉。"}, {"text": "这次考试是劳动密集型的，题目很多。", "explanation": "这里应该用〈繁重〉。劳动密集型指依靠大量人力的生产方式，考试不属于生产活动；形容题目多、工作量大应该用〈繁重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家鞋厂很劳动密集型的，大部分工作都靠手工。", "corrected_sentence": "这家鞋厂是劳动密集型的，大部分工作都靠手工。", "error_description": "错误形式“很劳动密集型的”，正确形式“是劳动密集型的”。“劳动密集型”是类别词，不能用“很”修饰，判断类别要用“是……的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家服装厂劳动密集型的，车间里有很多工人。", "corrected_sentence": "这家服装厂是劳动密集型的，车间里有很多工人。", "error_description": "错误形式“劳动密集型的”前缺少判断词“是”，正确形式“是劳动密集型的”。判断某厂属于哪一类时，主语后必须用“是”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
