INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到自己想要的东西。", "primary_collocate": null, "pronunciation": "huò", "ipa": "xwo˥˩", "syllable_count": 1, "sentences": [{"text": "他等了很久，终于获自由。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力工作，终于获老板的信任。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店终于获政府批准。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的请求获老师同意。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于获去北京学习的机会。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在新城市获很多帮助。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一生善良，获大家尊重。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了三年，终于获自己想要的工作。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法获经理支持，大家很高兴。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王写了三封信，终于获一封回信。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲", "label": "繁体"}], "register": "书面", "sense_fingerprint": "书面语，经过努力或请求，得到自己想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a92634-fb21-491d-bc46-54f0ac3ab9c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21578, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获", "is_correct": true, "explanation": "获（huò）即得到自己想要的东西，是本词的读音和意思。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是活。"}, {"text": "户", "is_correct": false, "explanation": "hù（第四声）与 huò 韵母不同（u 与 uo），意思是户。"}, {"text": "伙", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是伙（伙伴）。"}], "explanations": {"获": "获（huò）即得到自己想要的东西，是本词的读音和意思。", "火": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。", "活": "huó（第二声）与 huò（第四声）声调不同，意思是活。", "户": "hù（第四声）与 huò 韵母不同（u 与 uo），意思是户。", "伙": "huǒ（第三声）与 huò（第四声）声调不同，意思是伙（伙伴）。"}, "sentence_index": null, "correct_answer": "获"}, "level_3": {"options": [{"text": "获", "is_correct": true, "explanation": "获：得到想要的东西，与“自由”搭配，符合“等了很久，终于得到”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃自由。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说穿自由。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，与“终于得到”的意思相反，句意不通。"}], "explanations": {"获": "获：得到想要的东西，与“自由”搭配，符合“等了很久，终于得到”的语境。", "吃": "搭配：“吃”的对象是食物，不能说吃自由。", "穿": "搭配：“穿”的对象是衣物，不能说穿自由。", "扔": "语义：“扔”是丢掉，与“终于得到”的意思相反，句意不通。"}, "sentence_index": 0, "correct_answer": "获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师很快获了我的请求。", "explanation": "这里应该用〈答应〉。获指得到想要的东西，回应别人的请求要用“答应”。"}, {"text": "他昨天获了一个电话，很惊讶。", "explanation": "这里应该用〈接到〉。获不用于接电话，接到电话要用“接到”。"}, {"text": "他把那只旧鞋获了。", "explanation": "这里应该用〈扔〉。获指得到自己想要的东西，丢掉不要的旧东西要用“扔”，不能用获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21578, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "获", "is_correct": true, "explanation": "获（huò）即得到自己想要的东西，是本词的读音和意思。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是活。"}, {"text": "伙", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是伙（伙伴）。"}, {"text": "护", "is_correct": false, "explanation": "hù（第四声）与 huò 只差韵母中的一个 o，声调相同，意思是保护。"}, {"text": "互", "is_correct": false, "explanation": "hù（第四声）与 huò 只差韵母中的一个 o，声调相同，意思是相互。"}], "explanations": {"获": "获（huò）即得到自己想要的东西，是本词的读音和意思。", "活": "huó（第二声）与 huò（第四声）声调不同，意思是活。", "伙": "huǒ（第三声）与 huò（第四声）声调不同，意思是伙（伙伴）。", "护": "hù（第四声）与 huò 只差韵母中的一个 o，声调相同，意思是保护。", "互": "hù（第四声）与 huò 只差韵母中的一个 o，声调相同，意思是相互。"}, "sentence_index": null, "correct_answer": "获"}, "level_3": {"options": [{"text": "获", "is_correct": true, "explanation": "获：得到，与“尊重”搭配，表示得到大家的尊重，符合语境。"}, {"text": "挡", "is_correct": false, "explanation": "语义：“挡”是阻拦，与“尊重”意思不合，句意不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球等，不能说踢尊重。"}, {"text": "抽", "is_correct": false, "explanation": "搭配：“抽”的对象是烟、签等，不能说抽尊重。"}], "explanations": {"获": "获：得到，与“尊重”搭配，表示得到大家的尊重，符合语境。", "挡": "语义：“挡”是阻拦，与“尊重”意思不合，句意不通。", "踢": "搭配：“踢”的对象是球等，不能说踢尊重。", "抽": "搭配：“抽”的对象是烟、签等，不能说抽尊重。"}, "sentence_index": 6, "correct_answer": "获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆获给我三本书。", "explanation": "这里应该用〈借给〉。获指得到想要的东西，把书借出去要用“借给”。"}, {"text": "他终于获了这个难题。", "explanation": "这里应该用〈解决〉。获不能用于难题，解决问题要用“解决”。"}, {"text": "公司获了他的损失。", "explanation": "这里应该用〈赔偿〉。获指得到想要的东西，补偿别人的损失要用“赔偿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_versi