INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "得到的好处。", "primary_collocate": null, "pronunciation": "shōu yì", "ipa": "ʂoʊ⁵⁵ i⁵¹", "syllable_count": 2, "sentences": [{"text": "读书的收益，不只是考试成绩。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次实习，我的收益比想象中大得多。", "target_word": "收益", "complexity_tier": "T3", "furigana": "shōu yì", "sentence_source": "generated"}, {"text": "这次谈话给了我很大的收益。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坚持锻炼的收益很明显，身体更健康了。", "target_word": "收益", "complexity_tier": "T3", "furigana": "shōu yì", "sentence_source": "generated"}, {"text": "学外语的收益，过几年才能看到。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书，收益会一点点积累。", "target_word": "收益", "complexity_tier": "T3", "furigana": "shōu yì", "sentence_source": "generated"}, {"text": "这个办法的收益比成本大。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛，对我来说最大的收益是经验。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的改变也会带来收益。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从这次合作中得到了不少收益。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收益率", "label": "复合"}], "register": "书面语", "sense_fingerprint": "做某事之后得到的一般好处、帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1532fc7-f679-448f-975d-e35ead7876dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收益", "is_correct": true, "explanation": "正确：读书带来的是知识、能力等一般好处，“收益”符合“不只是考试成绩”的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能作为读书带来的好处，与句意不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是物理量，不能说“读书的温度”，与句意冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语随意，与这句书面的论述不相称。"}], "explanations": {"收益": "正确：读书带来的是知识、能力等一般好处，“收益”符合“不只是考试成绩”的语境。", "颜色": "语义：颜色不能作为读书带来的好处，与句意不符。", "温度": "语义：温度是物理量，不能说“读书的温度”，与句意冲突。", "玩意儿": "语域：“玩意儿”口语随意，与这句书面的论述不相称。"}, "sentence_index": 0, "correct_answer": "收益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次失误的收益很严重，大家都很担心。", "explanation": "这里应该用〈后果〉。收益指得到的好处，不能说“很严重”；表示不好的结果应说〈后果〉。"}, {"text": "这次实习给我带来了一头收益。", "explanation": "这里应该用〈点〉。“收益”这类抽象事物用量词“点”，“头”多用于牲畜等具体事物。"}, {"text": "这段时间我白白浪费了很多收益。", "explanation": "这里应该用〈时间〉。收益指得到的好处，不能说“浪费”；被浪费的应是时间、精力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收益", "is_correct": true, "explanation": "正确：比较办法的好处与成本，“收益比成本大”指得到的好处超过付出，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能与“成本”比较大小，与句意冲突。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“比……大”可用于效果、数量，不能说“性格比成本大”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能与成本相比较大小，与评价办法的语境不相容。"}], "explanations": {"收益": "正确：比较办法的好处与成本，“收益比成本大”指得到的好处超过付出，符合语境。", "天气": "语义：天气是自然现象，不能与“成本”比较大小，与句意冲突。", "性格": "搭配：“比……大”可用于效果、数量，不能说“性格比成本大”。", "玩具": "语义：玩具不能与成本相比较大小，与评价办法的语境不相容。"}, "sentence_index": 6, "correct_answer": "收益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次合作付出了不少收益。", "explanation": "这里应该用〈代价〉。收益是得到的好处，不能与“付出”搭配。"}, {"text": "这次事故给他带来了很大的收益。", "explanation": "这里应该用〈伤害〉。收益是好的结果，不能用来描述事故带来的不好影响。"}, {"text": "他从银行借到了一大笔收益。", "explanation": "这里应该用〈资金〉。收益不能用“借”，“借”的是钱款或资金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次实习给我带来了一场收益。", "corrected_sentence": "这次实习给我带来了一点收益。", "error_description": "量词错误：“场”用于比赛、活动等，“收益”应用“点”，正确说法是“一点收益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次实习的收益的很大。", "corrected_sentence": "这次实习的收益很大。", "error_description": "“收益”后多出一个“的”，应去掉，正确说法是“这次实习的收益很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
