INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21586, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公司或产品做事的每一步，像一条链子，连起来让东西更有用。", "primary_collocate": null, "pronunciation": "jià zhí liàn", "ipa": "tɕja˥˩ ʈʂɻ̩˧˥ ljɛn˥˩", "syllable_count": 3, "sentences": [{"text": "老板请大家画出公司的价值链。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店的价值链从买豆子开始。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价值链上的每一步都不能出错。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条价值链很短，只有三个环节。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想让价值链上每一步都更快。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机的价值链包括设计、生产和卖货。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果价值链断了，东西就送不到客人手里。", "target_word": "价值链", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "他们公司的价值链很清楚。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看面包店的价值链是什么样的。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少一个环节，整个价值链就会受影响。", "target_word": "价值链", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "企业价值链", "label": "复合"}], "register": "中性", "sense_fingerprint": "公司做事的每一步连成一条链，一步一步让产品更有用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a92634-fb21-491d-bc46-54f0ac3ab9c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价值链", "is_correct": true, "explanation": "价值链：公司做事的各个环节连成的链条，可以画出来，符合语境。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指人或动物的身体温度，公司没有体温，画不出来。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“画出”不能跟“脾气”搭配，脾气看不见，句子不通。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味是嗅觉的对象，看不见，不能被画出来。"}], "explanations": {"价值链": "价值链：公司做事的各个环节连成的链条，可以画出来，符合语境。", "体温": "语义：体温指人或动物的身体温度，公司没有体温，画不出来。", "脾气": "搭配：“画出”不能跟“脾气”搭配，脾气看不见，句子不通。", "气味": "语义：气味是嗅觉的对象，看不见，不能被画出来。"}, "sentence_index": 0, "correct_answer": "价值链"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件古董的价值链很高，很多人都想买。", "explanation": "这里是“值多少钱”的意思，应该用〈值钱〉。价值链指公司做事的环节链条，不能用来说古董值不值钱。"}, {"text": "他的价值链很正，大家都信任他。", "explanation": "这里应该用〈价值观〉。价值观指人对事物的看法和准则，形容人的品行要用“价值观”，价值链不能用来说人的为人。"}, {"text": "这条价值链很亮，是金的。", "explanation": "这里应该用〈链子〉。价值链指公司做事的环节，不是金属做的饰品，不能说亮或是金的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价值链", "is_correct": true, "explanation": "价值链：公司做事的环节连成的链条，可以断开或受影响，符合语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指身体的重量，不能说断了，这里的句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“断”不能跟“颜色”搭配，颜色不会断。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是用来称呼的，不是可以断开的连接，句子不通。"}], "explanations": {"价值链": "价值链：公司做事的环节连成的链条，可以断开或受影响，符合语境。", "体重": "语义：体重指身体的重量，不能说断了，这里的句意不通。", "颜色": "搭配：“断”不能跟“颜色”搭配，颜色不会断。", "名字": "语义：名字是用来称呼的，不是可以断开的连接，句子不通。"}, "sentence_index": 6, "correct_answer": "价值链"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店今年赚了很多价值链。", "explanation": "这里应该用〈利润〉。“赚”的对象是钱或利润，价值链指做事的环节，不能被赚到。"}, {"text": "这款手机的价值链卖得很多。", "explanation": "这里应该用〈销量〉。说卖得多少要用“销量”，价值链指做事的环节，不是卖出的数量。"}, {"text": "他今天的价值链很好。", "explanation": "这里应该用〈心情〉。价值链指公司做事的环节链条，形容人的状态要用“心情”，不能用价值链。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这只价值链画清楚了。", "corrected_sentence": "我们把这条价值链画清楚了。", "error_description": "量词错误：“价值链”应使用量词“条”，写成“只”不对，“只”一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要把价值链理楚清。", "corrected_sentence": "我们要把价值链理清楚。", "error_description": "补语语序错误：结果补语“清楚”应紧跟动词“理”，写成“理楚清”不对，正确形式是“理清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
