INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以代表同一类事物中特点最明显的那个。", "primary_collocate": null, "pronunciation": "diǎn xíng", "ipa": "tjɛn˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这座房子是北京四合院的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个病例是这种病的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老虎是猫科动物中的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗是唐诗中山水诗的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜是四川菜的典型，又麻又辣。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苏州是江南水乡的典型。", "target_word": "典型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他上课总迟到，是懒散的典型。", "target_word": "典型", "complexity_tier": "T3", "furigana": "tā shàng kè zǒng chí dào, shì lǎn sǎn de diǎn xíng.", "sentence_source": "generated"}, {"text": "这个案例是老师给我们挑的典型。", "target_word": "典型", "complexity_tier": "T3", "furigana": "zhè ge àn lì shì lǎo shī gěi wǒ men tiāo de diǎn xíng.", "sentence_source": "generated"}, {"text": "这个例子很简单，是这类问题的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器是同类产品中的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "典型性", "label": "复合"}], "register": "中性", "sense_fingerprint": "同类事物中特点最明显的代表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad310530-f948-41d8-ba99-6f24dfeafbb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确答案。典型（diǎn xíng）：同类事物中特点最明显的代表。"}, {"text": "点醒", "is_correct": false, "explanation": "点醒（diǎn xǐng）与典型末字声调不同：xǐng（第三声）与 xíng（第二声），意思是提醒、点拨。"}, {"text": "脸型", "is_correct": false, "explanation": "脸型（liǎn xíng）与典型首字声母不同：l 与 d，意思是脸的形状。"}, {"text": "显形", "is_correct": false, "explanation": "显形（xiǎn xíng）与典型首字声母不同：x 与 d，意思是显露出原形。"}], "explanations": {"典型": "正确答案。典型（diǎn xíng）：同类事物中特点最明显的代表。", "点醒": "点醒（diǎn xǐng）与典型末字声调不同：xǐng（第三声）与 xíng（第二声），意思是提醒、点拨。", "脸型": "脸型（liǎn xíng）与典型首字声母不同：l 与 d，意思是脸的形状。", "显形": "显形（xiǎn xíng）与典型首字声母不同：x 与 d，意思是显露出原形。"}, "sentence_index": null, "correct_answer": "典型"}, "level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确。“典型”指同类中有代表性的事物，放在“北京四合院的___”处，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指买卖时的钱数，房子不能是某种建筑的价格，句意不通。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指一个地区的居民总数，与建筑类型无关，句意不通。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是庆祝的日子，房子不能是某种建筑的节日，句意不通。"}], "explanations": {"典型": "正确。“典型”指同类中有代表性的事物，放在“北京四合院的___”处，句意通顺。", "价格": "语义：价格指买卖时的钱数，房子不能是某种建筑的价格，句意不通。", "人口": "语义：人口指一个地区的居民总数，与建筑类型无关，句意不通。", "节日": "语义：节日是庆祝的日子，房子不能是某种建筑的节日，句意不通。"}, "sentence_index": 0, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两本书的典型不同，一本是小说，一本是诗集。", "explanation": "这里应该用〈类型〉。“典型”指同类中最有代表性的实例，不指作品的种类，这句应说“类型不同”。"}, {"text": "这首诗用了很多典型，读起来有些难懂。", "explanation": "这里应该用〈典故〉。“典型”指同类中有代表性的实例，不指诗中引用的历史故事，这里应说“典故”。"}, {"text": "这首诗的典型是大量描写山水。", "explanation": "这里应该用〈特征〉。“典型”指同类中最有代表性的事物本身，不能用来表示事物的特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确答案。典型（diǎn xíng）：同类事物中特点最明显的代表。"}, {"text": "电刑", "is_correct": false, "explanation": "电刑（diàn xíng）与典型首字声调不同：diàn（第四声）与 diǎn（第三声），指用电流执行的刑罚。"}, {"text": "脸型", "is_correct": false, "explanation": "脸型（liǎn xíng）与典型首字声母不同：l 与 d，意思是脸的形状。"}, {"text": "扁形", "is_correct": false, "explanation": "扁形（biǎn xíng）与典型首字声母不同：b 与 d，声调相同，意思是扁平的形状。"}], "explanations": {"典型": "正确答案。典型（diǎn xíng）：同类事物中特点最明显的代表。", "电刑": "电刑（diàn xíng）与典型首字声调不同：diàn（第四声）与 diǎn（第三声），指用电流执行的刑罚。", "脸型": "脸型（liǎn xíng）与典型首字声母不同：l 与 d，意思是脸的形状。", "扁形": "扁形（biǎn xíng）与典型首字声母不同：b 与 d，声调相同，意思是扁平的形状。"}, "sentence_index": null, "correct_answer": "典型"}, "level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确。“典型”指同类中有代表性的人，放在“懒散的___”处，句意通顺。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“懒散”修饰的是人的作风或性格，“懒散的寿命”不成词，不能与“懒散”搭配。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，不能指人的懒散程度，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用书，不能用来形容一个人的懒散，句意不通。"}], "explanations": {"典型": "正确。“典型”指同类中有代表性的人，放在“懒散的___”处，句意通顺。", "寿命": "搭配：“懒散”修饰的是人的作风或性格，“懒散的寿命”不成词，不能与“懒散”搭配。", "词典": "语义：词典是工具书，不能指人的懒散程度，句意不通。", "课本": "语义：课本是教学用书，不能用来形容一个人的懒散，句意不通。"}, "sentence_index": 6, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的典型很有名，每天都要排队。", "explanation": "这里应该用〈招牌〉。“典型”指同类中有代表性的实例，不指店里最出名的招牌菜。"}, {"text": "这次比赛他拿到了一个典型，非常开心。", "explanation": "这里应该用〈奖牌〉。“典型”指同类中有代表性的人或事物，不指比赛的奖项。"}, {"text": "他送给我一个飞机典型。", "explanation": "这里应该用〈模型〉。“典型”指同类中有代表性的实例，不指仿制的缩小品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家是印象派的一只典型。", "corrected_sentence": "这位画家是印象派的一个典型。", "error_description": "量词错误：“典型”指有代表性的人或事物，应与“个”搭配，写作“一个典型”；“只”多用于动物，不能修饰“典型”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山是中国北方山脉典型。", "corrected_sentence": "这座山是中国北方山脉的典型。", "error_description": "漏掉“的”：“中国北方山脉”作定语修饰“典型”，此处应写作“中国北方山脉的典型”，缺“的”则不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺境", "is_correct": true, "explanation": "反义：“顺境”指顺利的境遇，与“困境”构成反义。"}, {"text": "厨房", "is_correct": false, "explanation": "无反义关系：“厨房”指做饭的房间，与“困境”的意思不相对。"}, {"text": "粉笔", "is_correct": false, "explanation": "无反义关系：“粉笔”指写字用的条状物，与“困境”没有对立关系。"}, {"text": "田野", "is_correct": false, "explanation": "无反义关系：“田野”指广阔的田地，与“困境”不构成反义。"}], "correct_answer": "顺境", "explanations": {"顺境": "反义：“顺境”指顺利的境遇，与“困境”构成反义。", "厨房": "无反义关系：“厨房”指做饭的房间，与“困境”的意思不相对。", "粉笔": "无反义关系：“粉笔”指写字用的条状物，与“困境”没有对立关系。", "田野": "无反义关系：“田野”指广阔的田地，与“困境”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
