INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遇到很难的事情，不知道怎么办才好。", "primary_collocate": null, "pronunciation": "kùn jìng", "ipa": "kʰwən˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他丢了工作又生了病，陷入了困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在国外，钱也花完了，陷入困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对这样的困境，她不知道该怎么办。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困境时，可以找朋友商量。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨把路冲断了，我们陷入了困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的困境让老板几天睡不着觉。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想不出办法，只好向老师说明自己的困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们现在的困境，谁也解决不了。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要不放弃，总能走出困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他钱包丢了，手机也没电，一时陷入困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生存困境", "label": "复合"}, {"form": "经济困境", "label": "复合"}], "register": "中性", "sense_fingerprint": "困境:遇到难事，不知如何是好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a818043-95f1-4634-87a5-2d86d4a18143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困境", "is_correct": true, "explanation": "正确：“陷入了困境”指陷入难以应付的处境，符合丢工作、生病的语境。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是具体的物件，不能“陷入”，与丢工作、生病的处境不符。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“陷入”的宾语须是状况或境地，不能带“人数”这类表示数量的名词。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，不是可以“陷入”的状况，句意讲不通。"}], "explanations": {"困境": "正确：“陷入了困境”指陷入难以应付的处境，符合丢工作、生病的语境。", "报纸": "语义：报纸是具体的物件，不能“陷入”，与丢工作、生病的处境不符。", "人数": "搭配：“陷入”的宾语须是状况或境地，不能带“人数”这类表示数量的名词。", "早餐": "语义：早餐是一顿饭，不是可以“陷入”的状况，句意讲不通。"}, "sentence_index": 0, "correct_answer": "困境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她现在的困境很好，同事都很照顾她。", "explanation": "这里应该用〈处境〉。困境指艰难的处境，不能用来形容良好的情况。"}, {"text": "这位老师的教学达到了很高的困境。", "explanation": "这里应该用〈境界〉。困境指艰难的处境，不指教学所达到的水平。"}, {"text": "这次比赛的困境很好，他很满意。", "explanation": "这里应该用〈情况〉。困境指艰难的处境，不能用来形容比赛顺利的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困境", "is_correct": true, "explanation": "正确：“向老师说明自己的困境”指说明自己所处的艰难情况，与“想不出办法”的语境相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是外部的自然状况，不是可以向老师“说明”的个人处境，句意讲不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是需要向老师说明的处境，句意讲不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体外形特征，与“想不出办法”的困难情境无关。"}], "explanations": {"困境": "正确：“向老师说明自己的困境”指说明自己所处的艰难情况，与“想不出办法”的语境相合。", "天气": "语义：天气是外部的自然状况，不是可以向老师“说明”的个人处境，句意讲不通。", "早饭": "语义：早饭是一顿饭，不是需要向老师说明的处境，句意讲不通。", "身高": "体貌：“身高”指身体外形特征，与“想不出办法”的困难情境无关。"}, "sentence_index": 6, "correct_answer": "困境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他现在的困境不错，钱也够用了。", "explanation": "这里应该用〈境况〉。困境指艰难的处境，不能用来形容不错、钱够用的状况。"}, {"text": "这道数学题的困境不大，很快就做完了。", "explanation": "这里应该用〈困难〉。困难可指事情难做的程度，困境指人所处的艰难处境，不能用来说题目的难度。"}, {"text": "他晚年的困境很舒服，每天都去公园散步。", "explanation": "这里应该用〈境地〉。困境指艰难的处境，不能用来形容舒服的晚年生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她小时候也遇到困境过，所以很理解别人。", "corrected_sentence": "她小时候也遇到困境，所以很理解别人。", "error_description": "体标位置错误：“过”只能紧跟动词，不能紧跟宾语“困境”。删去“过”即可，也可改为“遇到过困境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次意外让他们的旅行陷入了很困境。", "corrected_sentence": "这次意外让他们的旅行陷入了困境。", "error_description": "错误在“很”：“困境”是名词，不能被“很”修饰。应说“陷入了困境”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
