INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21596, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "与别的事物相比较而言，在某一方面程度较为……。", "primary_collocate": null, "pronunciation": "xiāng duì", "ipa": "ɕiaŋ˥ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的冬天相对暖和。", "target_word": "相对", "complexity_tier": "T3", "furigana": "zhè gè chéng shì de dōng tiān xiāng duì nuǎn huo", "sentence_source": "generated"}, {"text": "相对来说，坐地铁比开车快。", "target_word": "相对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个办法，相对而言，第二个更简单。", "target_word": "相对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家相对安静，离大路比较远。", "target_word": "相对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年夏天相对凉快，不太热。", "target_word": "相对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作相对轻松，但是钱不多。", "target_word": "相对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语相对不错，可是写字还不行。", "target_word": "相对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小镇的生活相对慢一些。", "target_word": "相对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路相对短，我们走这条吧。", "target_word": "相对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得红色的包相对好看。", "target_word": "相对", "complexity_tier": "T3", "furigana": "wǒ juéde hóngsè de bāo xiāng duì hǎokàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "相對", "label": "繁体"}, {"form": "相对地", "label": "副词形式"}, {"form": "相对论", "label": "复合词"}], "register": "中性", "sense_fingerprint": "放在一起比较后，在某方面显得更……（相对而言）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 今年夏天 (Zipf 3.15), 凉快 (Zipf 3.23), 太热 (Zipf 3.16)']::text[], 'c4ee3da4-4c99-4c2d-aaed-c51fb6a3dd04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相对", "is_correct": true, "explanation": "正确：“相对”表示比较而言，句中说这个城市的冬天比别处暖和。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向如此，与“冬天暖和”这一描述不合。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示急促，不能用来修饰“暖和”这类状态。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示义务或必要，不能用来修饰描述状态的“暖和”。"}], "explanations": {"相对": "正确：“相对”表示比较而言，句中说这个城市的冬天比别处暖和。", "从来": "语义：“从来”表示一向如此，与“冬天暖和”这一描述不合。", "赶紧": "搭配：“赶紧”表示急促，不能用来修饰“暖和”这类状态。", "必须": "语义：“必须”表示义务或必要，不能用来修饰描述状态的“暖和”。"}, "sentence_index": 0, "correct_answer": "相对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们相对去公园散步。", "explanation": "这里应该用〈一起〉。“相对”表示两者比较，不表示“共同做某事”。"}, {"text": "学生相对不能迟到。", "explanation": "这里应该用〈绝对〉。“相对”表示比较、有限度，不能表示“绝对不能”这种无条件的要求。"}, {"text": "我们班相对有三十个人。", "explanation": "这里应该用〈大约〉。“相对”用于比较性的描述，不用于确定的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相对", "is_correct": true, "explanation": "正确：“相对”表示比较而言，句中说他的汉语比较好，但写字还不行。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“汉语不错”这一状态不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，不能用来修饰“不错”这类评价。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同，不能用来修饰“汉语不错”。"}], "explanations": {"相对": "正确：“相对”表示比较而言，句中说他的汉语比较好，但写字还不行。", "忽然": "语义：“忽然”表示突然发生，与“汉语不错”这一状态不合。", "立刻": "语义：“立刻”表示马上，不能用来修饰“不错”这类评价。", "一起": "搭配：“一起”表示共同，不能用来修饰“汉语不错”。"}, "sentence_index": 6, "correct_answer": "相对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你等一下，我相对就到。", "explanation": "这里应该用〈马上〉。“相对”表示比较，不表示时间上的立即。"}, {"text": "他相对一个人住在这里。", "explanation": "这里应该用〈独自〉。“相对”表示比较，不表示“单独”。"}, {"text": "我们相对走散了。", "explanation": "这里应该用〈分开〉。“相对”指两者面对面或相互比较，不表示“走散”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭馆的菜相对相对便宜。", "corrected_sentence": "这家饭馆的菜相对便宜。", "error_description": "错误形式：“相对相对便宜”。正确形式：“相对便宜”。“相对”是副词，只能用一次，不能重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的英语相对了好一些。", "corrected_sentence": "他的英语相对好一些。", "error_description": "错误形式：“相对了”。正确形式：“相对”。“相对”作副词，不能带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
