INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "还没加工过的东西，比如地里刚摘的菜。", "primary_collocate": null, "pronunciation": "chū jí chǎn pǐn", "ipa": "ʈʂʰu˥ tɕi˧˥ ʈʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 4, "sentences": [{"text": "刚从地里摘的菜是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些苹果刚摘下来，还是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛奶加工以前，只是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民把初级产品拉到工厂去加工。", "target_word": "初级产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没洗没切的菜都是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把初级产品做成了罐头。", "target_word": "初级产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚收来的棉花还没加工，是初级产品。", "target_word": "初级产品", "complexity_tier": "T3", "furigana": "gāng shōu lái de mián huā hái méi jiā gōng, shì chū jí chǎn pǐn.", "sentence_source": "generated"}, {"text": "初级产品便宜，加工以后就贵了。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖的是初级产品，比如新鲜的菜和肉。", "target_word": "初级产品", "complexity_tier": "T3", "furigana": "zhè jiā diàn mài de shì chū jí chǎn pǐn, bǐ rú xīn xiān de cài hé ròu.", "sentence_source": "generated"}, {"text": "麦子磨成面粉以前，是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "初級產品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常说法：还没加工的东西，如刚摘的菜、刚收的棉花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad310530-f948-41d8-ba99-6f24dfeafbb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初级产品", "is_correct": true, "explanation": "正确。刚从地里摘的菜还没加工，属于“初级产品”，放在“是___”处，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指钱数，菜不能是价格，句意不通。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，菜不能是工厂，句意不通。"}, {"text": "夜晚", "is_correct": false, "explanation": "搭配：“夜晚”是时间词，不能用来说明菜的性质，这里不搭配。"}], "explanations": {"初级产品": "正确。刚从地里摘的菜还没加工，属于“初级产品”，放在“是___”处，句意通顺。", "价格": "语义：价格指钱数，菜不能是价格，句意不通。", "工厂": "语义：工厂是生产场所，菜不能是工厂，句意不通。", "夜晚": "搭配：“夜晚”是时间词，不能用来说明菜的性质，这里不搭配。"}, "sentence_index": 0, "correct_answer": "初级产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌是初级产品，大家都喜欢听。", "explanation": "这里应该用〈作品〉。“初级产品”指还没加工过的东西，不能用来指歌曲这类作品。"}, {"text": "这盒饼干已经烤好包装，是初级产品。", "explanation": "这里应该用〈成品〉。饼干已经烤好、包装完成，是加工过的东西，不再是“初级产品”。"}, {"text": "这桌菜都是初级产品，已经做好了。", "explanation": "这里应该用〈熟菜〉。“初级产品”指还没加工过的东西，做好的菜已经不是初级产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初级产品", "is_correct": true, "explanation": "正确。刚收来的棉花还没加工，属于“初级产品”，放在“是___”处，句意通顺。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是特定的日子，棉花不能是节日，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用书，棉花不能是课本，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”用于人的性情，不能用来说明棉花，这里不搭配。"}], "explanations": {"初级产品": "正确。刚收来的棉花还没加工，属于“初级产品”，放在“是___”处，句意通顺。", "节日": "语义：节日是特定的日子，棉花不能是节日，句意不通。", "课本": "语义：课本是教学用书，棉花不能是课本，句意不通。", "脾气": "搭配：“脾气”用于人的性情，不能用来说明棉花，这里不搭配。"}, "sentence_index": 6, "correct_answer": "初级产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱鸡蛋已经做成了蛋糕，是初级产品。", "explanation": "这里应该用〈成品〉。蛋糕是做好的东西，不是还没加工过的东西，不能称为“初级产品”。"}, {"text": "棉花做成衣服以后，是初级产品。", "explanation": "这里应该用〈成品〉。衣服已经加工完成，“初级产品”指加工前的东西。"}, {"text": "这批菜已经洗好切好、装进了盒子，是初级产品。", "explanation": "这里应该用〈净菜〉。“初级产品”指还没加工过的东西，洗切装盒的菜已经加工过了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这筐草莓是刚摘下来初级产品。", "corrected_sentence": "这筐草莓是刚摘下来的初级产品。", "error_description": "漏掉“的”：“刚摘下来”修饰“初级产品”时要加“的”，应为“刚摘下来的初级产品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些芒果是刚摘下的初级产品的。", "corrected_sentence": "这些芒果是刚摘下的初级产品。", "error_description": "多加了一个“的”：“是……的初级产品”结构已完整，句末不需要再加“的”，应为“这些芒果是刚摘下的初级产品。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西做成最初步的样子。", "primary_collocate": null, "pronunciation": "chū jiā gōng", "ipa": "ʈʂʰu˥ tɕja˥ kʊŋ˥", "syllable_count": 3, "sentences": [{"text": "茶叶摘下来以后，要先进行初加工。", "target_word": "初加工", "complexity_tier": "T3", "furigana": "chū jiāgōng", "sentence_source": "generated"}, {"text": "这家工厂只做水果的初加工。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把牛奶初加工后，卖给大工厂。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初加工以后，鱼可以放很久。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里新建了一个初加工的小厂。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些木头已经初加工过了。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉类初加工要注意卫生。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆先经过初加工，再运到国外。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在初加工车间工作了五年。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不做成品，只做初加工。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "初加工产品", "label": "复合"}], "register": "中性", "sense_fingerprint": "对原料做最初步的处理，还不是成品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a92634-fb21-491d-bc46-54f0ac3ab9c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初加工", "is_correct": true, "explanation": "正确。茶叶摘下来以后要先进行初加工，符合把原料做最初步处理的意思。"}, {"text": "深加工", "is_correct": false, "explanation": "语义：深加工是后续的深入处理，与“先”以及“摘下来以后”的先后顺序矛盾。"}, {"text": "精加工", "is_correct": false, "explanation": "语义：精加工也是后续工序，不能放在“先”的位置。"}, {"text": "采摘", "is_correct": false, "explanation": "搭配：茶叶已经“摘下来”，再说“进行采摘”搭配不当。"}], "explanations": {"初加工": "正确。茶叶摘下来以后要先进行初加工，符合把原料做最初步处理的意思。", "深加工": "语义：深加工是后续的深入处理，与“先”以及“摘下来以后”的先后顺序矛盾。", "精加工": "语义：精加工也是后续工序，不能放在“先”的位置。", "采摘": "搭配：茶叶已经“摘下来”，再说“进行采摘”搭配不当。"}, "sentence_index": 0, "correct_answer": "初加工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用慢火把排骨初加工，直到骨头酥烂。", "explanation": "这里应该用〈炖〉。初加工只是最初步的处理，把排骨用慢火炖到骨头酥烂属于烹饪，应该用〈炖〉。"}, {"text": "稻子成熟后要初加工。", "explanation": "这里应该用〈收获〉。初加工发生在收获之后，稻子成熟时要做的是〈收获〉。"}, {"text": "果农每天初加工草莓，一颗一颗地摘。", "explanation": "这里应该用〈采摘〉。初加工是对已经采下来的原料做最初步的处理，一颗颗地摘草莓是采摘，应该用〈采摘〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初加工", "is_correct": true, "explanation": "正确。肉类初加工是对肉类做最初步的处理，所以要注意卫生。"}, {"text": "种植", "is_correct": false, "explanation": "语义：肉类不能种植，“种植”与句中的肉类对象不相符。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于农作物，不与“肉类”搭配。"}, {"text": "设计", "is_correct": false, "explanation": "语义：肉类不能设计，“设计”与“肉类”的对象不符。"}], "explanations": {"初加工": "正确。肉类初加工是对肉类做最初步的处理，所以要注意卫生。", "种植": "语义：肉类不能种植，“种植”与句中的肉类对象不相符。", "收割": "搭配：“收割”用于农作物，不与“肉类”搭配。", "设计": "语义：肉类不能设计，“设计”与“肉类”的对象不符。"}, "sentence_index": 6, "correct_answer": "初加工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "师傅亲手初加工了这件木雕。", "explanation": "这里应该用〈制作〉。木雕是做好的工艺品，“初加工”只是最初步的处理，应该用〈制作〉。"}, {"text": "妈妈每天初加工碗筷。", "explanation": "这里应该用〈清洗〉。碗筷不是原料，初加工针对原料，清洗餐具应该用〈清洗〉。"}, {"text": "工人在初加工房子。", "explanation": "这里应该用〈装修〉。房子不是原料，初加工针对原料，装修房屋应该用〈装修〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些大豆已经好初加工了，可以拿去榨油。", "corrected_sentence": "这些大豆已经初加工了，可以拿去榨油。", "error_description": "错误形式“好初加工”，多出了结果补语“好”。“好”只能放在动词之后，不能放在动词前；这句只需“已经初加工了”，不需要补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批肉已经过初加工了。", "corrected_sentence": "这批肉已经初加工了。", "error_description": "错误形式“过初加工”，“过”放在动词之前不对，应放在动词之后。改为“已经初加工了”或“已经初加工过了”均可，但“过”不能放在“初加工”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏高", "is_correct": true, "explanation": "正确：“偏高”与“偏低”构成反义，指高度比一般的高。"}, {"text": "结实", "is_correct": false, "explanation": "与“偏低”没有反义关系，“结实”指坚固耐用。"}, {"text": "大方", "is_correct": false, "explanation": "与“偏低”没有反义关系，“大方”指不拘小节或举止自然。"}, {"text": "整齐", "is_correct": false, "explanation": "与“偏低”没有反义关系，“整齐”指有秩序、不杂乱。"}], "correct_answer": "偏高", "explanations": {"偏高": "正确：“偏高”与“偏低”构成反义，指高度比一般的高。", "结实": "与“偏低”没有反义关系，“结实”指坚固耐用。", "大方": "与“偏低”没有反义关系，“大方”指不拘小节或举止自然。", "整齐": "与“偏低”没有反义关系，“整齐”指有秩序、不杂乱。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏高", "is_correct": true, "explanation": "正确：“偏高”与“偏低”构成反义，指高度比一般的高。"}, {"text": "活泼", "is_correct": false, "explanation": "与“偏低”没有反义关系，“活泼”指性格开朗、爱动。"}, {"text": "安静", "is_correct": false, "explanation": "与“偏低”没有反义关系，“安静”指没有声音或很少动静。"}, {"text": "严肃", "is_correct": false, "explanation": "与“偏低”没有反义关系，“严肃”指态度庄重、不随便。"}], "correct_answer": "偏高", "explanations": {"偏高": "正确：“偏高”与“偏低”构成反义，指高度比一般的高。", "活泼": "与“偏低”没有反义关系，“活泼”指性格开朗、爱动。", "安静": "与“偏低”没有反义关系，“安静”指没有声音或很少动静。", "严肃": "与“偏低”没有反义关系，“严肃”指态度庄重、不随便。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高度比一般的矮。", "primary_collocate": null, "pronunciation": "piān dī", "ipa": "pʰjɛn˥ ti˥", "syllable_count": 2, "sentences": [{"text": "这把小凳子偏低，适合小朋友坐。", "target_word": "偏低", "complexity_tier": "T3", "furigana": "piān dī", "sentence_source": "generated"}, {"text": "这张桌子偏低，我写字不舒服。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这扇门偏低，高个子要弯腰。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个窗台偏低，小孩容易爬上去。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子偏低，坐着腿不舒服。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的台面偏低，做饭要弯着腰。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身高偏低，所以想穿高跟鞋。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个篮球架偏低，比赛时不能用。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆自行车的座椅偏低，适合小孩骑。", "target_word": "偏低", "complexity_tier": "T3", "furigana": "piān dī", "sentence_source": "generated"}, {"text": "这座桥的栏杆偏低，孩子走在上面不安全。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "个子或物体的高度比一般的矮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad310530-f948-41d8-ba99-6f24dfeafbb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏低", "is_correct": true, "explanation": "正确：“偏低”指高度比一般的矮，适合小朋友坐。"}, {"text": "偏大", "is_correct": false, "explanation": "语义：句中已说“小凳子”，“偏大”与之矛盾，也不适合小朋友坐。"}, {"text": "偏胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能用来形容凳子。"}, {"text": "偏远", "is_correct": false, "explanation": "语义：“偏远”指地方离城市远，不能形容凳子的高矮。"}], "explanations": {"偏低": "正确：“偏低”指高度比一般的矮，适合小朋友坐。", "偏大": "语义：句中已说“小凳子”，“偏大”与之矛盾，也不适合小朋友坐。", "偏胖": "体貌：“胖”形容人或动物的体形，不能用来形容凳子。", "偏远": "语义：“偏远”指地方离城市远，不能形容凳子的高矮。"}, "sentence_index": 0, "correct_answer": "偏低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木板的厚度偏低，承受不了重东西。", "explanation": "这里应该用〈偏薄〉。厚薄要说“厚”或“薄”，“偏低”指高度，不用于厚度。"}, {"text": "这扇门的宽度偏低，我的行李箱进不去。", "explanation": "这里应该用〈偏窄〉。“偏低”指高度，宽度只说宽或窄。"}, {"text": "这根绳子的长度偏低，绑不住箱子。", "explanation": "这里应该用〈偏短〉。长短要说“长”或“短”，“偏低”指高度，不用于长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏低", "is_correct": true, "explanation": "正确：身高比一般的矮，所以她想穿高跟鞋。"}, {"text": "偏高", "is_correct": false, "explanation": "语义：身高高就不需要靠高跟鞋增高，与“所以想穿高跟鞋”的因果相矛盾。"}, {"text": "偏宽", "is_correct": false, "explanation": "搭配：“宽”说的是宽度，不能用来形容身高。"}, {"text": "偏重", "is_correct": false, "explanation": "搭配：“重”说的是重量，身高不能用重量来形容。"}], "explanations": {"偏低": "正确：身高比一般的矮，所以她想穿高跟鞋。", "偏高": "语义：身高高就不需要靠高跟鞋增高，与“所以想穿高跟鞋”的因果相矛盾。", "偏宽": "搭配：“宽”说的是宽度，不能用来形容身高。", "偏重": "搭配：“重”说的是重量，身高不能用重量来形容。"}, "sentence_index": 6, "correct_answer": "偏低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的体积偏低，能装下两件大衣。", "explanation": "这里应该用〈偏大〉。体积只说大或小，“偏低”不能用于体积。"}, {"text": "这间屋子的面积偏低，放不下两张床。", "explanation": "这里应该用〈偏小〉。面积只说大或小，“偏低”指高度，不用于面积。"}, {"text": "这个水杯的容量偏低，装不了一升水。", "explanation": "这里应该用〈偏小〉。容量只说大或小，“偏低”指高度，不用于容量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张沙发偏低着，老人坐起来很吃力。", "corrected_sentence": "这张沙发偏低，老人坐起来很吃力。", "error_description": "错误：“偏低着”。正确：“偏低”。形容词不能加“着”表示状态，应直接说“偏低”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个洗手台被偏低，孩子用起来很方便。", "corrected_sentence": "这个洗手台偏低，孩子用起来很方便。", "error_description": "错误：“被偏低”。正确：“偏低”。“偏低”是形容词，不能直接放在“被”后构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ba6df40-c561-4b97-bedc-9ff97443ecd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
