INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把许多小东西合在一起，变成一个更大的东西。", "primary_collocate": null, "pronunciation": "guī mó huà", "ipa": "kwei̯˥ mwo˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "村里把许多小农田规模化，合成一大片。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几块小田地规模化以后，变成了一大片良田。", "target_word": "规模化", "complexity_tier": "T3", "furigana": "jǐ kuài xiǎo tián dì guī mó huà yǐ hòu, biàn chéng le yí dà piàn liáng tián", "sentence_source": "generated"}, {"text": "他们想把零散的茶园规模化。", "target_word": "规模化", "complexity_tier": "T3", "furigana": "tā men xiǎng bǎ líng sǎn de chá yuán guī mó huà", "sentence_source": "generated"}, {"text": "小果园规模化后，管理更方便了。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把分散的小鱼塘规模化，养鱼更容易。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民把小块土地规模化，一起种玉米。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "零散的小菜地规模化后，成了一大片菜地。", "target_word": "规模化", "complexity_tier": "T3", "furigana": "líng sǎn de xiǎo cài dì guī mó huà hòu, chéng le yí dà piàn cài dì", "sentence_source": "generated"}, {"text": "要把小块荒地规模化，先要大家同意。", "target_word": "规模化", "complexity_tier": "T3", "furigana": "yào bǎ xiǎo kuài huāng dì guī mó huà, xiān yào dà jiā tóng yì", "sentence_source": "generated"}, {"text": "规模化以后，十几块小田变成了一大块田。", "target_word": "规模化", "complexity_tier": "T3", "furigana": "guī mó huà yǐ hòu, shí jǐ kuài xiǎo tián biàn chéng le yí dà kuài tián", "sentence_source": "generated"}, {"text": "政府帮助农民把小菜园规模化。", "target_word": "规模化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "规模化经营", "label": "复合"}, {"form": "規模化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把分散的小单位合并成更大的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '393bfa21-a379-477d-b422-bab907e99afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规模化", "is_correct": true, "explanation": "正确：“规模化”指把许多小的东西合在一起变成更大的，与“合成一大片”一致。"}, {"text": "分割", "is_correct": false, "explanation": "语义：分割是把整体切开，与“合成一大片”的结果正相反。"}, {"text": "荒废", "is_correct": false, "explanation": "语义：荒废是土地不再耕种，荒废的农田不能合成一大片。"}, {"text": "翻耕", "is_correct": false, "explanation": "搭配：翻耕是翻松土地的农活，不能与“合成一大片”组成合理的因果关系。"}], "explanations": {"规模化": "正确：“规模化”指把许多小的东西合在一起变成更大的，与“合成一大片”一致。", "分割": "语义：分割是把整体切开，与“合成一大片”的结果正相反。", "荒废": "语义：荒废是土地不再耕种，荒废的农田不能合成一大片。", "翻耕": "搭配：翻耕是翻松土地的农活，不能与“合成一大片”组成合理的因果关系。"}, "sentence_index": 0, "correct_answer": "规模化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把这一大块蛋糕规模化成了几小块。", "explanation": "这里应该用〈拆分〉。拆分是把整体分开，与“规模化”的意思正相反。"}, {"text": "他把一大箱子的东西规模化，分成了许多小包。", "explanation": "这里应该用〈分装〉。分装是把东西分成小份，“规模化”是把小的合成大的，不能用来描述分装。"}, {"text": "这个小孩子的力气规模化了。", "explanation": "这里应该用〈增强〉。增强指力量变得更强；“规模化”指把许多小东西合成大的，不用于力气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规模化", "is_correct": true, "explanation": "正确：“零散的小菜地规模化后”指把许多小块合成一大片，与“成了一大片菜地”一致。"}, {"text": "分散", "is_correct": false, "explanation": "语义：分散是散开，与“成了一大片菜地”的结果正相反。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：拆开是把整体分开，只会得到更多小块，不能“成了一大片”。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：拍摄是用镜头记录影像，不能用来描述小菜地合成大片的变化。"}], "explanations": {"规模化": "正确：“零散的小菜地规模化后”指把许多小块合成一大片，与“成了一大片菜地”一致。", "分散": "语义：分散是散开，与“成了一大片菜地”的结果正相反。", "拆开": "语义：拆开是把整体分开，只会得到更多小块，不能“成了一大片”。", "拍摄": "搭配：拍摄是用镜头记录影像，不能用来描述小菜地合成大片的变化。"}, "sentence_index": 6, "correct_answer": "规模化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河要向东规模化。", "explanation": "这里应该用〈延伸〉。延伸指向某个方向伸展；“规模化”指把许多小东西合成大的，河流不能这样。"}, {"text": "这条路的宽度规模化了，车子也多了。", "explanation": "这里应该用〈加宽〉。加宽指使宽度变大；“规模化”指把许多小东西合成大的，不用于宽度。"}, {"text": "他把这群孩子规模化了。", "explanation": "这里应该用〈组织〉。组织指把人聚集起来编成团体；“规模化”指把许多小东西合在一起，不用于指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "几位农民把各自的小果园规模化下来，统一管理。", "corrected_sentence": "几位农民把各自的小果园规模化起来，统一管理。", "error_description": "趋向补语错误：把许多小东西合成大的，要用“起来”表示聚合，应说“规模化起来”，不能说“规模化下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们计划把几座小厂房规模化过，统一生产。", "corrected_sentence": "我们计划把几座小厂房规模化，统一生产。", "error_description": "时态错误：“计划”指将来要做的事，“规模化”还没有发生，不能加表示经历的“过”。应说“计划把……规模化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd775c96a-e041-4f12-b9ac-98092e764734') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21634, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21634, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个东西和另一个东西连在一起，像火车车厢一节接一节。", "primary_collocate": null, "pronunciation": "lián suǒ", "ipa": "ljɛn˧˥ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "车厢靠铁钩连锁，火车就能拉很多货。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "chē xiāng kào tiě gōu lián suǒ, huǒ chē jiù néng lā hěn duō huò.", "sentence_source": "generated"}, {"text": "这些铁环一个扣一个，互相连锁。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "zhè xiē tiě huán yí gè kòu yí gè, hù xiāng lián suǒ.", "sentence_source": "generated"}, {"text": "这些塑料环一个扣一个地连锁，拼成一个大圆圈。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "zhè xiē sù liào huán yí gè kòu yí gè de lián suǒ, pīn chéng yí gè dà yuán quān.", "sentence_source": "generated"}, {"text": "把几节小车厢连锁起来，就像一列火车。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "积木一块接一块，连锁起来很长。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条项链的每个小环都连锁着。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先把纸环连锁，再做成一条彩带。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "tā xiān bǎ zhǐ huán lián suǒ, zài zuò chéng yì tiáo cǎi dài.", "sentence_source": "generated"}, {"text": "两列火车的车厢连锁以后，才能一起走。", "target_word": "连锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车链条的每一节都紧密连锁。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "zì xíng chē liàn tiáo de měi yí jié dōu jǐn mì lián suǒ.", "sentence_source": "generated"}, {"text": "这几块木板靠卡扣连锁，才不会散开。", "target_word": "连锁", "complexity_tier": "T3", "furigana": "zhè jǐ kuài mù bǎn kào kǎ kòu lián suǒ, cái bú huì sàn kāi.", "sentence_source": "generated"}], "morphological_forms": [{"form": "连锁着", "label": "体标"}, {"form": "连锁了", "label": "体标"}, {"form": "連鎖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西一个接一个地连在一起，像车厢一节接一节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f14b0bd-4442-4a82-ad1b-855548461c16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连锁", "is_correct": true, "explanation": "正确：“连锁”指车厢靠钩子一节接一节相连，与“火车就能拉很多货”前后一致。"}, {"text": "分开", "is_correct": false, "explanation": "语义：车厢分开就无法一起拉货，与后半句“火车就能拉很多货”矛盾。"}, {"text": "撞坏", "is_correct": false, "explanation": "语义：车厢被撞坏后不能正常连接拉货，与后半句矛盾。"}, {"text": "拆卸", "is_correct": false, "explanation": "语义：“拆卸”指把连在一起的东西拆开，与“火车就能拉很多货”相矛盾。"}], "explanations": {"连锁": "正确：“连锁”指车厢靠钩子一节接一节相连，与“火车就能拉很多货”前后一致。", "分开": "语义：车厢分开就无法一起拉货，与后半句“火车就能拉很多货”矛盾。", "撞坏": "语义：车厢被撞坏后不能正常连接拉货，与后半句矛盾。", "拆卸": "语义：“拆卸”指把连在一起的东西拆开，与“火车就能拉很多货”相矛盾。"}, "sentence_index": 0, "correct_answer": "连锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用胶水把两张纸连锁在一起。", "explanation": "这里应该用〈连接〉。“连锁”指东西一节接一节像链条那样相连，两张纸粘在一起不构成一连串。"}, {"text": "他把三个苹果连锁起来，收进篮子里。", "explanation": "这里应该用〈装〉。“连锁”指东西一节接一节相连，苹果只是放在一起，不构成这种关系。"}, {"text": "医生用线把伤口连锁起来。", "explanation": "这里应该用〈缝合〉。“连锁”用于东西一节接一节相连，伤口要用线缝合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连锁", "is_correct": true, "explanation": "正确：“连锁”指纸环一节接一节连起来，与“再做成一条彩带”相合。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：纸环撕碎后无法再做成彩带，与后半句“再做成一条彩带”矛盾。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：纸环被点燃就毁了，不可能再做彩带，与语境矛盾。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐器或曲子，不能用于纸环，搭配不当。"}], "explanations": {"连锁": "正确：“连锁”指纸环一节接一节连起来，与“再做成一条彩带”相合。", "撕碎": "语义：纸环撕碎后无法再做成彩带，与后半句“再做成一条彩带”矛盾。", "点燃": "语义：纸环被点燃就毁了，不可能再做彩带，与语境矛盾。", "演奏": "搭配：“演奏”的对象是乐器或曲子，不能用于纸环，搭配不当。"}, "sentence_index": 6, "correct_answer": "连锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用电焊把两根钢管连锁在一起。", "explanation": "这里应该用〈焊接〉。焊接靠熔化金属接合，而“连锁”是部件一节接一节相扣，不是熔接。"}, {"text": "他用锅把米连锁煮熟了。", "explanation": "这里应该用〈煮〉。“连锁”指东西一节接一节相连，煮米应说煮，不能说连锁。"}, {"text": "他把三本书连锁放在桌上。", "explanation": "这里应该用〈叠〉。书只是摞放，并没有一节接一节相扣，所以不说“连锁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个铁环要连锁下来才结实。", "corrected_sentence": "这几个铁环要连锁起来才结实。", "error_description": "“连锁”后的补语应为“起来”，表示连成一片；“下来”表示由高处往低处，与“连锁”搭配不当，应改为“起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把两段绳子连锁出来，才能拉动重物。", "corrected_sentence": "他把两段绳子连锁起来，才能拉动重物。", "error_description": "“出来”表示由内向外显现，与“连锁”不搭配；连成一体应说“连锁起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80f4dc18-7450-4861-95d7-7e7e97b3ba28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
