INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21640, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "格局就是东西摆的样子或者人想事情的范围。", "primary_collocate": null, "pronunciation": "gé jú", "ipa": "kɤ˧˥ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "这个房子的格局很好，客厅很大。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想事情的格局很大，不只看眼前。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的格局很特别。", "target_word": "格局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王做事格局小，总是只想自己。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司有了新老板，格局变了。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家的格局是三个房间一个厨房。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，看问题要有大格局。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城市的格局很整齐。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的格局不一样，所以走得更远。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间办公室的格局，我不太喜欢。", "target_word": "格局", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新格局", "label": "复合词"}], "register": "中性", "sense_fingerprint": "事物的布局结构，或人看问题的眼界和范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ee3da4-4c99-4c2d-aaed-c51fb6a3dd04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "格局", "is_correct": true, "explanation": "正确：“格局”指房屋的布局，句中说这个房子的布局很好、客厅很大。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，不能用来形容房子。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“好”不用来形容“年龄”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是房屋的属性，不能说“很好”。"}], "explanations": {"格局": "正确：“格局”指房屋的布局，句中说这个房子的布局很好、客厅很大。", "脾气": "语义：“脾气”指人的性情，不能用来形容房子。", "年龄": "搭配：“好”不用来形容“年龄”。", "作业": "语义：“作业”不是房屋的属性，不能说“很好”。"}, "sentence_index": 0, "correct_answer": "格局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗面的格局很香。", "explanation": "这里应该用〈味道〉。“格局”指布局或眼界，不指气味，说香要用“味道”。"}, {"text": "这套房子的格局很便宜。", "explanation": "这里应该用〈价格〉。“格局”指布局或眼界，不能说“便宜”，说价钱要用“价格”。"}, {"text": "这家餐厅的格局很好吃。", "explanation": "语义：“格局”指布局或眼界，不指味道，说味道应用“好吃”或“味道好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "格局", "is_correct": true, "explanation": "正确：“格局”指眼界或看问题的范围，句中说看问题要有大的格局。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是空间，不能说看问题要有大房间。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“大”形容规模，不能与“价格”组成“大价格”这样的搭配。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“大眼睛”描述外貌，与“看问题”的语境不合。"}], "explanations": {"格局": "正确：“格局”指眼界或看问题的范围，句中说看问题要有大的格局。", "房间": "语义：“房间”是空间，不能说看问题要有大房间。", "价格": "搭配：“大”形容规模，不能与“价格”组成“大价格”这样的搭配。", "眼睛": "体貌：“大眼睛”描述外貌，与“看问题”的语境不合。"}, "sentence_index": 6, "correct_answer": "格局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的格局很开朗，大家都喜欢他。", "explanation": "这里应该用〈性格〉。“格局”指布局或眼界，描述性情要用“性格”。"}, {"text": "电话里的格局变小了。", "explanation": "这里应该用〈声音〉。“电话里”的变化是声音，“格局”指布局或眼界，不能用于声音的大小。"}, {"text": "他的格局每月涨了两百。", "explanation": "这里应该用〈工资〉。“格局”指布局或眼界，不是钱数，不能说“涨了两百”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套公寓有一条很好的格局。", "corrected_sentence": "这套公寓有一个很好的格局。", "error_description": "错误形式：“一条很好的格局”。正确形式：“一个很好的格局”。“条”用于细长的物件，“格局”的量词应为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一根大格局。", "corrected_sentence": "他有一个大格局。", "error_description": "错误形式：“一根大格局”。正确形式：“一个大格局”。“根”用于细长的物件，“格局”的量词应为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
