INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "非常好的东西。", "primary_collocate": null, "pronunciation": "jīng pǐn", "ipa": "tɕiŋ˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些水果都是精品，又大又甜。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们店里的衣服都是精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件精品只有一件，别人买不到。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送给我一件手工精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好东西才叫精品，普通的不算。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具做得很好，是精品中的精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说今天来的货都是精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家茶店的茶叶是精品，价格也不便宜。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直在找一件真正的精品。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批苹果是精品，要卖得贵一点。", "target_word": "精品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件精品", "label": "量词"}, {"form": "精品店", "label": "复合"}], "register": "通用", "sense_fingerprint": "非常好的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef83f8ea-da59-4442-8f09-9de465290990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精品", "is_correct": true, "explanation": "符合语境：“又大又甜”的水果属于非常好的东西。"}, {"text": "次货", "is_correct": false, "explanation": "语义：“又大又甜”是正面评价，不能说是次货。"}, {"text": "烂货", "is_correct": false, "explanation": "语域：“烂货”是口语且带贬义，与这里的正面描述不合。"}, {"text": "残次品", "is_correct": false, "explanation": "语义：“残次品”有残缺或次等的意思，与“又大又甜”矛盾。"}], "explanations": {"精品": "符合语境：“又大又甜”的水果属于非常好的东西。", "次货": "语义：“又大又甜”是正面评价，不能说是次货。", "烂货": "语域：“烂货”是口语且带贬义，与这里的正面描述不合。", "残次品": "语义：“残次品”有残缺或次等的意思，与“又大又甜”矛盾。"}, "sentence_index": 0, "correct_answer": "精品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货都是精品，质量很差，没人要。", "explanation": "这里应该用〈次品〉。精品指非常好的东西，与“质量很差”矛盾。"}, {"text": "他的手机摔坏了，只好当精品扔掉。", "explanation": "这里应该用〈废品〉。精品指非常好的东西，坏了要扔掉的东西是废品。"}, {"text": "这箱精品全是烂的，没法卖。", "explanation": "这里应该用〈烂货〉。精品指非常好的东西，全烂了的货不能说成精品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00522497-0e7b-4f03-9d0e-8c42e4f1305c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精品", "is_correct": true, "explanation": "符合语境：“老板说”是夸赞货品，“精品”与之一致。"}, {"text": "次品", "is_correct": false, "explanation": "语义：“老板说”带有夸赞语气，“次品”与之矛盾。"}, {"text": "假货", "is_correct": false, "explanation": "语义：假货不是老板会拿来夸赞的货品。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：“垃圾”是口语且带贬义，不适合商家介绍货品。"}], "explanations": {"精品": "符合语境：“老板说”是夸赞货品，“精品”与之一致。", "次品": "语义：“老板说”带有夸赞语气，“次品”与之矛盾。", "假货": "语义：假货不是老板会拿来夸赞的货品。", "垃圾": "语域：“垃圾”是口语且带贬义，不适合商家介绍货品。"}, "sentence_index": 6, "correct_answer": "精品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批苹果是精品，要扔掉。", "explanation": "这里应该用〈残次品〉。精品指非常好的东西，要扔掉的苹果应说“残次品”。"}, {"text": "这堆精品全是废铁，可以卖给收购站。", "explanation": "这里应该用〈废料〉。精品指非常好的东西，废铁不能说成精品。"}, {"text": "这块石头是精品，比废纸还不值钱。", "explanation": "这里应该用〈普通石头〉。精品指非常好的东西，不值钱的石头不能说成精品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00522497-0e7b-4f03-9d0e-8c42e4f1305c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买到一只精品。", "corrected_sentence": "我昨天买到一件精品。", "error_description": "错误形式：“一只精品”；正确形式：“一件精品”。精品是物品，用量词“件”，“只”用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00522497-0e7b-4f03-9d0e-8c42e4f1305c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天进了两精品，都卖掉了。", "corrected_sentence": "我们昨天进了两件精品，都卖掉了。", "error_description": "错误形式：“两精品”，数词后缺少量词；正确形式：“两件精品”。精品是物品，用量词“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00522497-0e7b-4f03-9d0e-8c42e4f1305c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
