INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21660, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一家人从老到小的名单。", "primary_collocate": null, "pronunciation": "pǔ xì", "ipa": "pʰu²¹⁴ ɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "爷爷把我们家的谱系写在本子上。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谱系上，爷爷排在第一个，我排在最后。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，大家一起看家里的谱系。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，谱系里有我们的名字。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在谱系上找到了曾祖父的名字。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份谱系从老到小，一共写了五代人。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸请人把家里的谱系抄了一遍。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的谱系放在爷爷的柜子里。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谱系上有一百多个名字，我看不完。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔想在谱系上加上新出生的孩子。", "target_word": "谱系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "譜系", "label": "繁体"}, {"form": "谱系图", "label": "复合"}], "register": "书面", "sense_fingerprint": "谱系：记录一家人从老到小的名单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0791d15f-9964-414f-b98b-e2f51390c435') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谱系", "is_correct": true, "explanation": "正确：谱系是一家人从老到小的名单，可以写在本子上。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开锁的工具，不能被“写在本子上”，句子意思不通。"}, {"text": "外卖", "is_correct": false, "explanation": "语义：“外卖”指订购的饭菜，不是可以写在本子上的东西，搭配不通。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“脚印”是踩出的痕迹，不能说“写在本子上”。"}], "explanations": {"谱系": "正确：谱系是一家人从老到小的名单，可以写在本子上。", "钥匙": "语义：“钥匙”是开锁的工具，不能被“写在本子上”，句子意思不通。", "外卖": "语义：“外卖”指订购的饭菜，不是可以写在本子上的东西，搭配不通。", "脚印": "搭配：“脚印”是踩出的痕迹，不能说“写在本子上”。"}, "sentence_index": 0, "correct_answer": "谱系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份谱系上有我们班的名字。", "explanation": "这里应该用〈名册〉。名册用于班级、比赛等的成员名单；谱系专指一家人从老到小的名单，不用于班级。"}, {"text": "老师的谱系贴在门口。", "explanation": "这里应该用〈座位表〉。谱系专指一家人从老到小的名单，不用来指教室里的座位安排；“座位表”才是座位的列表。"}, {"text": "教室的讲台上放着一个谱系。", "explanation": "这里应该用〈闹钟〉。谱系专指一家人从老到小的名单，不是用来计时的物件；讲台上放的闹钟要用“闹钟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谱系", "is_correct": true, "explanation": "正确：谱系是一家人的名单，可以抄写，符合“请人抄了一遍”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象状况，不能被“抄了一遍”，句子不通。"}, {"text": "日出", "is_correct": false, "explanation": "语义：“日出”指太阳升起的时刻，不能被抄写，搭配不通。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“歌声”是声音，不能与“抄了一遍”搭配。"}], "explanations": {"谱系": "正确：谱系是一家人的名单，可以抄写，符合“请人抄了一遍”的语境。", "天气": "语义：“天气”是气象状况，不能被“抄了一遍”，句子不通。", "日出": "语义：“日出”指太阳升起的时刻，不能被抄写，搭配不通。", "歌声": "搭配：“歌声”是声音，不能与“抄了一遍”搭配。"}, "sentence_index": 6, "correct_answer": "谱系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出版社想在谱系上加上新章节。", "explanation": "这里应该用〈目录〉。目录指书的章节列表；谱系专指一家人的名单，不用来指书的章节。"}, {"text": "这辆车的谱系很高。", "explanation": "这里应该用〈价格〉。谱系专指一家人从老到小的名单，不指车的价格；说价格高要用“价格”。"}, {"text": "叔叔买了一个谱系，想踢着玩。", "explanation": "这里应该用〈足球〉。谱系专指一家人从老到小的名单，不能拿来踢；“踢”的对象要用“足球”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家有一块谱系，记着几代人的名字。", "corrected_sentence": "我们家有一本谱系，记着几代人的名字。", "error_description": "“一块谱系”应改为“一本谱系”。这里的谱系是记录名单的册子，计量用“本”；“块”用于块状的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块谱系里记着一家人从老到小的名字。", "corrected_sentence": "这本谱系里记着一家人从老到小的名字。", "error_description": "“这块谱系”应改为“这本谱系”。这里的谱系是记录名单的册子，计量用“本”；“块”用于块状的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
