INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21664, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做事情，看看事情会变成什么样子。", "primary_collocate": null, "pronunciation": "shí jiàn", "ipa": "ʂɻ̩˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个办法好不好，实践过才知道。", "target_word": "实践", "complexity_tier": "T3", "furigana": "zhè gè bàn fǎ hǎo bù hǎo, shí jiàn guò cái zhī dào", "sentence_source": "generated"}, {"text": "你想学游泳，光看书是不够的，要亲身实践。", "target_word": "实践", "complexity_tier": "T3", "furigana": "nǐ xiǎng xué yóu yǒng, guāng kàn shū shì bú gòu de, yào qīn shēn shí jiàn", "sentence_source": "generated"}, {"text": "他把新想法拿到工作中去实践。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说得再好也没用，还是得亲自去实践。", "target_word": "实践", "complexity_tier": "T3", "furigana": "shuō de zài hǎo yě méi yòng, hái shì děi qīn zì qù shí jiàn", "sentence_source": "generated"}, {"text": "老师让我们实践这种新的学习方法。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划不错，我想马上实践。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法我们已经实践了一个月，效果还不错。", "target_word": "实践", "complexity_tier": "T3", "furigana": "zhè gè bàn fǎ wǒ men yǐ jīng shí jiàn le yí gè yuè, xiào guǒ hái bú cuò", "sentence_source": "generated"}, {"text": "他不怕失败，愿意实践各种新办法。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做行不行，只有实践才知道。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算在家里实践学到的做菜方法。", "target_word": "实践", "complexity_tier": "T3", "furigana": "tā dǎ suan zài jiā lǐ shí jiàn xué dào de zuò cài fāng fǎ", "sentence_source": "generated"}], "morphological_forms": [{"form": "实践了", "label": "体标：了"}, {"form": "实践过", "label": "体标：过"}, {"form": "实践着", "label": "体标：着"}, {"form": "實踐", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词，亲自去做，试试看结果如何", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1a16da-10f9-4386-9fa4-b1d4f0773c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确答案。实践（shí jiàn）作动词时指亲自去做，试试看结果如何。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”（shí jiān）与“实践”（shí jiàn）只有第二个音节声调不同（jiān 第一声，jiàn 第四声），意思是时间。"}, {"text": "事件", "is_correct": false, "explanation": "“事件”（shì jiàn）与“实践”（shí jiàn）只有第一个音节声调不同（shì 第四声，shí 第二声），意思是事件。"}, {"text": "实现", "is_correct": false, "explanation": "“实现”（shí xiàn）与“实践”（shí jiàn）只有第二个音节声母不同（x 与 j），意思是变成现实。"}, {"text": "石匠", "is_correct": false, "explanation": "“石匠”（shí jiàng）与“实践”（shí jiàn）只有第二个音节韵尾不同（-ng 与 -n），意思是石匠。"}], "explanations": {"实践": "正确答案。实践（shí jiàn）作动词时指亲自去做，试试看结果如何。", "时间": "“时间”（shí jiān）与“实践”（shí jiàn）只有第二个音节声调不同（jiān 第一声，jiàn 第四声），意思是时间。", "事件": "“事件”（shì jiàn）与“实践”（shí jiàn）只有第一个音节声调不同（shì 第四声，shí 第二声），意思是事件。", "实现": "“实现”（shí xiàn）与“实践”（shí jiàn）只有第二个音节声母不同（x 与 j），意思是变成现实。", "石匠": "“石匠”（shí jiàng）与“实践”（shí jiàn）只有第二个音节韵尾不同（-ng 与 -n），意思是石匠。"}, "sentence_index": null, "correct_answer": "实践"}, "level_3": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确。“实践过才知道”是常见说法，指亲自试过才能知道结果。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃过才知道”多用于食物，“办法”不能被吃，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与检验办法好不好无关。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能用来检验办法，句子结构也不成立。"}], "explanations": {"实践": "正确。“实践过才知道”是常见说法，指亲自试过才能知道结果。", "吃": "语义：“吃过才知道”多用于食物，“办法”不能被吃，句子不通。", "唱": "语义：“唱”指发声演唱，与检验办法好不好无关。", "哭": "配价：“哭”是不及物动词，不能用来检验办法，句子结构也不成立。"}, "sentence_index": 0, "correct_answer": "实践"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都实践游泳。", "explanation": "这里应该用〈练习〉。“实践”指把想法、办法付诸行动；游泳这类技能要靠“练习”。"}, {"text": "他每天都要实践生词，把它们抄三遍。", "explanation": "这里应该用〈抄写〉。“实践”是做事情、看看结果会怎样，不能用来指把生词照着写下来；抄写生词要用“抄写”。"}, {"text": "教练要求他每天实践跑步。", "explanation": "这里应该用〈训练〉。“实践”针对想法、办法付诸行动；跑步这类体育活动要用“训练”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确。“已经实践了一个月”指把办法亲自试行了一段时间，与“效果还不错”相接。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”用于衣物，“办法”不能被穿，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指休息，与试行办法、观察效果的意思不符。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，不能带“办法”作宾语，句子不成立。"}], "explanations": {"实践": "正确。“已经实践了一个月”指把办法亲自试行了一段时间，与“效果还不错”相接。", "穿": "语义：“穿”用于衣物，“办法”不能被穿，句子不通。", "睡": "语义：“睡”指休息，与试行办法、观察效果的意思不符。", "游": "配价：“游”是不及物动词，不能带“办法”作宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "实践"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上都要实践功课。", "explanation": "这里应该用〈复习〉。“实践”指把想法、办法付诸行动，功课要靠“复习”。"}, {"text": "他把这篇文章实践成了英文。", "explanation": "这里应该用〈翻译〉。“实践”是做事情、看看结果会怎样，不能把文章换成另一种语言；把文章译成英文要用“翻译”。"}, {"text": "他每天早上都实践诗歌，练发音。", "explanation": "这里应该用〈朗读〉。“实践”指把想法付诸行动，朗读诗歌要用“朗读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们实践了一下这个办法半年，才决定推广。", "corrected_sentence": "他们实践了这个办法半年，才决定推广。", "error_description": "“一下”表示时间短暂，不能与“半年”这样的长时段搭配；应去掉“一下”，说“实践了这个办法半年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们曾经实践着这个办法，效果不错。", "corrected_sentence": "他们曾经实践过这个办法，效果不错。", "error_description": "“过”表示经历过，与“曾经”搭配。“着”表示动作正在进行，与“曾经”矛盾，应说“实践过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
