INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更好、更厉害。", "primary_collocate": null, "pronunciation": "shēng jí", "ipa": "ʂɤŋ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我想把旧电脑升级一下。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸请人升级了家里的网络。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司打算升级这套旧系统。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师想升级教室里的设备。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅升级了菜单和服务。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每个月都花钱升级手机里的软件。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂买了新机器，升级了生产线。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们升级了酒店的房间，住着更舒服。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先升级你的手机，再下载这个软件。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校升级了图书馆的电脑。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升级了", "label": "体标（了）"}, {"form": "升级过", "label": "体标（过）"}, {"form": "升级版", "label": "复合"}, {"form": "升級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人使某物变得更好（及物）：升级电脑、升级系统、升级设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a021c322-13ee-45fe-9ef2-128980e8eb6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。升级：让东西变得更好、更厉害。"}, {"text": "生计", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，生计指谋生的办法。"}, {"text": "省级", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，省级指省一级的层次。"}, {"text": "生机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，生机指生命力。"}], "explanations": {"升级": "正确答案。升级：让东西变得更好、更厉害。", "生计": "jì（第四声）与 jí（第二声）声调不同，生计指谋生的办法。", "省级": "shěng（第三声）与 shēng（第一声）声调不同，省级指省一级的层次。", "生机": "jī（第一声）与 jí（第二声）声调不同，生机指生命力。"}, "sentence_index": null, "correct_answer": "升级"}, "level_3": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。“把旧电脑升级一下”表示让旧电脑变得更好。"}, {"text": "唱", "is_correct": false, "explanation": "语义：电脑不能“唱”，句意不通。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”的对象是植物或土地，不能说“浇电脑”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”只用于人或动物，电脑不能“吃”。"}], "explanations": {"升级": "正确答案。“把旧电脑升级一下”表示让旧电脑变得更好。", "唱": "语义：电脑不能“唱”，句意不通。", "浇": "搭配：“浇”的对象是植物或土地，不能说“浇电脑”。", "吃": "语义：“吃”只用于人或动物，电脑不能“吃”。"}, "sentence_index": 0, "correct_answer": "升级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生升级了很多病人。", "explanation": "这里应该用〈治疗〉。升级用于使器物、系统等变得更好，治疗病人要用治疗。"}, {"text": "工厂升级了产量。", "explanation": "这里应该用〈增加〉。升级指使器物或系统变得更好，数量增长要用增加。"}, {"text": "公司升级了他。", "explanation": "这里应该用〈提拔〉。升级用于使物品或系统变得更好，提拔人员要用提拔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。升级：让东西变得更好、更厉害。"}, {"text": "盛极", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，盛极指发展到顶点。"}, {"text": "生肌", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，生肌指促进新组织长出。"}, {"text": "省际", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，省际指各省之间。"}], "explanations": {"升级": "正确答案。升级：让东西变得更好、更厉害。", "盛极": "shèng（第四声）与 shēng（第一声）声调不同，盛极指发展到顶点。", "生肌": "jī（第一声）与 jí（第二声）声调不同，生肌指促进新组织长出。", "省际": "shěng（第三声）与 shēng（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，省际指各省之间。"}, "sentence_index": null, "correct_answer": "升级"}, "level_3": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。“工厂买了新机器，升级了生产线”表示让生产线变得更好。"}, {"text": "骑", "is_correct": false, "explanation": "语义：“骑”不能用于生产线，句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：生产线不能“喝”，句子说不通。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”用于动植物，不能说“养生产线”。"}], "explanations": {"升级": "正确答案。“工厂买了新机器，升级了生产线”表示让生产线变得更好。", "骑": "语义：“骑”不能用于生产线，句意不通。", "喝": "语义：生产线不能“喝”，句子说不通。", "养": "搭配：“养”用于动植物，不能说“养生产线”。"}, "sentence_index": 6, "correct_answer": "升级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "志愿者升级了贫困学生。", "explanation": "这里应该用〈帮助〉。升级用于使物品或系统变得更好，帮助人要用帮助。"}, {"text": "学校升级了浪费。", "explanation": "这里应该用〈减少〉。升级指使器物或系统变得更好，数量或浪费的下降要用减少。"}, {"text": "同学们升级了邮票。", "explanation": "这里应该用〈收集〉。升级指使物品变得更好，收集物品要用收集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把旧手机的升级一下。", "corrected_sentence": "我想把旧手机升级一下。", "error_description": "多加“的”：“升级”是动词，不能被“的”修饰，写成“的升级”变成名词短语，与后面的“一下”不搭配。正确形式为“把旧手机升级一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把图书馆的电脑升级。", "corrected_sentence": "学校把图书馆的电脑升级了。", "error_description": "“把”字句缺少成分：“把”字句中动词后要带“了”或其他成分，写成“把图书馆的电脑升级”语气未完。正确形式为“学校把图书馆的电脑升级了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21668, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正向", "is_correct": true, "explanation": "正确：“正向”与“反向”构成反义，指与反向相对的那个方向。"}, {"text": "北方", "is_correct": false, "explanation": "“北方”是方位名词，与“反向”不构成反义。"}, {"text": "边界", "is_correct": false, "explanation": "“边界”指界限，与方向相反无关，不构成反义。"}, {"text": "路径", "is_correct": false, "explanation": "“路径”指行进的路线，与方向相反无关，不构成反义。"}], "correct_answer": "正向", "explanations": {"正向": "正确：“正向”与“反向”构成反义，指与反向相对的那个方向。", "北方": "“北方”是方位名词，与“反向”不构成反义。", "边界": "“边界”指界限，与方向相反无关，不构成反义。", "路径": "“路径”指行进的路线，与方向相反无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21668, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正向", "is_correct": true, "explanation": "正确：“正向”与“反向”构成反义，指与反向相对的那个方向。"}, {"text": "南方", "is_correct": false, "explanation": "“南方”是方位名词，与“反向”不构成反义。"}, {"text": "出口", "is_correct": false, "explanation": "“出口”指通出去的地方，与方向相反无关，不构成反义。"}, {"text": "轨迹", "is_correct": false, "explanation": "“轨迹”指物体运动留下的路线，与方向相反无关，不构成反义。"}], "correct_answer": "正向", "explanations": {"正向": "正确：“正向”与“反向”构成反义，指与反向相对的那个方向。", "南方": "“南方”是方位名词，与“反向”不构成反义。", "出口": "“出口”指通出去的地方，与方向相反无关，不构成反义。", "轨迹": "“轨迹”指物体运动留下的路线，与方向相反无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "和平时相反的方向。", "primary_collocate": null, "pronunciation": "fǎn xiàng", "ipa": "fan˨˩ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我坐反了车，现在要往反向走。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开到一半，他突然朝反向开去。", "target_word": "反向", "complexity_tier": "T3", "furigana": "fǎn xiàng", "sentence_source": "generated"}, {"text": "风向变了，帆要转到反向。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到叫声，他朝反向跑了。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁有正向和反向两个方向。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路口太多，我拐错了弯，走向了反向。", "target_word": "反向", "complexity_tier": "T3", "furigana": "fǎn xiàng", "sentence_source": "generated"}, {"text": "他往东，我往反向，我们分开了。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风车朝反向转了起来。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们向反向走五步。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平时右转，今天他选了反向。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "与平时相反的那个方向（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b8a7d8d-7ee2-4ed2-a67d-1e712f561b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21668, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：反向（fǎn xiàng）名词，意思是和平时相反的方向。"}, {"text": "返乡", "is_correct": false, "explanation": "声调不同：第一音节都是 fǎn，第二音节 xiāng（第一声）与 xiàng（第四声）声调不同，返乡意思是回到家乡。"}, {"text": "反响", "is_correct": false, "explanation": "声调不同：第二音节 xiǎng（第三声）与 xiàng（第四声）声调不同，反响意思是回声或反应。"}, {"text": "饭香", "is_correct": false, "explanation": "声调不同：fàn（第四声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，饭香意思是饭的香气。"}, {"text": "翻箱", "is_correct": false, "explanation": "声调不同：fān（第一声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，翻箱意思是翻找箱子。"}], "explanations": {"反向": "正确：反向（fǎn xiàng）名词，意思是和平时相反的方向。", "返乡": "声调不同：第一音节都是 fǎn，第二音节 xiāng（第一声）与 xiàng（第四声）声调不同，返乡意思是回到家乡。", "反响": "声调不同：第二音节 xiǎng（第三声）与 xiàng（第四声）声调不同，反响意思是回声或反应。", "饭香": "声调不同：fàn（第四声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，饭香意思是饭的香气。", "翻箱": "声调不同：fān（第一声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，翻箱意思是翻找箱子。"}, "sentence_index": null, "correct_answer": "反向"}, "level_3": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：“往反向走”指朝与坐反的车相反的方向走，符合“坐反了车”的语境。"}, {"text": "高处", "is_correct": false, "explanation": "语义：“高处”指位置较高的地方，与坐反了车后的行进方向无关。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以前往的方向或地点，“往声音走”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是地点或方向，“往颜色走”句意不通。"}], "explanations": {"反向": "正确：“往反向走”指朝与坐反的车相反的方向走，符合“坐反了车”的语境。", "高处": "语义：“高处”指位置较高的地方，与坐反了车后的行进方向无关。", "声音": "语义：“声音”不是可以前往的方向或地点，“往声音走”句意不通。", "颜色": "语义：“颜色”不是地点或方向，“往颜色走”句意不通。"}, "sentence_index": 0, "correct_answer": "反向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这枚硬币的反向印着花纹。", "explanation": "这里应该用〈反面〉。“反向”指运动或方向相反的那一边，硬币的另一面要用“反面”。"}, {"text": "我们俩朝反向一起走了一段路。", "explanation": "这里应该用〈同一个方向〉。“反向”指相反的方向，两人同行要说“同一个方向”。"}, {"text": "他说话的反向很有道理。", "explanation": "这里应该用〈意思〉。“反向”指和平时相反的方向，说话的内容或道理要说“意思”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：“我往反向”指朝与“他往东”相反的方向走，所以两人分开了。"}, {"text": "东", "is_correct": false, "explanation": "语义：“东”与前文“他往东”方向相同，两人朝同一方向就不会分开。"}, {"text": "原地", "is_correct": false, "explanation": "语义：“原地”指不移动，与“往某个方向走”的动作不符。"}, {"text": "同路", "is_correct": false, "explanation": "搭配：“同路”表示同行，不能用来表示“往”的方向。"}], "explanations": {"反向": "正确：“我往反向”指朝与“他往东”相反的方向走，所以两人分开了。", "东": "语义：“东”与前文“他往东”方向相同，两人朝同一方向就不会分开。", "原地": "语义：“原地”指不移动，与“往某个方向走”的动作不符。", "同路": "搭配：“同路”表示同行，不能用来表示“往”的方向。"}, "sentence_index": 6, "correct_answer": "反向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在操场上画了一个反向。", "explanation": "这里应该用〈圆圈〉。“反向”指和平时相反的方向，是方位概念，不能用来指图形。"}, {"text": "我们的态度完全反向。", "explanation": "这里应该用〈相反〉。“反向”指方向或顺序的反转，态度上的对立要说“相反”。"}, {"text": "这张纸的反向写着名字。", "explanation": "这里应该用〈背面〉。“反向”指方向或运动相反，纸张的另一面要说“背面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机发现开错了方向，就掉头往反向的开。", "corrected_sentence": "司机发现开错了方向，就掉头往反向开。", "error_description": "错误：“往反向的开”。“反向”是名词，后面不能加“的”再接动词。正确为“往反向开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他往一只反向跑了一段路。", "corrected_sentence": "他往反向跑了一段路。", "error_description": "错误：“一只反向”。“只”是动物的量词，不能用于“反向”，此处直接说“往反向跑”。正确为“他往反向跑了一段路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83ad14e1-7dc6-4853-8bfb-6baa69ed0115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
