INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21676, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西按大小或好坏分成不同的等级。", "primary_collocate": null, "pronunciation": "fēn jí", "ipa": "fən˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "农民把苹果按大小分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋要先分级，再装进盒子。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在给茶叶分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些大米已经分级了。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果分级后，价钱不一样。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆按好坏分级，卖得更贵。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把牛肉按质量分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橘子太多了，先分级再卖。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店请人给土豆分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都用机器给鱼分级。", "target_word": "分级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分级了", "label": "体标"}, {"form": "分级管理", "label": "复合"}], "register": "中性", "sense_fingerprint": "把具体的东西按大小或好坏分成等级；水果、鸡蛋、茶叶等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a021c322-13ee-45fe-9ef2-128980e8eb6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21676, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分级", "is_correct": true, "explanation": "正确答案。分级：把东西按大小或好坏分成不同的等级。"}, {"text": "分歧", "is_correct": false, "explanation": "qí 与 jí 声母不同（q 与 j），声调相同，分歧指意见不一致。"}, {"text": "愤激", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，jī（第一声）与 jí（第二声）声调也不同，愤激指激动愤怒。"}, {"text": "分机", "is_correct": false, "explanation": "fēn 相同，jī（第一声）与 jí（第二声）声调不同，分机指电话总机之外的分支电话。"}, {"text": "粉剂", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，粉剂指粉末状的药剂。"}], "explanations": {"分级": "正确答案。分级：把东西按大小或好坏分成不同的等级。", "分歧": "qí 与 jí 声母不同（q 与 j），声调相同，分歧指意见不一致。", "愤激": "fèn（第四声）与 fēn（第一声）声调不同，jī（第一声）与 jí（第二声）声调也不同，愤激指激动愤怒。", "分机": "fēn 相同，jī（第一声）与 jí（第二声）声调不同，分机指电话总机之外的分支电话。", "粉剂": "fěn（第三声）与 fēn（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，粉剂指粉末状的药剂。"}, "sentence_index": null, "correct_answer": "分级"}, "level_3": {"options": [{"text": "分级", "is_correct": true, "explanation": "正确答案。“按大小分级”指按大小把苹果分成不同等级。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能用于按大小区分苹果，句意不通。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”不能与“苹果”搭配，也不能用于按大小处理水果。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指加热或焚烧，与按大小划分苹果的意思无关。"}], "explanations": {"分级": "正确答案。“按大小分级”指按大小把苹果分成不同等级。", "唱": "语义：“唱”不能用于按大小区分苹果，句意不通。", "骑": "搭配：“骑”不能与“苹果”搭配，也不能用于按大小处理水果。", "烧": "语义：“烧”指加热或焚烧，与按大小划分苹果的意思无关。"}, "sentence_index": 0, "correct_answer": "分级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "邮递员按地址分级信件。", "explanation": "这里应该用〈分拣〉。分级指按标准划分等级，按地址挑出信件要用分拣。"}, {"text": "工厂把药片分级到瓶子里。", "explanation": "这里应该用〈分装〉。分级指按等级划分，把东西装进容器要用分装。"}, {"text": "把书架分级一下。", "explanation": "这里应该用〈整理〉。分级指按标准划分等级，收拾书架要用整理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21676, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分级", "is_correct": true, "explanation": "正确答案。分级：把东西按大小或好坏分成不同的等级。"}, {"text": "分局", "is_correct": false, "explanation": "jú（第二声）与 jí（第二声）韵母不同（ü 与 i），声调相同，分局指机构下属的分支机构。"}, {"text": "分际", "is_correct": false, "explanation": "fēn 相同，jì（第四声）与 jí（第二声）声调不同，分际指界限、本分。"}, {"text": "忿疾", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，jí 相同，忿疾指愤恨痛恨。"}, {"text": "奋击", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）、jī（第一声）与 jí（第二声）声调均不同，奋击指奋勇攻击。"}], "explanations": {"分级": "正确答案。分级：把东西按大小或好坏分成不同的等级。", "分局": "jú（第二声）与 jí（第二声）韵母不同（ü 与 i），声调相同，分局指机构下属的分支机构。", "分际": "fēn 相同，jì（第四声）与 jí（第二声）声调不同，分际指界限、本分。", "忿疾": "fèn（第四声）与 fēn（第一声）声调不同，jí 相同，忿疾指愤恨痛恨。", "奋击": "fèn（第四声）与 fēn（第一声）、jī（第一声）与 jí（第二声）声调均不同，奋击指奋勇攻击。"}, "sentence_index": null, "correct_answer": "分级"}, "level_3": {"options": [{"text": "分级", "is_correct": true, "explanation": "正确答案。“按质量分级”指按质量把牛肉分成不同等级。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”不能用于按质量区分牛肉，句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”与按质量处理牛肉的意思无关，句子说不通。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”用于动植物，不能说“养牛肉”。"}], "explanations": {"分级": "正确答案。“按质量分级”指按质量把牛肉分成不同等级。", "跳": "语义：“跳”不能用于按质量区分牛肉，句意不通。", "喝": "语义：“喝”与按质量处理牛肉的意思无关，句子说不通。", "养": "搭配：“养”用于动植物，不能说“养牛肉”。"}, "sentence_index": 6, "correct_answer": "分级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师把鱼分级成小块。", "explanation": "这里应该用〈分割〉。分级指按标准分成等级，把整体切成小块要用分割。"}, {"text": "他每天用水分级鱼。", "explanation": "这里应该用〈清洗〉。分级是划分等级，把鱼洗干净要用清洗。"}, {"text": "妈妈把鱼刺分级出来了。", "explanation": "这里应该用〈挑〉。分级指按标准划分等级，把鱼刺挑出来要用挑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民已经把苹果按大小的分级了。", "corrected_sentence": "农民已经把苹果按大小分级了。", "error_description": "多加“的”：“按大小”作状语修饰动词“分级”，中间不能加“的”，写成“按大小的分级”变成名词短语，不能再接“了”。正确形式为“按大小分级了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些鲜鱼很分级了。", "corrected_sentence": "这些鲜鱼已经分级了。", "error_description": "程度副词误用：「分级」是动词，不能被「很」修饰。正确说法是「这些鲜鱼已经分级了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
