INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产者是制造东西的人或公司。", "primary_collocate": null, "pronunciation": "shēng chǎn zhě", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这家公司是有名的玩具生产者。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要直接向生产者买东西。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产者把新的电视机送到了店里。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位生产者做的鞋子又好又便宜。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的生产者不会用坏材料。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的生产者在上面写了名字。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店老板想找一位可靠的生产者。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产者每天要做很多面包。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国是世界上最大的茶叶生产者之一。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从生产者那里买了很多布。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "生产者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "生产者：制造东西的人或公司，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90865500-d708-484f-b474-f4f4acd19e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产者", "is_correct": true, "explanation": "“生产者”指制造东西的公司，句中说的是这家公司制造玩具，句意相符。"}, {"text": "消费者", "is_correct": false, "explanation": "语义：“消费者”指购买东西的人，与“制造玩具的公司”不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：公司不能是病人，句意不通。"}, {"text": "翻译员", "is_correct": false, "explanation": "搭配：“翻译员”不能用来指称玩具的制造方，这一搭配不成立。"}], "explanations": {"生产者": "“生产者”指制造东西的公司，句中说的是这家公司制造玩具，句意相符。", "消费者": "语义：“消费者”指购买东西的人，与“制造玩具的公司”不符。", "病人": "语义：公司不能是病人，句意不通。", "翻译员": "搭配：“翻译员”不能用来指称玩具的制造方，这一搭配不成立。"}, "sentence_index": 0, "correct_answer": "生产者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新机器是这家工厂的生产者，每天能做很多双鞋。", "explanation": "这里应该用〈生产设备〉。生产者是制造东西的人或公司，机器应说〈生产设备〉。"}, {"text": "这家商店是这双鞋的生产者，每天都在卖。", "explanation": "这里应该用〈销售者〉。生产者是制造东西的人或公司，只卖东西的商店应说〈销售者〉。"}, {"text": "这个创意是这双鞋的生产者。", "explanation": "这里应该用〈灵感来源〉。生产者是制造东西的人或公司，创意不是制造者，应说〈灵感来源〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产者", "is_correct": true, "explanation": "“生产者”指提供货物的制造方，与小店老板找货源的语境相符。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“可靠”多修饰能提供货物或服务的人，“乘客”与之不搭配。"}, {"text": "学者", "is_correct": false, "explanation": "语义：学者是做研究的人，与小店找货源的语境不符。"}, {"text": "司令", "is_correct": false, "explanation": "语义：司令指军队的指挥员，与小店找货无关。"}], "explanations": {"生产者": "“生产者”指提供货物的制造方，与小店老板找货源的语境相符。", "乘客": "搭配：“可靠”多修饰能提供货物或服务的人，“乘客”与之不搭配。", "学者": "语义：学者是做研究的人，与小店找货源的语境不符。", "司令": "语义：司令指军队的指挥员，与小店找货无关。"}, "sentence_index": 6, "correct_answer": "生产者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家银行是这家布厂的生产者。", "explanation": "这里应该用〈投资者〉。生产者是制造东西的人或公司，银行只出资，不制造布料，应说〈投资者〉。"}, {"text": "他是这些布的生产者，每天从工厂进货再转卖。", "explanation": "这里应该用〈批发商〉。生产者是制造东西的人或公司，从工厂进货再转卖的人应说〈批发商〉。"}, {"text": "这批布是这家工厂的生产者。", "explanation": "这里应该用〈产品〉。生产者是制造东西的人或公司，布是产品，不是制造者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那两只生产者都在城西建了新厂。", "corrected_sentence": "那两家生产者都在城西建了新厂。", "error_description": "“生产者”指公司时量词应用“家”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家纺织厂是本市最大的一只布料生产者。", "corrected_sentence": "这家纺织厂是本市最大的一家布料生产者。", "error_description": "量词错误：“生产者”指公司时应用“家”，“只”不能用于公司，应改为“一家布料生产者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
