INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示比以前更多或更厉害。", "primary_collocate": null, "pronunciation": "yù fā", "ipa": "y˥˩ fa˥", "syllable_count": 2, "sentences": [{"text": "他生病以后，脸色愈发白了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一关，房间里愈发黑了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间越久，我愈发想念朋友。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风越来越大，天气愈发冷了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情变得复杂，他愈发着急。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到这里，老人愈发伤心。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读的书越多，愈发觉得自己知道得少。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山越往上走，空气愈发冷。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸了他，他愈发努力。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，愈发懂事了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示比以前更多或更厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef83f8ea-da59-4442-8f09-9de465290990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愈发", "is_correct": true, "explanation": "正确：愈发表示比以前程度更厉害，与“生病以后”的变化相合。"}, {"text": "不再", "is_correct": false, "explanation": "语义：不再表示不再变化，与“生病以后，脸色愈发白”的加深趋势不符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：从来表示一向如此，与“生病以后”带来的变化不符。"}, {"text": "白白", "is_correct": false, "explanation": "搭配：白白表示徒然，不能修饰“白了”这类状态变化。"}], "explanations": {"愈发": "正确：愈发表示比以前程度更厉害，与“生病以后”的变化相合。", "不再": "语义：不再表示不再变化，与“生病以后，脸色愈发白”的加深趋势不符。", "从来": "语义：从来表示一向如此，与“生病以后”带来的变化不符。", "白白": "搭配：白白表示徒然，不能修饰“白了”这类状态变化。"}, "sentence_index": 0, "correct_answer": "愈发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天愈发买了一本词典。", "explanation": "这里应该用〈终于〉。愈发表示程度逐渐加深，不能修饰一次性的购买动作。"}, {"text": "他愈发是我的弟弟。", "explanation": "这里应该用〈确实〉。愈发表示程度加深，不能修饰判断，强调判断要用确实。"}, {"text": "桌子上愈发放着一本书。", "explanation": "这里应该用〈仍〉。愈发表示程度加深，不表示状态持续，表示状态一直保持要用仍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00522497-0e7b-4f03-9d0e-8c42e4f1305c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愈发", "is_correct": true, "explanation": "正确：愈发表示程度加深，与“书越多”的递进关系相合。"}, {"text": "毫不", "is_correct": false, "explanation": "搭配：毫不一般不修饰“觉得”这类心理动词，搭配不自然，且与句意不合。"}, {"text": "从不", "is_correct": false, "explanation": "语义：从不与“书越多”的递进关系相反，不合句意。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「越…，…」递进句式不用「非常」，且「非常觉得」不自然。"}], "explanations": {"愈发": "正确：愈发表示程度加深，与“书越多”的递进关系相合。", "毫不": "搭配：毫不一般不修饰“觉得”这类心理动词，搭配不自然，且与句意不合。", "从不": "语义：从不与“书越多”的递进关系相反，不合句意。", "非常": "搭配：「越…，…」递进句式不用「非常」，且「非常觉得」不自然。"}, "sentence_index": 6, "correct_answer": "愈发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色愈发一直没变。", "explanation": "这里应该用〈始终〉。愈发表示程度逐步加深，与“没变”的含义相矛盾，表示一直不变要用始终。"}, {"text": "妈妈把书愈发收好了。", "explanation": "这里应该用〈全部〉。愈发表示程度逐步加深，不能用于表示全部完成的把字句，表示全部完成要用全部。"}, {"text": "孩子刚起床就愈发去玩了。", "explanation": "这里应该用〈马上〉。愈发表示程度逐步加深，不能修饰刚起床就去玩这样的瞬间动作，表示立即行动要用马上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00522497-0e7b-4f03-9d0e-8c42e4f1305c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事越闹越大，妈妈很愈发担心了。", "corrected_sentence": "这件事越闹越大，妈妈愈发担心了。", "error_description": "错误形式：很愈发担心；正确形式：愈发担心。“愈发”已表示程度加深，不能再与“很”并用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00522497-0e7b-4f03-9d0e-8c42e4f1305c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他愈发得喜欢这本书了。", "corrected_sentence": "他愈发喜欢这本书了。", "error_description": "错误形式：愈发得喜欢；正确形式：愈发喜欢。“愈发”是状语，后面不能加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00522497-0e7b-4f03-9d0e-8c42e4f1305c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降低", "is_correct": true, "explanation": "“降低”指使数量或水平变低，与“提高”构成反义，符合“提高工作效率”的对立面。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指使事物维持原样，不与“提高”构成反义。"}, {"text": "努力", "is_correct": false, "explanation": "“努力”指尽力去做某事，与“提高”不是反义关系。"}, {"text": "维持", "is_correct": false, "explanation": "“维持”指保持某种状态不变，与“提高”不构成反义。"}], "correct_answer": "降低", "explanations": {"降低": "“降低”指使数量或水平变低，与“提高”构成反义，符合“提高工作效率”的对立面。", "保持": "“保持”指使事物维持原样，不与“提高”构成反义。", "努力": "“努力”指尽力去做某事，与“提高”不是反义关系。", "维持": "“维持”指保持某种状态不变，与“提高”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降低", "is_correct": true, "explanation": "“降低”指使水平变低，与“提高”构成反义，符合“生活水平提高”的对立面。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做完某件事，与“提高”不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“提高”不是反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交换意见，与“提高”不构成反义。"}], "correct_answer": "降低", "explanations": {"降低": "“降低”指使水平变低，与“提高”构成反义，符合“生活水平提高”的对立面。", "完成": "“完成”指做完某件事，与“提高”不构成反义。", "参加": "“参加”指加入某项活动，与“提高”不是反义关系。", "讨论": "“讨论”指交换意见，与“提高”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事物变得比原来更好。", "primary_collocate": null, "pronunciation": "tí gāo", "ipa": "tʰi˧˥ kau˥", "syllable_count": 2, "sentences": [{"text": "我想提高我的汉语水平。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多练习可以提高口语。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂提高了产品的质量。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个方法能提高工作效率。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师希望大家提高学习成绩。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司提高了工人的工资。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看书能提高写作能力。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了提高速度,他换了新电脑。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直努力提高自己的英语。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些年，这个城市的生活水平提高了很多。", "target_word": "提高", "complexity_tier": "T3", "furigana": "zhèxiē nián, zhège chéngshì de shēnghuó shuǐpíng tígāo le hěn duō.", "sentence_source": "generated"}], "morphological_forms": [{"form": "提高了", "label": "体标"}, {"form": "提高过", "label": "体标"}, {"form": "提高到", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "提高：使水平、质量、能力等变得比原来更高更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675cfc97-fbfc-4651-bf94-1c49f7b53f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“汉语水平”作宾语。"}, {"text": "提高", "is_correct": true, "explanation": "“提高”表示使水平变得更高，与句中“想……汉语水平”的意思相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“水平”搭配，不能说“唱汉语水平”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“汉语水平”无关，句子说不通。"}], "explanations": {"散步": "配价：“散步”是不及物动词，不能带“汉语水平”作宾语。", "提高": "“提高”表示使水平变得更高，与句中“想……汉语水平”的意思相合。", "唱": "搭配：“唱”不与“水平”搭配，不能说“唱汉语水平”。", "吃": "语义：“吃”指进食，与“汉语水平”无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "提高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提高了两个小时才到家。", "explanation": "这里应该用〈花〉。“提高”用于水平、质量，不用于时间的消耗，说花费时间要用“花”。"}, {"text": "他一晚上提高了三本书。", "explanation": "这里应该用〈读〉。“提高”用于水平、质量，不指阅读，读书要用“读”。"}, {"text": "这次改革提高了学校的校长。", "explanation": "这里应该用〈提拔〉。“提高”用于水平、质量等，不用于指人的职务晋升，职务上升应该用“提拔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降低", "is_correct": false, "explanation": "语义：“降低”指使变低，与“看书能……写作能力”的积极作用相反，句子说不通。"}, {"text": "提高", "is_correct": true, "explanation": "“提高”表示使能力变得更强，与“看书能”的积极作用相合，符合句意。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不能与“写作能力”搭配，不能说“打写作能力”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与“写作能力”无关，句子说不通。"}], "explanations": {"降低": "语义：“降低”指使变低，与“看书能……写作能力”的积极作用相反，句子说不通。", "提高": "“提高”表示使能力变得更强，与“看书能”的积极作用相合，符合句意。", "打": "搭配：“打”不能与“写作能力”搭配，不能说“打写作能力”。", "喝": "语义：“喝”指饮用，与“写作能力”无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "提高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天提高两个小时，准备上班。", "explanation": "这里不宜用“提高”。“提高”用于水平、质量，不用来表示时间的长短，应该用〈延长〉。"}, {"text": "妈妈提高了那张桌子。", "explanation": "这里不宜用“提高”。“提高”用于水平、质量等抽象事物，不用来指搬动桌子，应该用〈搬〉。"}, {"text": "我们提高了一个下午的路程。", "explanation": "这里应该用〈走〉。“提高”用于水平、质量，不用于距离，走一段路应该用“走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂把产品的质量提高。", "corrected_sentence": "这家工厂把产品的质量提高了。", "error_description": "错误：“把”字句中动词后缺少“了”，句子不完整。正确形式是“把产品的质量提高了”，动态助词“了”应放在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工资提高在了五千元。", "corrected_sentence": "工资提高到了五千元。", "error_description": "错误：结果补语用错，“提高在”不成立。表示提升到某个数额要用“提高到”，正确形式是“工资提高到了五千元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
