INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买东西的人和卖东西的人商量价格。", "primary_collocate": null, "pronunciation": "yì jià", "ipa": "i˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "我想和老板议价，看能不能便宜点。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买二手车时，你可以和卖家议价。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在市场里议价了很久。", "target_word": "议价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店不能议价，价格都写在牌子上。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈擅长议价，每次都买得便宜。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子前，我们先找中介议价。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客想议价，可是老板不同意。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别急着买，先跟他议价吧。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和摊主议价，最后只花了五十块。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅游时，买纪念品常常要议价。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "议价了", "label": "体标（了）"}, {"form": "议价过", "label": "体标（过）"}, {"form": "議價", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买卖双方商量价格（动词用法）：和老板议价、跟卖家议价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a021c322-13ee-45fe-9ef2-128980e8eb6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议价", "is_correct": true, "explanation": "正确：议价，指买卖双方商量价格。"}, {"text": "衣架", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是衣服架子。"}, {"text": "一家", "is_correct": false, "explanation": "yī 与 yì、jiā 与 jià 声调都不同，意思是一个家庭。"}, {"text": "意见", "is_correct": false, "explanation": "jiàn 与 jià 韵尾不同（多一个 n），意思是看法。"}], "explanations": {"议价": "正确：议价，指买卖双方商量价格。", "衣架": "yī（第一声）与 yì（第四声）声调不同，意思是衣服架子。", "一家": "yī 与 yì、jiā 与 jià 声调都不同，意思是一个家庭。", "意见": "jiàn 与 jià 韵尾不同（多一个 n），意思是看法。"}, "sentence_index": null, "correct_answer": "议价"}, "level_3": {"options": [{"text": "议价", "is_correct": true, "explanation": "“和老板议价”表示与老板商量价格，与“看能不能便宜点”的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：与老板结婚和“看能不能便宜点”毫不相干，句意不通。"}, {"text": "辞职", "is_correct": false, "explanation": "配价：“辞职”不能与“和老板”搭配表示商量价格，后半句语义也不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：和老板散步不能使价格变便宜，句意不通。"}], "explanations": {"议价": "“和老板议价”表示与老板商量价格，与“看能不能便宜点”的语境相符。", "结婚": "语义：与老板结婚和“看能不能便宜点”毫不相干，句意不通。", "辞职": "配价：“辞职”不能与“和老板”搭配表示商量价格，后半句语义也不通。", "散步": "语义：和老板散步不能使价格变便宜，句意不通。"}, "sentence_index": 0, "correct_answer": "议价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商场决定议价促销，全部商品都参加。", "explanation": "这里应该用〈降价〉。商场统一促销应说降价，议价是买卖双方的协商。"}, {"text": "顾客一进店就议价，先参观一下商品。", "explanation": "这里应该用〈参观〉。议价指买卖双方商量价格，进店先看商品应说参观，不能说议价。"}, {"text": "他们在工厂里议价，生产了很多零件。", "explanation": "这里应该用〈生产〉。议价指买卖双方商量价格，制造零件应说生产，不能说议价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议价", "is_correct": true, "explanation": "“顾客想议价，可是老板不同意”中，议价指顾客想与老板商量价格，语境通顺。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“顾客想失眠”不成立，与语境不符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“顾客想出生”不合逻辑，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“想下雨”不能用顾客的意愿来表述，“下雨”不带这种主语。"}], "explanations": {"议价": "“顾客想议价，可是老板不同意”中，议价指顾客想与老板商量价格，语境通顺。", "失眠": "语义：“顾客想失眠”不成立，与语境不符。", "出生": "语义：“顾客想出生”不合逻辑，句意不通。", "下雨": "搭配：“想下雨”不能用顾客的意愿来表述，“下雨”不带这种主语。"}, "sentence_index": 6, "correct_answer": "议价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商品都要议价，合格后才能出售。", "explanation": "这里应该用〈质检〉。议价指买卖双方商量价格，检验商品是否合格应说质检，不能说议价。"}, {"text": "超市天天议价，价格很便宜。", "explanation": "这里应该用〈打折〉。超市统一打折，顾客不需要和店员商量，不能说议价。"}, {"text": "卖家议价一千块，我们还价到八百。", "explanation": "这里应该用〈开价〉。开价是卖家先报出价格，议价是双方商量的过程，不能说“议价一千块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想老板议价，看看能不能给我打个折。", "corrected_sentence": "我想跟老板议价，看看能不能给我打个折。", "error_description": "介词缺失：「议价」要用「跟」引出对方，应说「跟老板议价」，不能直接说「老板议价」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈常常在摊主议价。", "corrected_sentence": "我妈妈常常跟摊主议价。", "error_description": "介词错误：引出议价对象应用「跟」，「在」不能引出议价的对象，正确说法是「跟摊主议价」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30a8b487-80ff-48d8-bf97-dc5cd1d0a93d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
