INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "层级就是东西分成的不同等级，比如大楼的一层一层。", "primary_collocate": null, "pronunciation": "céng jí", "ipa": "tsʰɤŋ˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这座商场的层级很多，我常常迷路。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个蛋糕有三个层级，每层味道不同。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山坡上的梯田层级分明，非常好看。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "停车场分成好几个层级，上面一层是空的。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古塔有七个层级，每一层都比下面小。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在地下停车场的第二个层级找到了车。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花园是按层级设计的，下面是花，上面是树。", "target_word": "层级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼的层级越高，风景越好。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏里的城堡有五个层级。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房的架子分成上下两个层级。", "target_word": "层级", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "层级结构", "label": "复合"}], "register": "中性", "sense_fingerprint": "大楼、蛋糕、塔等实物一层一层叠起来的层次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f95e5d-4e87-424f-8121-0527036d276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "层级", "is_correct": true, "explanation": "层级（céng jí）：东西一层一层分成的不同层次，是正确答案。"}, {"text": "城际", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节声调不同（jì）；意思是城市之间的。"}, {"text": "乘积", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节声调不同（jī）；意思是数学中的乘积。"}, {"text": "能级", "is_correct": false, "explanation": "第一音节 céng 与 néng 声母不同（c 与 n），声调相同；意思是能量的等级，是物理学术语。"}], "explanations": {"层级": "层级（céng jí）：东西一层一层分成的不同层次，是正确答案。", "城际": "第一音节声母 c 与 ch 不同，第二音节声调不同（jì）；意思是城市之间的。", "乘积": "第一音节声母 c 与 ch 不同，第二音节声调不同（jī）；意思是数学中的乘积。", "能级": "第一音节 céng 与 néng 声母不同（c 与 n），声调相同；意思是能量的等级，是物理学术语。"}, "sentence_index": null, "correct_answer": "层级"}, "level_3": {"options": [{"text": "层级", "is_correct": true, "explanation": "正确。“层级很多”指商场一层一层的楼层多，搭配自然。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：商场没有年龄，不能说“年龄很多”。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”用于人，不能用来描述商场的层次。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的情绪特点，商场没有脾气，句子不通。"}], "explanations": {"层级": "正确。“层级很多”指商场一层一层的楼层多，搭配自然。", "年龄": "语义：商场没有年龄，不能说“年龄很多”。", "性格": "搭配：“性格”用于人，不能用来描述商场的层次。", "脾气": "语义：脾气是人的情绪特点，商场没有脾气，句子不通。"}, "sentence_index": 0, "correct_answer": "层级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的层级很快，一小时就到了。", "explanation": "这里应该用〈速度〉。“层级”指东西一层一层分成的等级，不表示快慢，说车的快慢要用“速度”。"}, {"text": "他的层级比我大五岁。", "explanation": "这里应该用〈年龄〉。“层级”不表示人的岁数，说人多大要用“年龄”。"}, {"text": "这件衣服的层级很贵。", "explanation": "这里应该用〈价格〉。“层级”不表示钱的多少，说东西值多少钱要用“价格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21686, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "层级", "is_correct": true, "explanation": "层级（céng jí）：东西一层一层分成的不同层次，是正确答案。"}, {"text": "成绩", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节声调不同（jì）；意思是考试或工作的成绩。"}, {"text": "能级", "is_correct": false, "explanation": "第一音节 céng 与 néng 声母不同（c 与 n），声调相同；意思是能量的等级，是物理学术语。"}, {"text": "乘机", "is_correct": false, "explanation": "第一音节声母 c 与 ch 不同，第二音节声调不同（jī）；意思是趁着机会。"}], "explanations": {"层级": "层级（céng jí）：东西一层一层分成的不同层次，是正确答案。", "成绩": "第一音节声母 c 与 ch 不同，第二音节声调不同（jì）；意思是考试或工作的成绩。", "能级": "第一音节 céng 与 néng 声母不同（c 与 n），声调相同；意思是能量的等级，是物理学术语。", "乘机": "第一音节声母 c 与 ch 不同，第二音节声调不同（jī）；意思是趁着机会。"}, "sentence_index": null, "correct_answer": "层级"}, "level_3": {"options": [{"text": "层级", "is_correct": true, "explanation": "正确。“按层级设计”指按一层一层的高低安排，与下面是花、上面是树的结构相符。"}, {"text": "语法", "is_correct": false, "explanation": "语义：花园不是按语法设计的，“语法”指语言规则，与花园无关。"}, {"text": "音调", "is_correct": false, "explanation": "语义：“音调”指声音的高低，不能用来设计花园。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语说法，不能作为设计依据，与书面描述不合。"}], "explanations": {"层级": "正确。“按层级设计”指按一层一层的高低安排，与下面是花、上面是树的结构相符。", "语法": "语义：花园不是按语法设计的，“语法”指语言规则，与花园无关。", "音调": "语义：“音调”指声音的高低，不能用来设计花园。", "家伙": "语域：“家伙”是口语说法，不能作为设计依据，与书面描述不合。"}, "sentence_index": 6, "correct_answer": "层级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的架子分成上下两条层级。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，不能用来计量层级。"}, {"text": "厨房的架子分成上下两本层级。", "explanation": "这里应该用〈个〉。〈本〉用于书籍，不能用来计量层级。"}, {"text": "厨房的架子分成上下两只层级。", "explanation": "这里应该用〈个〉。〈只〉用于动物或成对物品中的一个，不能用来计量层级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个架子有四条层级，每层都放满了书。", "corrected_sentence": "这个架子有四个层级，每层都放满了书。", "error_description": "“层级”的量词应用“个”，不能用“条”（“条”用于细长的东西）。写作：这个架子有四个层级，每层都放满了书。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个蛋糕的层级们从下往上越来越小。", "corrected_sentence": "这个蛋糕的层级从下往上越来越小。", "error_description": "“层级”是无生命名词，不能加后缀“们”表示复数；“们”只用于指人的名词。写作：这个蛋糕的层级从下往上越来越小。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
