INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21690, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做一件很难的事，试试看能不能做成。", "primary_collocate": null, "pronunciation": "tiǎo zhàn", "ipa": "tʰiɑʊ̯˨˩˦ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "我想挑战一下自己，跑完全程马拉松。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他决定挑战一座很高的雪山。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末，我要挑战三小时不看手机。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她第一次挑战游泳比赛，有点儿紧张。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人七十岁了还想挑战跳伞。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他挑战过一天只吃一顿饭，结果很难受。", "target_word": "挑战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想挑战做一道最难的数学题。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们准备挑战一次沙漠长跑。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了试试自己的极限，他挑战了冰水游泳。", "target_word": "挑战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我敢挑战这道难题，你敢不敢？", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑战了", "label": "完成体"}, {"form": "挑战过", "label": "经历体"}, {"form": "挑战者", "label": "复合"}], "register": "中性", "sense_fingerprint": "尝试去做一件很困难的事，考验自己的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb2f094-77d0-4e9f-8b03-ce3ad85679b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挑战", "is_correct": true, "explanation": "挑战：“想……一下自己”指尝试考验自己，与“跑完全程马拉松”的目标一致。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“跑完全程马拉松”的意图相反，句子前后矛盾。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指修饰外表，与“跑完全程马拉松”无关，句子不通。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”的对象是物品或人，不能用于“自己”，说“挑选自己”不通。"}], "explanations": {"挑战": "挑战：“想……一下自己”指尝试考验自己，与“跑完全程马拉松”的目标一致。", "放弃": "语义：“放弃”与“跑完全程马拉松”的意图相反，句子前后矛盾。", "打扮": "语义：“打扮”指修饰外表，与“跑完全程马拉松”无关，句子不通。", "挑选": "搭配：“挑选”的对象是物品或人，不能用于“自己”，说“挑选自己”不通。"}, "sentence_index": 0, "correct_answer": "挑战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他挑战了一下地板，地板很干净。", "explanation": "这里应该用〈拖〉。拖指用拖把擦地，挑战表示迎难而上、做困难的事，不能用于打扫地面。"}, {"text": "她每天挑战早饭，味道很好。", "explanation": "这里应该用〈准备〉。准备指事先做好要用的东西；挑战表示迎难而上、做困难的事，不能用于日常做早饭。"}, {"text": "她在店里挑战了一件泳衣。", "explanation": "这里应该用〈选择〉。选择指从几种里挑出一种，挑战表示迎难而上，不能用于挑选物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挑战", "is_correct": true, "explanation": "挑战：“想”后接“做一道最难的题”，表示想尝试难题，语义通顺。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”要搭配“这道题”，不能说“完成做一道题”。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出错误，与“想做一道题”的意愿不符，句子不通。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”表示不相信，与“想做一道最难的题”的主动意愿相反。"}], "explanations": {"挑战": "挑战：“想”后接“做一道最难的题”，表示想尝试难题，语义通顺。", "完成": "搭配：“完成”要搭配“这道题”，不能说“完成做一道题”。", "批评": "语义：“批评”指指出错误，与“想做一道题”的意愿不符，句子不通。", "怀疑": "语义：“怀疑”表示不相信，与“想做一道最难的题”的主动意愿相反。"}, "sentence_index": 6, "correct_answer": "挑战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天按时挑战工作，从不迟到。", "explanation": "这里应该用〈完成〉。完成指做完任务，挑战强调去做困难的事，日常工作不能说挑战。"}, {"text": "他挑战了这次邀请，没有去参加。", "explanation": "这里应该用〈拒绝〉。拒绝指不接受，挑战表示迎难而上，不能用于不接受邀请。"}, {"text": "我昨晚挑战了一张新床，睡得很香。", "explanation": "这里应该用〈试〉。试指试用；挑战表示迎难而上、做困难的事，不能用于试用一般的日常用品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我正在挑战了一座高山。", "corrected_sentence": "我正在挑战一座高山。", "error_description": "错误在“了”：“正在”表示动作正在进行，不能与表示完成的“了”同用。应去掉“了”，说“正在挑战一座高山”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她打算挑战一只攀岩。", "corrected_sentence": "她打算挑战一次攀岩。", "error_description": "量词错误：“攀岩”是活动，应用动量词“次”，“只”是动物的量词，不能修饰攀岩。应说“挑战一次攀岩”，不能说“挑战一只攀岩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
