INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能力就是你会做一件事的本事。", "primary_collocate": null, "pronunciation": "néng lì", "ipa": "nɤŋ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "小鸟有飞的能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有能力照顾自己。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有能力帮你这个忙。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人有说话的能力。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长大以后，孩子的能力会越来越强。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做饭的能力让大家都很吃惊。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要相信自己有能力把事情做好。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己的能力，也有做不到的事。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳能力不好的人，请不要下水。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，他的能力比同学们都强。", "target_word": "能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种能力", "label": "量词"}, {"form": "游泳能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "会做某件事的本事，日常用法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f17d8f4-7240-4fff-bcf3-3b883044363e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "能力：会飞的本事，句中指小鸟会飞的本领。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有飞的”后面接“颜色”不成搭配，句子说不通。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：“价钱”指物品的价格，与小鸟会飞无关，句子说不通。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：“脸色”指面部的气色，与小鸟会飞无关，句子说不通。"}], "explanations": {"能力": "能力：会飞的本事，句中指小鸟会飞的本领。", "颜色": "搭配：“有飞的”后面接“颜色”不成搭配，句子说不通。", "价钱": "语义：“价钱”指物品的价格，与小鸟会飞无关，句子说不通。", "脸色": "语义：“脸色”指面部的气色，与小鸟会飞无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个机器人的能力很亮，在夜里特别显眼。", "explanation": "这里应该用〈灯光〉。能力指做事的本领，不能用“亮”形容。"}, {"text": "这个机器人能力充沛，一直在跑。", "explanation": "这里应该用〈精力〉。“充沛”形容精神、劲头，能力不能充沛，应说“精力充沛”。"}, {"text": "这个机器人的能力不支，动作越来越慢。", "explanation": "这里应该用〈体力〉。“不支”形容力气耗尽，能力不能“不支”，应说“体力不支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "能力：做事的本领，句中指把事情做好的本领。"}, {"text": "方言", "is_correct": false, "explanation": "语义：“方言”指地方话，与把事情做好无关，句子说不通。"}, {"text": "语调", "is_correct": false, "explanation": "语义：“语调”指说话的声调，与做事的本领无关，句子说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来把事情做好，句子说不通。"}], "explanations": {"能力": "能力：做事的本领，句中指把事情做好的本领。", "方言": "语义：“方言”指地方话，与把事情做好无关，句子说不通。", "语调": "语义：“语调”指说话的声调，与做事的本领无关，句子说不通。", "身材": "体貌：“身材”指人的体形，不能用来把事情做好，句子说不通。"}, "sentence_index": 6, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师说，他的能力很红，大家都认识他。", "explanation": "这里应该用〈名气〉。能力指做事的本领，不能用“红”形容人的知名度。"}, {"text": "老师说，他的能力很胖，比同学们都重。", "explanation": "这里应该用〈身材〉。能力指做事的本领，不能用“胖”形容体形。"}, {"text": "这座桥的能力很长，要走半个小时才能过去。", "explanation": "这里应该用〈长度〉。能力指做事的本领，不能用来形容桥的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子有一只很强的游泳能力。", "corrected_sentence": "这个孩子有一种很强的游泳能力。", "error_description": "错误形式：“一只很强的游泳能力”；正确形式：“一种很强的游泳能力”。能力是抽象名词，量词用“种”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只狗有很强嗅觉能力，能找到主人。", "corrected_sentence": "这只狗有很强的嗅觉能力，能找到主人。", "error_description": "错误形式：“很强嗅觉能力”；正确形式：“很强的嗅觉能力”。形容词被“很”修饰后修饰名词，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
