INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种东西的地方，比如种菜或种树的地方。", "primary_collocate": null, "pronunciation": "zhòng zhí qū", "ipa": "ʈʂʊŋ⁵¹ ʈʂɻ̩³⁵ tɕʰy⁵⁵", "syllable_count": 3, "sentences": [{"text": "这个种植区种了很多菜。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家后面有一个小种植区。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去学校的种植区。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在种植区里种了几棵树。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个种植区里有西红柿和黄瓜。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种植区的门口有一条小河。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在种植区里给花浇水。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校新建了一个种植区，让学生种菜。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区旁边的种植区里开满了花。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天早上去种植区看看菜。", "target_word": "种植区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "種植區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "种植区：种菜、种树、种花的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1179397-e906-4d1c-9821-be884b88404e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种植区", "is_correct": true, "explanation": "正确：“种植区”是种菜的地方，与“种了很多菜”相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：“图书馆”是借阅书籍的地方，不种菜，与句意矛盾。"}, {"text": "篮球场", "is_correct": false, "explanation": "搭配：“篮球场”是运动场地，不说在篮球场里“种了很多菜”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是用来冷藏食物的电器，不能种菜。"}], "explanations": {"种植区": "正确：“种植区”是种菜的地方，与“种了很多菜”相符。", "图书馆": "语义：“图书馆”是借阅书籍的地方，不种菜，与句意矛盾。", "篮球场": "搭配：“篮球场”是运动场地，不说在篮球场里“种了很多菜”。", "冰箱": "语义：“冰箱”是用来冷藏食物的电器，不能种菜。"}, "sentence_index": 0, "correct_answer": "种植区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家后面有一根种植区，种了很多菜。", "explanation": "这里应该用〈片〉。“根”用于细长的条状物，种植区是一大片地，要用“片”。"}, {"text": "学校门口有一只种植区，里面种着西红柿。", "explanation": "这里应该用〈片〉。“只”用于禽兽、手脚等，不能用来数种植区。"}, {"text": "老师带我们看了一扇种植区。", "explanation": "这里应该用〈片〉。“扇”用于门窗，种植区要用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植区", "is_correct": true, "explanation": "正确：“种植区”指栽种植物的地方，孩子们在那里给花浇水，符合句意。"}, {"text": "书柜", "is_correct": false, "explanation": "语义：“书柜”是放书的家具，不是给花浇水的场所，句意说不通。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“地铁”是交通设施，不说在地铁里给花浇水。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：“游泳池”是用来游泳的地方，与给花浇水无关。"}], "explanations": {"种植区": "正确：“种植区”指栽种植物的地方，孩子们在那里给花浇水，符合句意。", "书柜": "语义：“书柜”是放书的家具，不是给花浇水的场所，句意说不通。", "地铁": "搭配：“地铁”是交通设施，不说在地铁里给花浇水。", "游泳池": "语义：“游泳池”是用来游泳的地方，与给花浇水无关。"}, "sentence_index": 6, "correct_answer": "种植区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天早上去种植区理发。", "explanation": "这里应该用〈理发店〉。种植区是栽种作物的地方，理发要去理发店。"}, {"text": "妈妈在种植区弹钢琴，弹得很好听。", "explanation": "这里应该用〈琴房〉。种植区是栽种作物的地方，弹钢琴要在琴房。"}, {"text": "爸爸把粮食放进种植区。", "explanation": "这里应该用〈仓库〉。种植区是栽种植物的地方，存放粮食要用仓库。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校后面种植区种了很多菜。", "corrected_sentence": "学校后面的种植区种了很多菜。", "error_description": "错误：表示地点的修饰语“学校后面”与“种植区”之间漏掉了“的”。正确：“学校后面的种植区”，表示地点的修饰语后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带有几只种植区，里面都种着菜。", "corrected_sentence": "这一带有几块种植区，里面都种着菜。", "error_description": "错误：量词用了“只”。正确：“块”。“只”用于禽兽、手脚等，种植区是一小块地，应该用“块”或“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
