INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物各个部分之间搭配的方式或特点。", "primary_collocate": null, "pronunciation": "jié gòu xìng", "ipa": "tɕiɛ˧˥ kou˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这家工厂有结构性的问题。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家发现这座桥有结构性缺陷。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定做结构性改革。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结构性矛盾一直没有解决。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的结构性问题很多。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分析了市场的结构性变化。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种结构性差异很明显。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先看清问题的结构性原因。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一次结构性调整，不是小修小改。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的结构性改造需要先经过审批。", "target_word": "结构性", "complexity_tier": "T3", "furigana": "zhè dòng lóu de jiégòuxìng gǎizào xūyào xiān jīngguò shěnpī", "sentence_source": "generated"}], "morphological_forms": [{"form": "结构性失业", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物各部分如何搭配组合所形成的特点，多修饰问题、矛盾、改革等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f2b21f7-48af-4f3b-85cd-c9621453e519') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结构性", "is_correct": true, "explanation": "“结构性”修饰“问题”，指工厂问题来自各部分搭配的方式。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”指愉快的感受，工厂有“乐趣的问题”说不通。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”指景色，不能说工厂有风景问题。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指人的外貌，不用来说工厂。"}], "explanations": {"结构性": "“结构性”修饰“问题”，指工厂问题来自各部分搭配的方式。", "乐趣": "语义：“乐趣”指愉快的感受，工厂有“乐趣的问题”说不通。", "风景": "语义：“风景”指景色，不能说工厂有风景问题。", "长相": "体貌：“长相”指人的外貌，不用来说工厂。"}, "sentence_index": 0, "correct_answer": "结构性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的结构性很稳定。", "explanation": "这里应该用〈天气〉。“结构性”指事物各部分的搭配方式，不能用来指天气；说天气稳定要用“天气”。"}, {"text": "我的朋友是结构性的。", "explanation": "这里应该用〈热情〉。“结构性”指事物各部分的搭配方式，不用来描述人的性格；形容朋友要用“热情”等词。"}, {"text": "他把结构性送给了朋友。", "explanation": "这里应该用〈礼物〉。“结构性”是属性，不是可以送出去的东西；送人的应该是“礼物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结构性", "is_correct": true, "explanation": "“结构性”指组成方式的特点，与“差异很明显”搭配自然。"}, {"text": "跑步", "is_correct": false, "explanation": "语法：“跑步”是动词，不能修饰“差异”，“这种跑步差异”不成立。"}, {"text": "唱歌", "is_correct": false, "explanation": "语法：“唱歌”是动词，不能修饰“差异”，句子不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语法：“睡觉”是动词，不能修饰“差异”，句子不成立。"}], "explanations": {"结构性": "“结构性”指组成方式的特点，与“差异很明显”搭配自然。", "跑步": "语法：“跑步”是动词，不能修饰“差异”，“这种跑步差异”不成立。", "唱歌": "语法：“唱歌”是动词，不能修饰“差异”，句子不成立。", "睡觉": "语法：“睡觉”是动词，不能修饰“差异”，句子不成立。"}, "sentence_index": 6, "correct_answer": "结构性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的结构性在去年很热闹。", "explanation": "这里应该用〈气氛〉。“结构性”指事物各部分的搭配方式，不用来描述场面的热闹；说热闹的场面要用“气氛”等词。"}, {"text": "这栋楼的结构性很好吃。", "explanation": "这里应该用〈味道〉。“结构性”指组成方式，不能用来形容口感或滋味；形容口感要用“味道”。"}, {"text": "这栋楼的结构性很多。", "explanation": "这里应该用〈部分〉。“结构性”不是可数名词，不能说“很多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋楼的问题是结构性。", "corrected_sentence": "这栋楼的问题是结构性的。", "error_description": "错误：“是结构性”；正确：“是结构性的”。作表语时，“结构性”后面要加“的”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革的重点是结构性地。", "corrected_sentence": "这次改革的重点是结构性的。", "error_description": "错误：“是结构性地”；正确：“是结构性的”。作表语时要用“的”，“地”用于动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64831937-5f39-4db5-afa7-0c351e12d69c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放松", "is_correct": true, "explanation": "反义：“紧张”与“放松”相对，指心里由害怕转为安适。"}, {"text": "陌生", "is_correct": false, "explanation": "无反义关系：“陌生”指不熟悉，与“紧张”的心理意义不相对。"}, {"text": "深刻", "is_correct": false, "explanation": "无反义关系：“深刻”形容印象或道理深入，与“紧张”不构成反义。"}, {"text": "清脆", "is_correct": false, "explanation": "无反义关系：“清脆”形容声音，与“紧张”的心理状态无关。"}], "correct_answer": "放松", "explanations": {"放松": "反义：“紧张”与“放松”相对，指心里由害怕转为安适。", "陌生": "无反义关系：“陌生”指不熟悉，与“紧张”的心理意义不相对。", "深刻": "无反义关系：“深刻”形容印象或道理深入，与“紧张”不构成反义。", "清脆": "无反义关系：“清脆”形容声音，与“紧张”的心理状态无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放松", "is_correct": true, "explanation": "反义：“紧张”与“放松”相对，指心里由害怕转为安适。"}, {"text": "幽默", "is_correct": false, "explanation": "无反义关系：“幽默”形容言语风趣，与“紧张”的心理状态无关。"}, {"text": "平淡", "is_correct": false, "explanation": "无反义关系：“平淡”形容不突出，与“紧张”的心理意义不相对。"}, {"text": "热烈", "is_correct": false, "explanation": "无反义关系：“热烈”形容情绪高涨，与“紧张”不构成反义。"}], "correct_answer": "放松", "explanations": {"放松": "反义：“紧张”与“放松”相对，指心里由害怕转为安适。", "幽默": "无反义关系：“幽默”形容言语风趣，与“紧张”的心理状态无关。", "平淡": "无反义关系：“平淡”形容不突出，与“紧张”的心理意义不相对。", "热烈": "无反义关系：“热烈”形容情绪高涨，与“紧张”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里很害怕，不能放松。", "primary_collocate": null, "pronunciation": "jǐn zhāng", "ipa": "tɕin˨˩ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "我坐飞机的时候总是很紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩第一次看牙医，紧张得哭了。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里一个人在家，她紧张极了。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他紧张得手一直在发抖。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听见奇怪的声音，我心里很紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放轻松，不用紧张，这只是个小测试。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她紧张地看着门外的黑影。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗朝我跑来，我紧张得不敢动。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一进医院，我就觉得紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子站在高高的台上，脸上很紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紧张感", "label": "复合"}, {"form": "緊張", "label": "繁体"}], "register": "口语", "sense_fingerprint": "形容词：心里害怕、不能放松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1179397-e906-4d1c-9821-be884b88404e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紧张", "is_correct": true, "explanation": "正确。“很紧张”表示心里害怕、不能放松，符合句中的描述。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容空气、皮肤，不用来形容人的心里状态。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”描述环境，与句中“我”的心理状态不符。"}, {"text": "平坦", "is_correct": false, "explanation": "搭配：“平坦”形容地面、道路，不说人“很平坦”。"}], "explanations": {"紧张": "正确。“很紧张”表示心里害怕、不能放松，符合句中的描述。", "干燥": "搭配：“干燥”形容空气、皮肤，不用来形容人的心里状态。", "潮湿": "语义：“潮湿”描述环境，与句中“我”的心理状态不符。", "平坦": "搭配：“平坦”形容地面、道路，不说人“很平坦”。"}, "sentence_index": 0, "correct_answer": "紧张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子考了第一名，紧张得直拍手。", "explanation": "这里应该用〈兴奋〉。紧张表示害怕、不能放松，因高兴而拍手要用兴奋。"}, {"text": "听到医生说手术很成功，她终于紧张了。", "explanation": "这里应该用〈安心〉。紧张表示心里害怕、不能放松，听到好消息后心里踏实要用安心。"}, {"text": "他每天在花园里浇花，心情很紧张。", "explanation": "这里应该用〈放松〉。紧张表示心里害怕、不能放松，悠然浇花的心情要用放松。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紧张", "is_correct": true, "explanation": "正确。“紧张地看着”表示因害怕而注视，符合门外黑影的语境。"}, {"text": "欢喜", "is_correct": false, "explanation": "语义：“欢喜”表示高兴，与门外黑影带来的害怕语境不合。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”多用于对待人，不说“热情地看着黑影”。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”表示轻松的好心情，与句中害怕的情绪不合。"}], "explanations": {"紧张": "正确。“紧张地看着”表示因害怕而注视，符合门外黑影的语境。", "欢喜": "语义：“欢喜”表示高兴，与门外黑影带来的害怕语境不合。", "热情": "搭配：“热情”多用于对待人，不说“热情地看着黑影”。", "愉快": "语义：“愉快”表示轻松的好心情，与句中害怕的情绪不合。"}, "sentence_index": 6, "correct_answer": "紧张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很生气，紧张地摔上了门。", "explanation": "这里应该用〈发火〉。紧张表示心里害怕、不能放松，描述发怒摔门要用发火。"}, {"text": "阳光很好，她一边哼着歌一边洗衣服，心里很紧张。", "explanation": "这里应该用〈轻松〉。紧张表示心里害怕、不能放松，哼着歌洗衣服的心情要用轻松。"}, {"text": "她和朋友在公园里开心地聊天，心里很紧张。", "explanation": "这里应该用〈愉快〉。紧张表示害怕、不能放松，和朋友开心聊天的心情要用愉快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "走进黑漆漆的地下室，我紧张地腿都软了。", "corrected_sentence": "走进黑漆漆的地下室，我紧张得腿都软了。", "error_description": "「紧张」后引出结果补语“腿都软了”要用“得”，用“地”（状语标记）则不成句，应说「紧张得腿都软了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一听见雷声，心里很就紧张。", "corrected_sentence": "她一听见雷声，心里就很紧张。", "error_description": "副词「就」与「很」次序颠倒：「很」要紧接在形容词“紧张”之前，应说「心里就很紧张」，不能说「心里很就紧张」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
