INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用船或飞机运送东西。", "primary_collocate": null, "pronunciation": "háng yùn", "ipa": "xɑŋ˧˥ yn˥˩", "syllable_count": 2, "sentences": [{"text": "这批茶叶从杭州航运到国外。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些大机器要用船航运过去。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算把这批汽车航运到欧洲。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些家具是从意大利航运来的。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货太重了，只能用大船航运。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花很贵，所以用飞机航运。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些煤先运到港口，再航运到南方。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友把他的旧车航运回了老家。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批机器已经航运到上海港了。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果一般都是用船航运的。", "target_word": "航运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "航运过", "label": "体标"}, {"form": "航運", "label": "繁体"}], "register": "书面", "sense_fingerprint": "动词：用船或飞机运送东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1179397-e906-4d1c-9821-be884b88404e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航运", "is_correct": true, "explanation": "正确：“航运”指用船或飞机运送货物，与“从杭州……到国外”相符。"}, {"text": "生长", "is_correct": false, "explanation": "语义：茶叶不能从杭州“生长”到国外，与运输语境矛盾。"}, {"text": "思考", "is_correct": false, "explanation": "语义：茶叶无法思考，与“运到国外”的动作无关。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”只用于书报等出版物，不能用于茶叶。"}], "explanations": {"航运": "正确：“航运”指用船或飞机运送货物，与“从杭州……到国外”相符。", "生长": "语义：茶叶不能从杭州“生长”到国外，与运输语境矛盾。", "思考": "语义：茶叶无法思考，与“运到国外”的动作无关。", "出版": "搭配：“出版”只用于书报等出版物，不能用于茶叶。"}, "sentence_index": 0, "correct_answer": "航运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们把人航运到了北京。", "explanation": "这里应该用〈乘〉。航运只用于运送货物，运送人员坐飞机或船要说“乘”。"}, {"text": "工人们在仓库里航运货物。", "explanation": "这里应该用〈搬运〉。航运专指用船或飞机运送东西，在仓库里搬货要说“搬运”。"}, {"text": "他用卡车把旧书航运回了家。", "explanation": "这里应该用〈拉〉。航运专指用船或飞机运送东西，用卡车运书要说“拉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航运", "is_correct": true, "explanation": "正确：“航运”指用船运送，与“再……到南方”的运输过程相符。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是饮品，煤不能饮用。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：煤不能朗读，与“运到港口”的运输语境矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：煤不能唱歌，句中描述的是运输过程。"}], "explanations": {"航运": "正确：“航运”指用船运送，与“再……到南方”的运输过程相符。", "饮用": "搭配：“饮用”的对象是饮品，煤不能饮用。", "朗读": "语义：煤不能朗读，与“运到港口”的运输语境矛盾。", "唱歌": "语义：煤不能唱歌，句中描述的是运输过程。"}, "sentence_index": 6, "correct_answer": "航运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用自行车把这箱书航运到了学校。", "explanation": "这里应该用〈骑车〉。航运专指用船或飞机运送东西，用自行车送书要说“骑车”。"}, {"text": "他把行李航运到了楼上。", "explanation": "这里应该用〈提〉。航运专指用船或飞机运送东西，把行李送上楼要说“提”或“搬”。"}, {"text": "这些汽车是用铁路航运的。", "explanation": "这里应该用〈运输〉。航运专指用船或飞机，用铁路运汽车要说“运输”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些玩具航运欧洲。", "corrected_sentence": "这些玩具航运到了欧洲。", "error_description": "错误：漏掉方向补语“到”。运送到某地要说“航运到了欧洲”，不能说“航运欧洲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些货物把航运到北京了。", "corrected_sentence": "这些货物航运到北京了。", "error_description": "错误：“把”字句中“航运”后缺少宾语，“把”不能直接接动词。应说“这些货物航运到北京了”，去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
