INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家对进出口货物征收的税，比如外国货物进来时要交的钱。", "primary_collocate": null, "pronunciation": "guān shuì", "ipa": "kwan˥ ʂweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "外国的手机进来要交关税。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关税高了，进口的东西就贵了。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的关税很低。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一辆外国车，还交了关税。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一些国家想用关税保护本国工厂。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，关税让咖啡的价格涨了。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不懂什么是关税。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批水果交了关税，才能卖到我们国家。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家互相提高了关税。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这种茶叶的关税降了一半。", "target_word": "关税", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进口关税", "label": "复合"}, {"form": "關稅", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：外国货物进来时要交的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1179397-e906-4d1c-9821-be884b88404e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关税", "is_correct": true, "explanation": "正确。外国手机进来时要交的是关税，符合句意。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是上学的费用，与外国手机进口无关。"}, {"text": "房租", "is_correct": false, "explanation": "语义：“房租”是租住房屋的费用，与货物进口无关。"}, {"text": "利息", "is_correct": false, "explanation": "语义：“利息”是借贷产生的费用，与手机进口的语境不合。"}], "explanations": {"关税": "正确。外国手机进来时要交的是关税，符合句意。", "学费": "语义：“学费”是上学的费用，与外国手机进口无关。", "房租": "语义：“房租”是租住房屋的费用，与货物进口无关。", "利息": "语义：“利息”是借贷产生的费用，与手机进口的语境不合。"}, "sentence_index": 0, "correct_answer": "关税"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次进口，我们交了一只关税。", "explanation": "这里的量词应该用〈笔〉，〈只〉用于动物或成对的东西，不能用来计量关税。"}, {"text": "开车过桥要交关税。", "explanation": "这里应该用〈过路费〉。关税是对进出口商品征收的税，过桥要交的是过路费。"}, {"text": "违章停车，要交一笔关税。", "explanation": "这里应该用〈罚款〉。关税是进出口商品的税，违章停车的处罚叫罚款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关税", "is_correct": true, "explanation": "正确。“什么是关税”询问的是税种概念，符合句意。"}, {"text": "因为", "is_correct": false, "explanation": "语法：「因为」是连词，不能作「什么是」的宾语。"}, {"text": "很快", "is_correct": false, "explanation": "语法：「很快」是副词，不能作「什么是」的宾语。"}, {"text": "并且", "is_correct": false, "explanation": "语法：「并且」是连词，不能作「什么是」的宾语。"}], "explanations": {"关税": "正确。“什么是关税”询问的是税种概念，符合句意。", "因为": "语法：「因为」是连词，不能作「什么是」的宾语。", "很快": "语法：「很快」是副词，不能作「什么是」的宾语。", "并且": "语法：「并且」是连词，不能作「什么是」的宾语。"}, "sentence_index": 6, "correct_answer": "关税"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "借图书馆的书，要先交关税。", "explanation": "这里应该用〈押金〉。关税只针对进出口商品，借书时交的押金不叫关税。"}, {"text": "这批货我们交了一座关税。", "explanation": "这里的量词应该用〈笔〉，〈座〉用于山、建筑等，不能用来计量关税。"}, {"text": "孩子上学，要交一笔关税。", "explanation": "这里应该用〈学费〉。关税是进出口商品的税，上学交的费用叫学费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买的进口手机要交一张关税。", "corrected_sentence": "我买的进口手机要交一笔关税。", "error_description": "「关税」应搭配量词“笔”，“张”用于纸张等平面物，不能计量税款。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那颗关税我们已经付清了。", "corrected_sentence": "那笔关税我们已经付清了。", "error_description": "「关税」应用量词“笔”，“颗”用于粒状的东西，不能修饰税款，应说「那笔关税」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d7a2c73-d7ce-440d-922a-a37d8d053172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
