INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水往一个方向走。", "primary_collocate": null, "pronunciation": "liú xiàng", "ipa": "ljou̯˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "河水的流向是从西到东。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的箭头表示河流的流向。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小河的流向很特别。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先观察一下这段河道的流向。", "target_word": "流向", "complexity_tier": "T3", "furigana": "liú xiàng", "sentence_source": "generated"}, {"text": "下雨后，雨水的流向跟着地势走。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用红笔画出了河水的流向。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用树叶测出了小溪的流向。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里地势低，所以水的流向是向南。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下水的流向很难看出来。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人要先搞清楚污水的流向，再修管道。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "河水流向", "label": "复合"}, {"form": "水流流向", "label": "复合"}], "register": "中性", "sense_fingerprint": "河水、雨水等水流动的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1532fc7-f679-448f-975d-e35ead7876dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流速", "is_correct": false, "explanation": "语义：流速说水流的快慢，不能说明水流从哪里到哪里的方向。"}, {"text": "流向", "is_correct": true, "explanation": "流向指水流动的方向，与“从西到东”搭配，符合句意。"}, {"text": "水位", "is_correct": false, "explanation": "语义：水位指水面的高低，不能说明水流从西到东的走向。"}, {"text": "流域", "is_correct": false, "explanation": "语义：流域指河流经过的区域，不是水流的方向。"}], "explanations": {"流速": "语义：流速说水流的快慢，不能说明水流从哪里到哪里的方向。", "流向": "流向指水流动的方向，与“从西到东”搭配，符合句意。", "水位": "语义：水位指水面的高低，不能说明水流从西到东的走向。", "流域": "语义：流域指河流经过的区域，不是水流的方向。"}, "sentence_index": 0, "correct_answer": "流向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段河道的流向很快，要注意安全。", "explanation": "这里应该用〈流速〉。流向说水流的方向，水流的快慢要用〈流速〉。"}, {"text": "这条河在夏天的流向最大。", "explanation": "这里应该用〈流量〉。流向说方向，不说大小；夏天水量最大要用〈流量〉。"}, {"text": "这条河的流向在夏天上涨了。", "explanation": "这里应该用〈水位〉。流向说方向，不能上涨；河水高度的变化要用〈水位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：用树叶测不出颜色，与“测出”的对象不相符。"}, {"text": "流向", "is_correct": true, "explanation": "流向指水流朝哪边走，用树叶漂浮可以测出，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“测出味道”不搭配，树叶无法测量味道。"}, {"text": "光泽", "is_correct": false, "explanation": "语义：光泽是表面的反光效果，与水流的测量无关。"}], "explanations": {"颜色": "语义：用树叶测不出颜色，与“测出”的对象不相符。", "流向": "流向指水流朝哪边走，用树叶漂浮可以测出，符合句意。", "味道": "搭配：“测出味道”不搭配，树叶无法测量味道。", "光泽": "语义：光泽是表面的反光效果，与水流的测量无关。"}, "sentence_index": 6, "correct_answer": "流向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口井的流向很好，可以直接饮用。", "explanation": "这里应该用〈水质〉。流向说水流的方向，水的好坏要用〈水质〉。"}, {"text": "这口井的流向很低，适合保存食物。", "explanation": "这里应该用〈水温〉。流向说方向，水的冷热要用〈水温〉。"}, {"text": "这片湖的流向不到两米，很适合划船。", "explanation": "这里应该用〈水深〉。流向说方向，水的深浅要用〈水深〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖水的流向地是向东。", "corrected_sentence": "湖水的流向是向东。", "error_description": "错误：“流向地是向东”中多了“地”；正确：“流向是向东”。“流向”是名词，后面不能接“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨季时河水的流向了东方。", "corrected_sentence": "雨季时河水流向了东方。", "error_description": "错误：“河水的流向了东方”；正确：“河水流向了东方”。这里“流向”是动词，表示水朝某个方向流，前面加“的”后就变成名词短语，不能再接动词“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21728, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "挖掘", "is_correct": false, "explanation": "挖掘与“扰乱”没有对立关系，不构成反义词。"}, {"text": "整理", "is_correct": true, "explanation": "整理与“扰乱”意义相反：“扰乱”是把整齐的东西弄乱，“整理”是把东西收拾整齐。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论与“扰乱”没有对立关系，不构成反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行与“扰乱”没有对立关系，不构成反义词。"}], "correct_answer": "整理", "explanations": {"挖掘": "挖掘与“扰乱”没有对立关系，不构成反义词。", "整理": "整理与“扰乱”意义相反：“扰乱”是把整齐的东西弄乱，“整理”是把东西收拾整齐。", "讨论": "讨论与“扰乱”没有对立关系，不构成反义词。", "旅行": "旅行与“扰乱”没有对立关系，不构成反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21728, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "考察", "is_correct": false, "explanation": "考察与“扰乱”没有对立关系，不构成反义词。"}, {"text": "整理", "is_correct": true, "explanation": "整理与“扰乱”意义相反：“扰乱”是把整齐的东西弄乱，“整理”是把东西收拾整齐。"}, {"text": "制造", "is_correct": false, "explanation": "制造与“扰乱”没有对立关系，不构成反义词。"}, {"text": "宣布", "is_correct": false, "explanation": "宣布与“扰乱”没有对立关系，不构成反义词。"}], "correct_answer": "整理", "explanations": {"考察": "考察与“扰乱”没有对立关系，不构成反义词。", "整理": "整理与“扰乱”意义相反：“扰乱”是把整齐的东西弄乱，“整理”是把东西收拾整齐。", "制造": "制造与“扰乱”没有对立关系，不构成反义词。", "宣布": "宣布与“扰乱”没有对立关系，不构成反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得乱乱的，不整齐。", "primary_collocate": null, "pronunciation": "rǎo luàn", "ipa": "ɻɑʊ˨˩˦ lwan˥˩", "syllable_count": 2, "sentences": [{"text": "一阵大风扰乱了整齐的队形。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "yī zhèn dà fēng rǎo luàn le zhěng qí de duì xíng", "sentence_source": "generated"}, {"text": "孩子们冲进教室，扰乱了原本整齐的队伍。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "hái zi men chōng jìn jiào shì rǎo luàn le yuán běn zhěng qí de duì wu", "sentence_source": "generated"}, {"text": "突然的枪声扰乱了士兵们整齐的阵形。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "tū rán de qiāng shēng rǎo luàn le shì bīng men zhěng qí de zhèn xíng", "sentence_source": "generated"}, {"text": "突然的哨声扰乱了新兵整齐的步伐。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "tū rán de shào shēng rǎo luàn le xīn bīng zhěng qí de bù fá", "sentence_source": "generated"}, {"text": "游客们拥进景区，扰乱了入口处整齐的队列。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "yóu kè men yōng jìn jǐng qū rǎo luàn le rù kǒu chù zhěng qí de duì liè", "sentence_source": "generated"}, {"text": "他匆忙穿过人群，扰乱了一排整齐的阵列。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "tā cōng máng chuān guò rén qún rǎo luàn le yī pái zhěng qí de zhèn liè", "sentence_source": "generated"}, {"text": "这场混战扰乱了双方整齐的阵线。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "zhè chǎng hùn zhàn rǎo luàn le shuāng fāng zhěng qí de zhèn xiàn", "sentence_source": "generated"}, {"text": "突然的变故扰乱了整齐的行列。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "tū rán de biàn gù rǎo luàn le zhěng qí de háng liè", "sentence_source": "generated"}, {"text": "他不小心撞了一下，扰乱了排好的方阵。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "tā bù xiǎo xīn zhuàng le yí xià rǎo luàn le pái hǎo de fāng zhèn", "sentence_source": "generated"}, {"text": "突然的爆炸扰乱了整齐的编队。", "target_word": "扰乱", "complexity_tier": "T3", "furigana": "tū rán de bào zhà rǎo luàn le zhěng qí de biān duì", "sentence_source": "generated"}], "morphological_forms": [{"form": "扰乱了", "label": "体标"}, {"form": "扰乱过", "label": "体标"}, {"form": "擾亂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把整齐摆好的东西弄乱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0f7a4f-5379-4dcd-92b3-4e8d45a14fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保持", "is_correct": false, "explanation": "语义：“保持”表示维持原样，与“大风”打乱队形的语境相反。"}, {"text": "扰乱", "is_correct": true, "explanation": "“扰乱”指把整齐摆好的东西弄乱，与“一阵大风”造成的结果相符。"}, {"text": "排列", "is_correct": false, "explanation": "配价：“排列”的施事应是人，“大风”不能排列队形。"}, {"text": "整顿", "is_correct": false, "explanation": "配价：“整顿”需要人来组织，“大风”不能整顿队形。"}], "explanations": {"保持": "语义：“保持”表示维持原样，与“大风”打乱队形的语境相反。", "扰乱": "“扰乱”指把整齐摆好的东西弄乱，与“一阵大风”造成的结果相符。", "排列": "配价：“排列”的施事应是人，“大风”不能排列队形。", "整顿": "配价：“整顿”需要人来组织，“大风”不能整顿队形。"}, "sentence_index": 0, "correct_answer": "扰乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大火扰乱了那座老房子。", "explanation": "这里应该用〈烧毁〉。扰乱只指把整齐的东西弄乱，房屋被烧毁要用烧毁。"}, {"text": "他一拳扰乱了那扇玻璃门。", "explanation": "这里应该用〈打碎〉。扰乱只指把整齐的东西弄乱，玻璃被打碎要用打碎。"}, {"text": "他一摔，扰乱了那只花瓶。", "explanation": "这里应该用〈摔碎〉。扰乱只指把东西弄乱，东西摔坏、破碎要用摔碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指挥", "is_correct": false, "explanation": "配价：“指挥”的施事应是人，“混战”不能指挥阵线。"}, {"text": "扰乱", "is_correct": true, "explanation": "“扰乱”指把整齐的东西弄乱，与“这场混战”造成的结果相符。"}, {"text": "检阅", "is_correct": false, "explanation": "配价：“检阅”需要人主动查看部队，“混战”不能检阅阵线。"}, {"text": "赞扬", "is_correct": false, "explanation": "语义：“赞扬”是正面评价，与“混战”造成的混乱语境相反。"}], "explanations": {"指挥": "配价：“指挥”的施事应是人，“混战”不能指挥阵线。", "扰乱": "“扰乱”指把整齐的东西弄乱，与“这场混战”造成的结果相符。", "检阅": "配价：“检阅”需要人主动查看部队，“混战”不能检阅阵线。", "赞扬": "语义：“赞扬”是正面评价，与“混战”造成的混乱语境相反。"}, "sentence_index": 6, "correct_answer": "扰乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的话扰乱了宝贵的生命。", "explanation": "这里应该用〈危害〉。扰乱指打乱秩序，危及生命要说危害。"}, {"text": "他的脏手扰乱了雪白的桌布。", "explanation": "这里应该用〈弄脏〉。扰乱只指把整齐的东西弄乱，桌布被弄脏要用弄脏。"}, {"text": "他一刀扰乱了那片成熟的麦田。", "explanation": "这里应该用〈割倒〉。扰乱只指把东西弄乱，庄稼被割倒要用割倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们把桌上的书扰乱。", "corrected_sentence": "孩子们把桌上的书扰乱了。", "error_description": "错误：“把”字句中动词后缺少“了”，句子不完整。应补上“了”，改为“孩子们把桌上的书扰乱了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这阵大风很扰乱了晾好的一排衣服。", "corrected_sentence": "这阵大风扰乱了晾好的一排衣服。", "error_description": "错误：动作动词“扰乱”前加了程度副词“很”。“很”不修饰这类动作动词，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
