INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21736, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情接着发生，意思就是“就”。", "primary_collocate": null, "pronunciation": "zé", "ipa": "tsɤ˧˥", "syllable_count": 1, "sentences": [{"text": "学习不努力，则很难进步。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人多则热闹，人少则安静。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太热则会烫手，太冷则不好喝。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不进则退，学习就像划船一样。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开得太快则容易出事故。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你多练习，则一定会进步。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天晴则去爬山，下雨在家看书。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱花得太多则不够用。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜放久了则会坏。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡得早则起得早，身体也会好。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "副词；表示承接，前一件事发生后接着出现结果，相当于“就”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 太热 (Zipf 3.16), 烫 (Zipf 3.98), 好喝 (Zipf 3.59)','sentence 6 above tier T1: 3 words above tier T1 (max 2): 晴 (Zipf 3.85), 爬山 (Zipf 3.34), 看书 (Zipf 3.84)']::text[], 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21736, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "则", "is_correct": true, "explanation": "则 zé，副词，表示事情接着发生，相当于“就”。"}, {"text": "折", "is_correct": false, "explanation": "zhé（第二声）与 zé 声母不同（zh 与 z），意思是折叠。"}, {"text": "贼", "is_correct": false, "explanation": "zéi（第二声）与 zé 韵母不同（ei 与 e），意思是小偷。"}, {"text": "哲", "is_correct": false, "explanation": "zhé 与 zé 声母不同（zh 与 z），意思是哲学、智慧。"}, {"text": "蛇", "is_correct": false, "explanation": "shé 与 zé 声母不同（sh 与 z），意思是蛇。"}, {"text": "德", "is_correct": false, "explanation": "dé 与 zé 声母不同（d 与 z），意思是道德。"}], "explanations": {"则": "则 zé，副词，表示事情接着发生，相当于“就”。", "折": "zhé（第二声）与 zé 声母不同（zh 与 z），意思是折叠。", "贼": "zéi（第二声）与 zé 韵母不同（ei 与 e），意思是小偷。", "哲": "zhé 与 zé 声母不同（zh 与 z），意思是哲学、智慧。", "蛇": "shé 与 zé 声母不同（sh 与 z），意思是蛇。", "德": "dé 与 zé 声母不同（d 与 z），意思是道德。"}, "sentence_index": null, "correct_answer": "则"}, "level_3": {"options": [{"text": "则", "is_correct": true, "explanation": "则：表示承接，“学习不努力”之后接着出现“很难进步”的结果，相当于“就”。"}, {"text": "却", "is_correct": false, "explanation": "语义：却表示转折，与“不努力，难进步”的顺理成章的关系不合。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：偏偏表示出乎意料，与这里顺理成章的结果不合。"}, {"text": "才", "is_correct": false, "explanation": "搭配：才表示“只有到……才”，不能与“很难进步”这一结果搭配。"}], "explanations": {"则": "则：表示承接，“学习不努力”之后接着出现“很难进步”的结果，相当于“就”。", "却": "语义：却表示转折，与“不努力，难进步”的顺理成章的关系不合。", "偏偏": "语义：偏偏表示出乎意料，与这里顺理成章的结果不合。", "才": "搭配：才表示“只有到……才”，不能与“很难进步”这一结果搭配。"}, "sentence_index": 0, "correct_answer": "则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店外观普通，店里的东西则很贵。", "explanation": "这里的〈则〉表示对比，不表示事情接着发生的“就”。"}, {"text": "他戒烟有两个原因：一则为了健康，二则为了省钱。", "explanation": "这里的〈则〉用于列举，不表示事情接着发生。"}, {"text": "昨天的报纸上登了一则广告。", "explanation": "这里的〈则〉是量词，用于广告，不表示承接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21736, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "则", "is_correct": true, "explanation": "则 zé，副词，表示事情接着发生，相当于“就”。"}, {"text": "格", "is_correct": false, "explanation": "gé 与 zé 声母不同（g 与 z），意思是格子。"}, {"text": "隔", "is_correct": false, "explanation": "gé 与 zé 声母不同（g 与 z），意思是隔开。"}, {"text": "舌", "is_correct": false, "explanation": "shé 与 zé 声母不同（sh 与 z），意思是舌头。"}, {"text": "得", "is_correct": false, "explanation": "dé 与 zé 声母不同（d 与 z），意思是获得。"}], "explanations": {"则": "则 zé，副词，表示事情接着发生，相当于“就”。", "格": "gé 与 zé 声母不同（g 与 z），意思是格子。", "隔": "gé 与 zé 声母不同（g 与 z），意思是隔开。", "舌": "shé 与 zé 声母不同（sh 与 z），意思是舌头。", "得": "dé 与 zé 声母不同（d 与 z），意思是获得。"}, "sentence_index": null, "correct_answer": "则"}, "level_3": {"options": [{"text": "则", "is_correct": true, "explanation": "则：表示承接，天晴之后接着去爬山，相当于“就”。"}, {"text": "偏", "is_correct": false, "explanation": "语义：偏表示故意或相反，与“天晴就去爬山”的顺承关系不合。"}, {"text": "竟", "is_correct": false, "explanation": "搭配：竟表示出乎意料，与这里按条件安排的常规行动不合。"}, {"text": "已", "is_correct": false, "explanation": "搭配：已表示已经完成，与“天晴则去爬山”这种将来的安排不合。"}], "explanations": {"则": "则：表示承接，天晴之后接着去爬山，相当于“就”。", "偏": "语义：偏表示故意或相反，与“天晴就去爬山”的顺承关系不合。", "竟": "搭配：竟表示出乎意料，与这里按条件安排的常规行动不合。", "已": "搭配：已表示已经完成，与“天晴则去爬山”这种将来的安排不合。"}, "sentence_index": 6, "correct_answer": "则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的目标则是成为医生。", "explanation": "这里的〈则是〉表示判断，不表示事情接着发生的“就”。"}, {"text": "他以身作则，带头遵守制度。", "explanation": "这里的〈则〉是“准则”的意思，不表示承接。"}, {"text": "这是一则寓言，很有意思。", "explanation": "这里的〈则〉是量词，用于寓言，不表示承接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一到家，先则洗个澡。", "corrected_sentence": "他一到家，则先洗个澡。", "error_description": "错误：“先则洗个澡”；正确：“则先洗个澡”。“则”表示承接，应放在“先”之前，不能放在“先”与动词之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下班，却则去超市买菜。", "corrected_sentence": "他一下班，则去超市买菜。", "error_description": "错误：“却则”；正确：“则”。“则”表示承接，不能与表示转折的“却”叠用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
