INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示全都一样或全都如此。", "primary_collocate": null, "pronunciation": "jūn", "ipa": "tɕyn⁵⁵", "syllable_count": 1, "sentences": [{"text": "这里的房子价格均不高。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个孩子的成绩均很好。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加比赛的学生均已到齐。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些水果均是今天早上买的。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三位老师均来自北京。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里的衣服均打八折。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的年纪均在二十岁左右。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各位客人均可免费喝茶。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几本书均是他写的。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全班同学的作业均已交齐。", "target_word": "均", "complexity_tier": "T3", "furigana": "quán bān tóng xué de zuò yè jūn yǐ jiāo qí", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "范围副词，表示全都如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd8ccd27-d9af-45a9-8d08-de0015174fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "均", "is_correct": true, "explanation": "正确：“均”（jūn）表示全都，是这里要听的词。"}, {"text": "菌", "is_correct": false, "explanation": "jùn（第四声）与 jūn（第一声）声调不同，意思是细菌。"}, {"text": "居", "is_correct": false, "explanation": "jū 与 jūn 韵母不同，少了鼻音 -n，意思是居住。"}, {"text": "精", "is_correct": false, "explanation": "jīng 与 jūn 韵母不同：-ing 与 -un，意思是精华、精细。"}, {"text": "俊", "is_correct": false, "explanation": "jùn（第四声）与 jūn（第一声）声调不同，意思是英俊。"}], "explanations": {"均": "正确：“均”（jūn）表示全都，是这里要听的词。", "菌": "jùn（第四声）与 jūn（第一声）声调不同，意思是细菌。", "居": "jū 与 jūn 韵母不同，少了鼻音 -n，意思是居住。", "精": "jīng 与 jūn 韵母不同：-ing 与 -un，意思是精华、精细。", "俊": "jùn（第四声）与 jūn（第一声）声调不同，意思是英俊。"}, "sentence_index": null, "correct_answer": "均"}, "level_3": {"options": [{"text": "均", "is_correct": true, "explanation": "正确：“均”表示全都，与“这里的房子价格”搭配，符合“不高”的整体描述。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示比较中的最高程度，句中没有比较对象，“最不高”说不通。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，句子要说的是这些房子价格都不高，而不是只有个别。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰程度，“很不高”不是通常的说法，与整体描述不合。"}], "explanations": {"均": "正确：“均”表示全都，与“这里的房子价格”搭配，符合“不高”的整体描述。", "最": "搭配：“最”表示比较中的最高程度，句中没有比较对象，“最不高”说不通。", "只": "语义：“只”表示限定，句子要说的是这些房子价格都不高，而不是只有个别。", "很": "搭配：“很”修饰程度，“很不高”不是通常的说法，与整体描述不合。"}, "sentence_index": 0, "correct_answer": "均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些人中，有一个均来了。", "explanation": "“均”表示全部一致，“有一个”只指部分，两者矛盾，不能搭配。"}, {"text": "这个水果均是今天早上买的。", "explanation": "“均”表示全部，要求主语是多个对象；这里只说“这个水果”一个，不能用“均”。"}, {"text": "我均去过北京。", "explanation": "“均”表示全都，主语须是两个或以上；“我”只指一人，不能用“均”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "均", "is_correct": true, "explanation": "正确：“均”（jūn）表示全都，是这里要听的词。"}, {"text": "惊", "is_correct": false, "explanation": "jīng 与 jūn 韵母不同：-ing 与 -un，意思是吃惊。"}, {"text": "经", "is_correct": false, "explanation": "jīng 与 jūn 韵母不同：-ing 与 -un，意思是经过。"}, {"text": "尊", "is_correct": false, "explanation": "zūn 与 jūn 声母不同：z 与 j，意思是尊敬。"}], "explanations": {"均": "正确：“均”（jūn）表示全都，是这里要听的词。", "惊": "jīng 与 jūn 韵母不同：-ing 与 -un，意思是吃惊。", "经": "jīng 与 jūn 韵母不同：-ing 与 -un，意思是经过。", "尊": "zūn 与 jūn 声母不同：z 与 j，意思是尊敬。"}, "sentence_index": null, "correct_answer": "均"}, "level_3": {"options": [{"text": "均", "is_correct": true, "explanation": "正确：“均”表示全都，符合“他们的年纪……在二十岁左右”的整体描述。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”突出程度，与“在二十岁左右”的估计语气冲突。"}, {"text": "一共", "is_correct": false, "explanation": "搭配：“一共”用于总计，年纪不能加总，“一共在二十岁左右”不成立。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意与预期相反，与描述年龄范围的语境不合。"}], "explanations": {"均": "正确：“均”表示全都，符合“他们的年纪……在二十岁左右”的整体描述。", "特别": "语义：“特别”突出程度，与“在二十岁左右”的估计语气冲突。", "一共": "搭配：“一共”用于总计，年纪不能加总，“一共在二十岁左右”不成立。", "偏偏": "语义：“偏偏”表示故意与预期相反，与描述年龄范围的语境不合。"}, "sentence_index": 6, "correct_answer": "均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的同学均很高，只有他很矮。", "explanation": "“均”表示全部一致，后面不能接“只有他”这样的例外，前后矛盾。"}, {"text": "这间屋子的窗户均朝南，但有一扇朝北。", "explanation": "“均”表示全部一致，后面却说“有一扇朝北”，前后矛盾。"}, {"text": "全班同学的作业均已交齐，但有几个人还没交。", "explanation": "“均”表示全都如此，后面却说“有几个人还没交”，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些同学均的已报名。", "corrected_sentence": "这些同学均已报名。", "error_description": "“均”是副词，后面不能加“的”，应说“这些同学均已报名”，不能说“均的已报名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位老师都均已经到了。", "corrected_sentence": "几位老师均已经到了。", "error_description": "“均”和“都”都表示全都，不能叠用，应去掉“都”，说“几位老师均已经到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee911bcc-5f51-4212-b250-ee73f2686fed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "个别", "is_correct": true, "explanation": "正确。“个别”指少数、不普遍，与“普遍”构成反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物头绪多、难理解，与“普遍”的意思没有对立关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”形容价钱低，与“普遍”的范围广没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“普遍”不构成反义。"}], "correct_answer": "个别", "explanations": {"个别": "正确。“个别”指少数、不普遍，与“普遍”构成反义关系。", "复杂": "“复杂”形容事物头绪多、难理解，与“普遍”的意思没有对立关系。", "便宜": "“便宜”形容价钱低，与“普遍”的范围广没有反义关系。", "明亮": "“明亮”形容光线充足或颜色鲜亮，与“普遍”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "个别", "is_correct": true, "explanation": "正确。“个别”指少数、不普遍，与“普遍”构成反义关系。"}, {"text": "清淡", "is_correct": false, "explanation": "“清淡”形容味道或颜色淡，与“普遍”的意思无关，不构成反义。"}, {"text": "迟缓", "is_correct": false, "explanation": "“迟缓”形容动作或速度慢，与“普遍”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不光滑，与“普遍”的范围广不构成反义。"}], "correct_answer": "个别", "explanations": {"个别": "正确。“个别”指少数、不普遍，与“普遍”构成反义关系。", "清淡": "“清淡”形容味道或颜色淡，与“普遍”的意思无关，不构成反义。", "迟缓": "“迟缓”形容动作或速度慢，与“普遍”没有反义关系。", "粗糙": "“粗糙”形容表面不光滑，与“普遍”的范围广不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是到处都有，很多地方都一样。", "primary_collocate": null, "pronunciation": "pǔ biàn", "ipa": "pʰu˨˩˦ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "现在手机在年轻人中很普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种情况在大城市很普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题很普遍，很多学校都有。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上网看书已经变得很普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑自行车在这里非常普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "普遍的看法是，早睡对身体好。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个习惯在老人中不太普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生用电脑上课，现在很普遍了。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一个普遍的问题，不只你有。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花在南方很普遍，到处都能看到。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "普遍地", "label": "副词形式"}, {"form": "普遍性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "存在范围很广，到处都有、大家都这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ee3da4-4c99-4c2d-aaed-c51fb6a3dd04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普遍", "is_correct": true, "explanation": "正确。“普遍”指到处都有、很多人都这样，与“现在手机在年轻人中很普遍”相符。"}, {"text": "罕见", "is_correct": false, "explanation": "语义：“罕见”指很少见，与“现在手机在年轻人中”的广泛使用相矛盾。"}, {"text": "寂寞", "is_correct": false, "explanation": "搭配：“寂寞”形容人的心情，手机不会感到寂寞，不能这样形容它。"}, {"text": "缓慢", "is_correct": false, "explanation": "搭配：“缓慢”形容速度或动作慢，不能用来描述手机的普及程度。"}], "explanations": {"普遍": "正确。“普遍”指到处都有、很多人都这样，与“现在手机在年轻人中很普遍”相符。", "罕见": "语义：“罕见”指很少见，与“现在手机在年轻人中”的广泛使用相矛盾。", "寂寞": "搭配：“寂寞”形容人的心情，手机不会感到寂寞，不能这样形容它。", "缓慢": "搭配：“缓慢”形容速度或动作慢，不能用来描述手机的普及程度。"}, "sentence_index": 0, "correct_answer": "普遍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜很普遍，别的店都没有这样的做法。", "explanation": "这里应该用〈独特〉。普遍指很多地方、很多人都有，与“别的店都没有”的意思相反；只说一家的特色要用独特。"}, {"text": "他只是个普遍的工人，没什么特别的经历。", "explanation": "这里应该用〈普通〉。普遍强调范围广，形容人平凡、一般要用普通。"}, {"text": "昨天的会议很普遍，是我们第一次在湖边开的。", "explanation": "这里应该用〈特殊〉。普遍指很多地方都有，单次活动不能说普遍；表示与众不同要用特殊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普遍", "is_correct": true, "explanation": "正确。“不太普遍”指在老人中并不多见，与句意一致。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄，不能用来形容习惯。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，习惯没有体形，不能这样说。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”指声音大而清楚，与“习惯在老人中是否多见”无关。"}], "explanations": {"普遍": "正确。“不太普遍”指在老人中并不多见，与句意一致。", "年轻": "搭配：“年轻”说人的年龄，不能用来形容习惯。", "高大": "体貌：“高大”形容人或物的体形，习惯没有体形，不能这样说。", "响亮": "语义：“响亮”指声音大而清楚，与“习惯在老人中是否多见”无关。"}, "sentence_index": 6, "correct_answer": "普遍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那次意外是普遍的，没人预料到。", "explanation": "这里应该用〈偶然〉。普遍指范围广、到处都有，单次意外不能说普遍；偶然发生的事要用偶然。"}, {"text": "这所学校有一个普遍的实验室。", "explanation": "这里应该用〈专门〉。普遍指范围广，形容单个设施不合适；为某项用途设立的要用专门。"}, {"text": "这里只有普遍的几户人家。", "explanation": "这里应该用〈零星〉。普遍指很多地方都有，少量分散的几户不能说普遍；形容分散稀少要用零星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种现象在城市里很普遍性。", "corrected_sentence": "这种现象在城市里很普遍。", "error_description": "词性错误：“普遍性”是名词，不能作“很”之后的形容词谓语，应说“很普遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个普遍地现象，很多人都见过。", "corrected_sentence": "这是一个普遍的现象，很多人都见过。", "error_description": "助词错误：修饰名词“现象”时要用“的”，不能用副词用的“地”，应说“普遍的现象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "反义：“大”与“小”相对，表示东西的体积、尺寸超过比较对象。"}, {"text": "慢", "is_correct": false, "explanation": "无关：“慢”指速度低，与“小”不构成反义或近义关系。"}, {"text": "厚", "is_correct": false, "explanation": "无关：“厚”指物体两面之间的距离大，与“小”没有反义关系。"}, {"text": "冷", "is_correct": false, "explanation": "无关：“冷”指温度低，与“小”不构成反义关系。"}], "correct_answer": "大", "explanations": {"大": "反义：“大”与“小”相对，表示东西的体积、尺寸超过比较对象。", "慢": "无关：“慢”指速度低，与“小”不构成反义或近义关系。", "厚": "无关：“厚”指物体两面之间的距离大，与“小”没有反义关系。", "冷": "无关：“冷”指温度低，与“小”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "反义：“大”与“小”相对，表示东西的体积、尺寸超过比较对象。"}, {"text": "远", "is_correct": false, "explanation": "无关：“远”指距离长，与“小”不构成反义或近义关系。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”指质地坚实，与“小”没有反义关系。"}, {"text": "重", "is_correct": false, "explanation": "无关：“重”指分量大，与“小”不构成反义关系。"}], "correct_answer": "大", "explanations": {"大": "反义：“大”与“小”相对，表示东西的体积、尺寸超过比较对象。", "远": "无关：“远”指距离长，与“小”不构成反义或近义关系。", "硬": "无关：“硬”指质地坚实，与“小”没有反义关系。", "重": "无关：“重”指分量大，与“小”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示东西不大。", "primary_collocate": null, "pronunciation": "xiǎo", "ipa": "ɕjɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个盒子太小，装不下书。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张桌子很小，只能坐两个人。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手机屏幕很小。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个苹果比那个小。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的书包太小了，放不下水瓶。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子对大人来说太小。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个蛋糕很小，一个人就能吃完。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小的那个箱子是我的。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这双鞋有点小，走路脚疼。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外的花园很小，树也都很矮。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小小", "label": "重叠"}], "register": "中性", "sense_fingerprint": "具体东西的个头、尺寸不大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 书包 (Zipf 3.62), 不下 (Zipf 3.94), 水瓶 (Zipf 3.14)']::text[], '7441cee5-2e00-483a-8d58-1c3e5c5576de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小", "is_correct": true, "explanation": "本词：小（xiǎo，第三声），表示东西不大。"}, {"text": "校", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“学校”。"}, {"text": "消", "is_correct": false, "explanation": "声调不同：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是“消除”。"}, {"text": "想", "is_correct": false, "explanation": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“想念”。"}, {"text": "效", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“效果”。"}], "explanations": {"小": "本词：小（xiǎo，第三声），表示东西不大。", "校": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“学校”。", "消": "声调不同：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是“消除”。", "想": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“想念”。", "效": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“效果”。"}, "sentence_index": null, "correct_answer": "小"}, "level_3": {"options": [{"text": "小", "is_correct": true, "explanation": "正确：“盒子太小”指盒子的容积不够，“小”与“装不下书”相符。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能修饰“盒子”。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线充足，与“装不下书”的容量义无关，句意不通。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”指速度低，与“盒子”的容量无关，句意不通。"}], "explanations": {"小": "正确：“盒子太小”指盒子的容积不够，“小”与“装不下书”相符。", "甜": "搭配：“甜”形容味道，不能修饰“盒子”。", "亮": "语义：“亮”指光线充足，与“装不下书”的容量义无关，句意不通。", "慢": "语义：“慢”指速度低，与“盒子”的容量无关，句意不通。"}, "sentence_index": 0, "correct_answer": "小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家离学校很小，要坐一个小时车。", "explanation": "这里应该用〈远〉。“小”说东西的体积、尺寸不大，说距离要用“远”，“离学校很小”不这么说。"}, {"text": "他们之间的感情很小，几乎不往来。", "explanation": "这里应该用〈淡〉。“小”说东西的大小，不说感情的深浅；感情淡薄要用“淡”，“感情很小”不这么用。"}, {"text": "这个箱子的价钱很小，我买不起。", "explanation": "这里应该用〈高〉。“小”说东西的大小，不说价钱高低；价钱高要用“高”，“价钱很小”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小", "is_correct": true, "explanation": "本词：小（xiǎo，第三声），表示东西不大。"}, {"text": "笑", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“笑”。"}, {"text": "脚", "is_correct": false, "explanation": "声母不同：jiǎo 的声母是 j，xiǎo 的声母是 x，意思是“脚”。"}, {"text": "险", "is_correct": false, "explanation": "韵母不同：xiǎn 的韵母是 -an，xiǎo 的韵母是 -ao，意思是“危险”。"}, {"text": "享", "is_correct": false, "explanation": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“享受”。"}], "explanations": {"小": "本词：小（xiǎo，第三声），表示东西不大。", "笑": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“笑”。", "脚": "声母不同：jiǎo 的声母是 j，xiǎo 的声母是 x，意思是“脚”。", "险": "韵母不同：xiǎn 的韵母是 -an，xiǎo 的韵母是 -ao，意思是“危险”。", "享": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“享受”。"}, "sentence_index": null, "correct_answer": "小"}, "level_3": {"options": [{"text": "小", "is_correct": true, "explanation": "正确：“蛋糕很小”指蛋糕的体积不大，与“一个人就能吃完”相符。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”形容距离，不能用来修饰“蛋糕”。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能形容蛋糕。"}, {"text": "暖", "is_correct": false, "explanation": "语义：“暖”指温度，与“一个人就能吃完”的份量义无关，句意不通。"}], "explanations": {"小": "正确：“蛋糕很小”指蛋糕的体积不大，与“一个人就能吃完”相符。", "远": "搭配：“远”形容距离，不能用来修饰“蛋糕”。", "瘦": "体貌：“瘦”形容人或动物的身材，不能形容蛋糕。", "暖": "语义：“暖”指温度，与“一个人就能吃完”的份量义无关，句意不通。"}, "sentence_index": 6, "correct_answer": "小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在车站停留的时间很小，就出发了。", "explanation": "这里应该用〈短〉。“小”说东西的大小，不说时间长短；时间短要用“短”，“停留时间很小”不这么用。"}, {"text": "这间屋子的温度很小，大家都冷得发抖。", "explanation": "这里应该用〈低〉。“小”说东西的大小，不说温度高低，温度低要用“低”，“温度很小”不这么用。"}, {"text": "这列火车跑得很小。", "explanation": "这里应该用〈快〉。“小”说东西的大小，不用来形容“跑得”的快慢；说快慢要用“快”或“慢”，“跑得很小”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只鞋小穿不进去。", "corrected_sentence": "这只鞋小得穿不进去。", "error_description": "补语错误：“小”作谓语时后接补语“穿不进去”，中间须用“得”连接，应说“小得穿不进去”；漏掉“得”，“小穿不进去”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只碗小很，装不下这么多汤。", "corrected_sentence": "这只碗很小，装不下这么多汤。", "error_description": "位置错误：“很”是程度副词，应放在形容词前，说“很小”，不说“小很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国内", "is_correct": true, "explanation": "与“国际”相对，指一国之内，不涉及不同国家之间的事务，二者构成反义。"}, {"text": "严格", "is_correct": false, "explanation": "形容要求高、不宽松，与“国际”没有反义关系。"}, {"text": "委婉", "is_correct": false, "explanation": "形容说话含蓄、不直接，与“国际”没有反义关系。"}, {"text": "富裕", "is_correct": false, "explanation": "形容经济条件好、财产多，与“国际”没有反义关系。"}], "correct_answer": "国内", "explanations": {"国内": "与“国际”相对，指一国之内，不涉及不同国家之间的事务，二者构成反义。", "严格": "形容要求高、不宽松，与“国际”没有反义关系。", "委婉": "形容说话含蓄、不直接，与“国际”没有反义关系。", "富裕": "形容经济条件好、财产多，与“国际”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国内", "is_correct": true, "explanation": "与“国际”相对，指一国之内，不涉及不同国家之间的事务，二者构成反义。"}, {"text": "迟钝", "is_correct": false, "explanation": "形容反应慢、感觉不灵敏，与“国际”没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "形容性情或态度平和，与“国际”没有反义关系。"}, {"text": "亲切", "is_correct": false, "explanation": "形容态度和蔼、让人感到温暖，与“国际”没有反义关系。"}], "correct_answer": "国内", "explanations": {"国内": "与“国际”相对，指一国之内，不涉及不同国家之间的事务，二者构成反义。", "迟钝": "形容反应慢、感觉不灵敏，与“国际”没有反义关系。", "温和": "形容性情或态度平和，与“国际”没有反义关系。", "亲切": "形容态度和蔼、让人感到温暖，与“国际”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "指不同国家之间的事情。", "primary_collocate": null, "pronunciation": "guó jì", "ipa": "kwo˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "国际上，很多国家都在帮助这个地方。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际关系越来越好，两国来往也多了。", "target_word": "国际", "complexity_tier": "T3", "furigana": "guó jì guān xì yuè lái yuè hǎo liǎng guó lái wǎng yě duō le", "sentence_source": "generated"}, {"text": "他对国际问题很感兴趣。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国际组织帮助贫困的儿童。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际形势会影响各国的经济。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "整个国际社会都希望和平。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条国际规定要求所有国家遵守。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际合作让环境变得更干净。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际事务不是一个国家能解决的。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在国际机构工作了五年。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "国际化", "label": "复合"}, {"form": "国际象棋", "label": "复合"}, {"form": "國際", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不同国家之间的事务、关系与局势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0f7a4f-5379-4dcd-92b3-4e8d45a14fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确答案。国际读作 guó jì，指不同国家之间的事情。"}, {"text": "国籍", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是国籍。"}, {"text": "国企", "is_correct": false, "explanation": "qǐ 与 jì 声母不同（q 与 j），声调也不同，意思是国有企业。"}, {"text": "过季", "is_correct": false, "explanation": "guò（第四声）与 guó（第二声）声调不同，意思是过了季节。"}, {"text": "国境", "is_correct": false, "explanation": "jìng 比 jì 多了韵尾 ng，意思是国家的边界。"}], "explanations": {"国际": "正确答案。国际读作 guó jì，指不同国家之间的事情。", "国籍": "jí（第二声）与 jì（第四声）声调不同，意思是国籍。", "国企": "qǐ 与 jì 声母不同（q 与 j），声调也不同，意思是国有企业。", "过季": "guò（第四声）与 guó（第二声）声调不同，意思是过了季节。", "国境": "jìng 比 jì 多了韵尾 ng，意思是国家的边界。"}, "sentence_index": null, "correct_answer": "国际"}, "level_3": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确：“国际上”指在国与国之间的范围，与“很多国家都在帮助”相符。"}, {"text": "农村", "is_correct": false, "explanation": "语义：“农村上”不是有效的处所，且与“很多国家”的范围不相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“学校上”只指一所学校，与“很多国家帮助”的范围矛盾。"}, {"text": "家里", "is_correct": false, "explanation": "搭配：“家里上”不能作处所词，与“上”的用法不搭配。"}], "explanations": {"国际": "正确：“国际上”指在国与国之间的范围，与“很多国家都在帮助”相符。", "农村": "语义：“农村上”不是有效的处所，且与“很多国家”的范围不相符。", "学校": "语义：“学校上”只指一所学校，与“很多国家帮助”的范围矛盾。", "家里": "搭配：“家里上”不能作处所词，与“上”的用法不搭配。"}, "sentence_index": 0, "correct_answer": "国际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国际政府决定增加学校经费。", "explanation": "这里应该用〈国家〉。“国际”指国与国之间，一个政府只属于一个国家，要说“国家政府”。"}, {"text": "这几年国际的天气变化很大。", "explanation": "这里应该用〈全球〉。“国际”指国与国之间，天气变化属于整个地球，要说“全球”。"}, {"text": "国际的农民收入提高了。", "explanation": "这里应该用〈国内〉。“国际”指国与国之间，说一国之内的农民要用“国内”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确：“国际规定”指国与国之间的规定，要求所有国家遵守，与句意相符。"}, {"text": "国内", "is_correct": false, "explanation": "语义：“国内规定”只在一国之内有效，不能要求所有国家遵守。"}, {"text": "地方", "is_correct": false, "explanation": "语义：“地方规定”只约束当地，不能要求所有国家遵守。"}, {"text": "班级", "is_correct": false, "explanation": "搭配：“班级”的规定约束的是学生，不能用来要求国家遵守。"}], "explanations": {"国际": "正确：“国际规定”指国与国之间的规定，要求所有国家遵守，与句意相符。", "国内": "语义：“国内规定”只在一国之内有效，不能要求所有国家遵守。", "地方": "语义：“地方规定”只约束当地，不能要求所有国家遵守。", "班级": "搭配：“班级”的规定约束的是学生，不能用来要求国家遵守。"}, "sentence_index": 6, "correct_answer": "国际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的父母一直住在国际的小城市。", "explanation": "这里应该用〈本国〉。“国际”指国与国之间，说自己国家之内的小城市要用“本国”。"}, {"text": "我家的国际沙发很舒服。", "explanation": "这里应该用〈国产〉。“国际”指国与国之间，说我国自己生产的沙发要用“国产”。"}, {"text": "这个国际的人口超过了一亿。", "explanation": "这里应该用〈地区〉。“国际”指国与国之间，一个地区的人口不能说成“国际的人口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们对国际了事务很关心。", "corrected_sentence": "我们对国际事务很关心。", "error_description": "语法错误：区别词“国际”修饰名词时后面不能加动态助词“了”，应去掉“了”。正确说法是“对国际事务很关心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在国际了机构工作了两年。", "corrected_sentence": "她在国际机构工作了两年。", "error_description": "语法错误：区别词“国际”修饰名词时后面不能加动态助词“了”，应去掉“了”。正确说法是“在国际机构工作了两年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
