INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一些人自己出钱开的公司或工厂。", "primary_collocate": null, "pronunciation": "sī yíng qǐ yè", "ipa": "sɹ̩˥ iŋ˧˥ tɕʰi˨˩˦ je˥˩", "syllable_count": 4, "sentences": [{"text": "他自己出钱开了一家私营企业。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家私营企业只有三个人。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "私营企业的工资有时比较高。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在私营企业工作过。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们几个朋友合开了一家私营企业。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家私营企业生产的鞋很便宜。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想开一家小的私营企业。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家私营企业是我朋友自己办的。", "target_word": "私营企业", "complexity_tier": "T3", "furigana": "zhè jiā sī yíng qǐ yè shì wǒ péngyou zìjǐ bàn de.", "sentence_source": "generated"}, {"text": "哥哥辞职后办了私营企业。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家私营企业的老板很年轻。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "私营企业主", "label": "复合"}, {"form": "私營企業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人自己出钱开办的公司或工厂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0f7a4f-5379-4dcd-92b3-4e8d45a14fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "私营企业", "is_correct": true, "explanation": "正确：私营企业是一些人自己出钱开办的公司或工厂，与“出钱开了一家”相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不能被“开”，也不能说“开了一家老师”。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：量词“家”用于店铺、公司，猫应用“只”，且不能被开办。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景象，不能被出钱开办。"}], "explanations": {"私营企业": "正确：私营企业是一些人自己出钱开办的公司或工厂，与“出钱开了一家”相符。", "老师": "语义：老师是人，不能被“开”，也不能说“开了一家老师”。", "小猫": "搭配：量词“家”用于店铺、公司，猫应用“只”，且不能被开办。", "天空": "语义：天空是自然景象，不能被出钱开办。"}, "sentence_index": 0, "correct_answer": "私营企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一台私营企业。", "explanation": "这里应该用〈家〉。企业用量词“家”，“台”用于机器，不能用于企业。"}, {"text": "我舅舅是私营企业，很有钱。", "explanation": "这里应该用〈私营企业主〉。私营企业指机构，不能指人。"}, {"text": "这家私营企业会员很多，每周都有比赛。", "explanation": "这里应该用〈俱乐部〉。会员和比赛是俱乐部的活动，私营企业指由私人经营的公司，不设会员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "私营企业", "is_correct": true, "explanation": "正确：私营企业是个人出资经营的企业，与“我想开一家小的”相符。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：量词“家”用于店铺、公司，狗应用“只”，不能说“一家小的狗”。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：冬天是时间，不能被“开”。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：火车应用量词“列”或“辆”，不能用“家”。"}], "explanations": {"私营企业": "正确：私营企业是个人出资经营的企业，与“我想开一家小的”相符。", "狗": "搭配：量词“家”用于店铺、公司，狗应用“只”，不能说“一家小的狗”。", "冬天": "语义：冬天是时间，不能被“开”。", "火车": "搭配：火车应用量词“列”或“辆”，不能用“家”。"}, "sentence_index": 6, "correct_answer": "私营企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她小学是在私营企业念的。", "explanation": "这里应该用〈私立学校〉。“私营”用于企业，学校应说“私立”。"}, {"text": "我们的私营企业很爱笑，每天都很开心。", "explanation": "这里应该用〈老板〉。“私营企业”指机构，不会笑，说人很开心要用“老板”。"}, {"text": "这家私营企业是政府出资开的。", "explanation": "这里应该用〈国有企业〉。私营企业由私人出资，政府出资就不能说是私营。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐在一只私营企业当秘书。", "corrected_sentence": "我姐姐在一家私营企业当秘书。", "error_description": "量词错误：“企业”应用量词“家”，“只”用于动物等。错误在“一只”，应改为“一家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸爸以前过开一家私营企业。", "corrected_sentence": "我爸爸以前开过一家私营企业。", "error_description": "体标位置错误：“过”表示经历，应紧跟动词，写作“开过”，不能放在动词前。错误在“过开”，应改为“开过一家私营企业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模拟化", "is_correct": true, "explanation": "反义：“模拟化”指转换为模拟形式，与“数字化”构成反义。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”指随意地慢慢走，与“数字化”的意思不相对。"}, {"text": "煮饭", "is_correct": false, "explanation": "无反义关系：“煮饭”指用水和米做饭，与“数字化”没有对立关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系：“跳舞”指随音乐做动作，与“数字化”不构成反义。"}], "correct_answer": "模拟化", "explanations": {"模拟化": "反义：“模拟化”指转换为模拟形式，与“数字化”构成反义。", "散步": "无反义关系：“散步”指随意地慢慢走，与“数字化”的意思不相对。", "煮饭": "无反义关系：“煮饭”指用水和米做饭，与“数字化”没有对立关系。", "跳舞": "无反义关系：“跳舞”指随音乐做动作，与“数字化”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模拟化", "is_correct": true, "explanation": "反义：“模拟化”指转换为模拟形式，与“数字化”构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：“游泳”指在水中运动，与“数字化”的意思不相对。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”指用声音演唱曲调，与“数字化”没有对立关系。"}, {"text": "骑车", "is_correct": false, "explanation": "无反义关系：“骑车”指骑自行车等交通工具，与“数字化”不构成反义。"}], "correct_answer": "模拟化", "explanations": {"模拟化": "反义：“模拟化”指转换为模拟形式，与“数字化”构成反义。", "游泳": "无反义关系：“游泳”指在水中运动，与“数字化”的意思不相对。", "唱歌": "无反义关系：“唱歌”指用声音演唱曲调，与“数字化”没有对立关系。", "骑车": "无反义关系：“骑车”指骑自行车等交通工具，与“数字化”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西变成用电脑能处理的样子。", "primary_collocate": null, "pronunciation": "shù zì huà", "ipa": "ʂu˥˩ tsɨ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "图书馆想把旧书都数字化。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在把老照片数字化。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些纸上的资料，需要先数字化才能存进电脑。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定把所有合同数字化。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字化以后，文件就不会丢了。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆把很多文物数字化了，大家在网上就能看。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把课本数字化，学生用平板就能读。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行想让更多服务数字化。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把爷爷的旧录音数字化，留给孩子。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要数字化一本旧书，要先一页一页扫描。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数字化了", "label": "体标"}, {"form": "数字化转型", "label": "复合"}], "register": "中性", "sense_fingerprint": "数字化:把东西变成电脑能处理的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a818043-95f1-4634-87a5-2d86d4a18143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数字化", "is_correct": true, "explanation": "正确：“图书馆想把旧书都数字化”指把旧书转换成电脑能处理的形式，符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：书不能被吃掉，与“图书馆想把旧书都”的处理意图不合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能带“旧书”这类物件作宾语，句子讲不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”多用于食物，不能用来处理旧书。"}], "explanations": {"数字化": "正确：“图书馆想把旧书都数字化”指把旧书转换成电脑能处理的形式，符合句意。", "吃掉": "语义：书不能被吃掉，与“图书馆想把旧书都”的处理意图不合。", "唱": "配价：“唱”不能带“旧书”这类物件作宾语，句子讲不通。", "煮": "搭配：“煮”多用于食物，不能用来处理旧书。"}, "sentence_index": 0, "correct_answer": "数字化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这本英文书数字化成了中文。", "explanation": "这里应该用〈翻译〉。数字化指转换为数字形式，不指改变语言，应说“翻译成中文”。"}, {"text": "他把我妈妈做的饭菜数字化了。", "explanation": "这里应该用〈记下〉。数字化的对象须是资料或信息，饭菜是实物，无法转换成数字形式，只能把做法记下来。"}, {"text": "他把这块石头数字化成了雕像。", "explanation": "这里应该用〈雕刻〉。数字化指转换为数字形式，不能用来指把石头雕成雕像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字化", "is_correct": true, "explanation": "正确：“老师把课本数字化”指把课本转成电子形式，学生才能用平板阅读，符合句意。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是破坏纸张的动作，与“学生用平板就能读”的处理结果不合，句意讲不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：课本烧掉后就无法阅读，与“学生用平板就能读”的结果矛盾，句意讲不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象须是饮品，不能带“课本”作宾语，句子讲不通。"}], "explanations": {"数字化": "正确：“老师把课本数字化”指把课本转成电子形式，学生才能用平板阅读，符合句意。", "撕": "语义：撕是破坏纸张的动作，与“学生用平板就能读”的处理结果不合，句意讲不通。", "烧": "语义：课本烧掉后就无法阅读，与“学生用平板就能读”的结果矛盾，句意讲不通。", "喝": "搭配：“喝”的对象须是饮品，不能带“课本”作宾语，句子讲不通。"}, "sentence_index": 6, "correct_answer": "数字化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把坏掉的椅子数字化好了。", "explanation": "这里应该用〈修理〉。数字化指转换为数字形式，不指修好实物。"}, {"text": "他把两人的友情数字化了。", "explanation": "这里应该用〈记住〉。数字化的对象须是资料或信息，友情是情感，无法转换成数字形式，只能记在心里。"}, {"text": "这间屋子用鲜花数字化了一下。", "explanation": "这里应该用〈装饰〉。数字化指转换为数字形式，不指用鲜花美化房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用这些老照片数字化了。", "corrected_sentence": "我们把这些老照片数字化了。", "error_description": "介词错误。“把”引出被处理的对象，“用”不能引出“数字化”的对象，应说“把这些老照片数字化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆正在把旧报纸数字化了。", "corrected_sentence": "图书馆正在把旧报纸数字化。", "error_description": "体标错误。“正在”表示动作正在进行，不能与表示完成的“了”同用。应说“图书馆正在把旧报纸数字化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
