INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来解决一个问题的方法或方式。", "primary_collocate": null, "pronunciation": "jiě jué fāng àn", "ipa": "tɕje˨˩˦ tɕɥe˧˥ faŋ˥ an˥˩", "syllable_count": 4, "sentences": [{"text": "小李终于找到一个解决方案。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法是最好的解决方案。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络出问题了，我们需要解决方案。", "target_word": "解决方案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把解决方案写在纸上。", "target_word": "解决方案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个解决方案很简单，大家都能用。", "target_word": "解决方案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个解决方案不满意。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们试了两个解决方案。", "target_word": "解决方案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的解决方案要容易做到。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁有解决方案，请举手。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我们公司的新解决方案。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "解決方案", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来解决一个问题的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0f7a4f-5379-4dcd-92b3-4e8d45a14fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解决方案", "is_correct": true, "explanation": "正确：“找到一个”后接的是用来解决问题的办法，与“终于”相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能被“找到一个”当作可以找到的物件。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不能被“找到一个”。"}, {"text": "山", "is_correct": false, "explanation": "搭配：量词“座”用于山，不能说“一个山”。"}], "explanations": {"解决方案": "正确：“找到一个”后接的是用来解决问题的办法，与“终于”相符。", "太阳": "语义：太阳是天体，不能被“找到一个”当作可以找到的物件。", "星期": "语义：星期是时间单位，不能被“找到一个”。", "山": "搭配：量词“座”用于山，不能说“一个山”。"}, "sentence_index": 0, "correct_answer": "解决方案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们找到了一只解决方案。", "explanation": "这里应该用〈个〉。“解决方案”用量词“个”或“套”，不用“只”。"}, {"text": "这次考试是一个很大的解决方案。", "explanation": "这里应该用〈难题〉。“解决方案”指解决问题的办法，考试本身是难题，不能说解决方案。"}, {"text": "这次数学竞赛的解决方案是三十二。", "explanation": "这里应该用〈答案〉。解决方案指针对问题的办法，数值结果要说答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解决方案", "is_correct": true, "explanation": "正确：“试了两个”后接的是可以试用的办法，只有“解决方案”合适。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能被“试”。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不能说“试了两个小说”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱应用量词“台”，且“试”不接大件家电。"}], "explanations": {"解决方案": "正确：“试了两个”后接的是可以试用的办法，只有“解决方案”合适。", "天气": "语义：天气是自然现象，不能被“试”。", "小说": "语义：小说是文学作品，不能说“试了两个小说”。", "冰箱": "搭配：冰箱应用量词“台”，且“试”不接大件家电。"}, "sentence_index": 6, "correct_answer": "解决方案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯糖水是糖的解决方案。", "explanation": "这里应该用〈溶液〉。化学上糖溶于水形成的混合液叫溶液，“解决方案”指针对问题的办法。"}, {"text": "我们明天的解决方案排得很满。", "explanation": "这里应该用〈计划〉。“解决方案”针对问题，安排日程要说计划。"}, {"text": "这次调查的解决方案说明大家都很累。", "explanation": "这里应该用〈结论〉。“说明”后接的是结论，解决方案是针对问题的办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们找到了一本新的解决方案。", "corrected_sentence": "他们找到了一个新的解决方案。", "error_description": "量词错误：“解决方案”用“个”或“套”，“本”用于书册。错误在“一本”，应改为“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们需要一个新地解决方案。", "corrected_sentence": "我们需要一个新的解决方案。", "error_description": "结构助词错误：形容词作定语修饰名词时用“的”，不用“地”。错误在“新地”，应改为“新的解决方案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
