INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把很多人或东西安排在一起，让他们一起做事情。", "primary_collocate": null, "pronunciation": "zǔ zhī", "ipa": "tsu˨˩˦ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "学校组织学生去爬山。", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末，公司组织我们去旅行。", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师组织大家打扫教室。", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在组织一场比赛。", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区组织了一次文艺活动。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来组织这次聚会？", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想组织朋友们一起吃饭。", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她组织孩子们排好队。", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司组织过两次培训。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把组织会议的工作交给了我。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "组织了", "label": "体标"}, {"form": "组织过", "label": "体标"}, {"form": "组织者", "label": "复合"}, {"form": "組織", "label": "繁体"}], "register": "中性", "sense_fingerprint": "安排很多人一起做某件事或参加活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0f7a4f-5379-4dcd-92b3-4e8d45a14fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组织", "is_correct": true, "explanation": "正确：“组织学生去爬山”指安排学生一起去爬山，与句意相符。"}, {"text": "拆散", "is_correct": false, "explanation": "语义：“拆散学生”是打散学生，与安排学生一起活动的意思相反。"}, {"text": "解散", "is_correct": false, "explanation": "搭配：“解散”不能与“学生去爬山”搭配，不能表示安排活动。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁学生”说法荒谬，与学校安排活动的意思无关。"}], "explanations": {"组织": "正确：“组织学生去爬山”指安排学生一起去爬山，与句意相符。", "拆散": "语义：“拆散学生”是打散学生，与安排学生一起活动的意思相反。", "解散": "搭配：“解散”不能与“学生去爬山”搭配，不能表示安排活动。", "销毁": "语义：“销毁学生”说法荒谬，与学校安排活动的意思无关。"}, "sentence_index": 0, "correct_answer": "组织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重组织了三公斤。", "explanation": "这里应该用〈增加〉。“组织”指安排人一起做事，体重的变化要用“增加”。"}, {"text": "妈妈组织了一只小猫。", "explanation": "这里应该用〈养〉。“组织”指安排人或事物一起做事，养宠物要用“养”。"}, {"text": "妈妈每天都组织屋子。", "explanation": "这里应该用〈整理〉。“组织”指安排人或事物一起做事，收拾屋子要用“整理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组织", "is_correct": true, "explanation": "正确：“组织朋友们一起吃饭”指安排大家聚餐，与句意相符。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”的对象是纸张、书册，不能说“装订朋友们”。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件，不能说“打印朋友们”。"}, {"text": "发射", "is_correct": false, "explanation": "搭配：“发射”的对象是火箭、卫星等，不能说“发射朋友们”。"}], "explanations": {"组织": "正确：“组织朋友们一起吃饭”指安排大家聚餐，与句意相符。", "装订": "搭配：“装订”的对象是纸张、书册，不能说“装订朋友们”。", "打印": "搭配：“打印”的对象是文件，不能说“打印朋友们”。", "发射": "搭配：“发射”的对象是火箭、卫星等，不能说“发射朋友们”。"}, "sentence_index": 6, "correct_answer": "组织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们组织了操场。", "explanation": "这里应该用〈打扫〉。“组织”指安排人一起做事，清理操场要用“打扫”。"}, {"text": "他很快组织了这门技术。", "explanation": "这里应该用〈掌握〉。“组织”指安排人或事物一起做事，学会技术要用“掌握”。"}, {"text": "他组织了一条鱼。", "explanation": "这里应该用〈钓〉。“组织”指安排人或事物一起做事，钓鱼要用“钓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长组织把大家去打扫教室。", "corrected_sentence": "班长组织大家去打扫教室。", "error_description": "“把”字位置错误：“组织”后直接带兼语“大家去打扫教室”，“把”不能插在动词和兼语之间，多出的“把”应删去。错误形式是“组织把大家”，正确形式是“组织大家”，正确说法是“班长组织大家去打扫教室。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师组织得学生去爬山。", "corrected_sentence": "老师组织好学生去爬山。", "error_description": "补语形式错误：“组织”后应接结果补语“好”，写作“组织好学生”，不能用可能补语标记“得”。错误在“得”，应改为“好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0ee4ff-37d6-4860-bbb0-c876dcbe1f78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
