INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21768, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "区块是一块区域，比如小区被分成很多块。", "primary_collocate": null, "pronunciation": "qū kuài", "ipa": "tɕʰy˥ kʰuai̯˥˩", "syllable_count": 2, "sentences": [{"text": "这个区块有三栋楼和一个小花园。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，红色的区块是新开的公园。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把这个区块打扫干净。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区块的房子比那个区块贵。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府把老城分成了五个区块。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在图上圈出你家所在的区块。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区块晚上很安静，适合住人。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个区块正在修路，车不能进去。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在东边的区块，离学校很近。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上画了四个区块，每个区块写一个名字。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "区块链", "label": "复合"}], "register": "中性", "sense_fingerprint": "区块：被划分出来的一块区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23eec3b-6256-4fda-81a7-c349d8b21264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区块", "is_correct": true, "explanation": "“区块”指住宅区中划分出的一块区域，有三栋楼和小花园，与句意相合。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子不能有三栋楼和小花园，与句中描述的住宅环境不合。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是书，不能有楼和花园。"}, {"text": "音符", "is_correct": false, "explanation": "搭配：“有三栋楼”需要能容纳建筑的地方作主语，“音符”不能作此主语。"}], "explanations": {"区块": "“区块”指住宅区中划分出的一块区域，有三栋楼和小花园，与句意相合。", "句子": "语义：句子不能有三栋楼和小花园，与句中描述的住宅环境不合。", "词典": "语义：词典是书，不能有楼和花园。", "音符": "搭配：“有三栋楼”需要能容纳建筑的地方作主语，“音符”不能作此主语。"}, "sentence_index": 0, "correct_answer": "区块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个区块的股票涨得很快。", "explanation": "这里应该用〈板块〉。板块指股市中按行业划分的一类股票；“区块”不用于股票分类，也不指住宅区。"}, {"text": "这个区块有三层，每层住了八户。", "explanation": "这里应该用〈楼栋〉。楼栋指一幢建筑，有层数；“区块”指一片区域，不指单幢楼，不能说有几层。"}, {"text": "这条区块的房子比那条区块贵。", "explanation": "这里应该用〈个〉。区块的量词用“个”，“条”用于长条形的东西，不用于区块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区块", "is_correct": true, "explanation": "“区块”指住宅区中划分出的一块地方，晚上安静、适合住人，与句意相合。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能住人，也谈不上“晚上安静、适合住人”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是地方，不能作“适合住人”的主语。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“适合住人”搭配的主语须是地方，“天空”不能与之搭配。"}], "explanations": {"区块": "“区块”指住宅区中划分出的一块地方，晚上安静、适合住人，与句意相合。", "海洋": "语义：海洋不能住人，也谈不上“晚上安静、适合住人”。", "歌曲": "语义：歌曲不是地方，不能作“适合住人”的主语。", "天空": "搭配：“适合住人”搭配的主语须是地方，“天空”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "区块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个论坛有十个区块，每个区块讨论一个话题。", "explanation": "这里应该用〈版块〉。版块指论坛或报纸中的分类栏目；“区块”指住宅区这类划分出的地方，不用于论坛分类。"}, {"text": "这个区块的卧室朝南，采光很好。", "explanation": "这里应该用〈住房〉。住房指一套房子，有卧室；“区块”指一片区域，不能说区块有卧室。"}, {"text": "这首歌有四个区块，每个区块都是一段副歌。", "explanation": "这里应该用〈段落〉。段落指乐曲或文章中划分出的部分；“区块”指一片地方，不用于乐曲的分段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条区块的公园很大，孩子们经常去那里玩。", "corrected_sentence": "这个区块的公园很大，孩子们经常去那里玩。", "error_description": "量词错误：“区块”应搭配量词“个”，“这条区块”是错误的，“条”不用于计量区块。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条区块的学校很好，很多家长都想搬过去。", "corrected_sentence": "那个区块的学校很好，很多家长都想搬过去。", "error_description": "量词错误：“区块”应搭配量词“个”，“那条区块”是错误的，“条”不用于计量区块。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21770, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "固定", "is_correct": true, "explanation": "正确：「固定」与「移动」是反义，指不能挪动的。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：「明亮」形容光线，与挪动无关。"}, {"text": "善良", "is_correct": false, "explanation": "无关：「善良」形容人品，与挪动无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：「清楚」形容明白，与挪动无关。"}], "correct_answer": "固定", "explanations": {"固定": "正确：「固定」与「移动」是反义，指不能挪动的。", "明亮": "无关：「明亮」形容光线，与挪动无关。", "善良": "无关：「善良」形容人品，与挪动无关。", "清楚": "无关：「清楚」形容明白，与挪动无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12c70ff4-bc45-420f-aa00-0997336be39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
